window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["anki:hematologia-introducao-ao-estudo-das-anemias"]={"block":"anki:hematologia-introducao-ao-estudo-das-anemias","label":"Anki · Introdução ao Estudo das Anemias","count":90,"questions":[{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-03b3561df5061a71","number":"1001a","sourceNumber":"1001a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"São causas de anemia normocítica.","options":{"A":"Doença renal, doença crônica.","B":"Deficiência de ferro, lesão medular.","C":"Mielodisplasia, talassemia minor.","D":"Anemia sideroblástica, anemia hemolítica."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Esquema rápido - Anemia normocítica\n\n📌 Anemia normocítica\n\n➡️ Definição: Eritrócitos normais em tamanho (VCM 80-100 fL), mas reduzidos em número 🩺\n\n🔍 Causas: Doença renal (menos eritropoetina) + doença crônica (inflamação inibe produção) ✅\n\n➡️ Outros exemplos: Hemólise aguda, aplasia medular.\n\n➡️ Diferencial: Microcítica (ferro, talassemia) / Macrocítica (B12, folato).\n\n💡 Dica visual: Imagine glóbulos \"normais\" parados por rins doentes ou inflamação crônica!\n\nComentário breve\n\nCorreta (doença renal, doença crônica): Doença renal reduz eritropoetina, e doenças crônicas (ex.: inflamações) suprimem produção de eritrócitos, ambas normocíticas.\n\nErrada (deficiência de ferro, lesão medular): Deficiência de ferro é microcítica; lesão medular pode ser normocítica (aplasia), mas não é típico com ferro.\n\nErrada (anemia sideroblástica, hemolítica): Sideroblástica é geralmente microcítica; hemolítica pode ser normocítica, mas não combina como par típico.\n\nErrada (mielodisplasia, talassemia minor): Mielodisplasia pode ser normocítica, mas talassemia minor é microcítica.\n\nAlternativas\n\nDeficiência de ferro, lesão medular → ❌ Ferro é microcítica, lesão não é par típico.\n\nAnemia sideroblástica, hemolítica → ❌ Sideroblástica é microcítica, hemolítica varia.\n\nDoença renal, doença crônica → ✅ Ambas normocíticas, causas comuns.\n\nMielodisplasia, talassemia minor → ❌ Talassemia é microcítica.\n\nGabarito\n\nDoença renal, doença crônica.\n\nMnemônico para lembrar\n\n\"RINS CRÔNICOS\"\n\nRINS: Doença renal (menos eritropoetina).\n\nCRÔNICOS: Doença crônica (inflamação).\n\n💡 Pense em \"rins cansados\" de doença crônica parando glóbulos normais! 🩺😴","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885704","ankiGuid":"j-QU8A{DE{"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-dd722d0faee712d1","number":"1002a","sourceNumber":"1002a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Paciente masculino, 38 anos de idade, procurou atendimento médico devido à astenia. Observado quadro de anemia com dosagem de reticulócitos alta. São causas possíveis da anemia desse paciente, exceto:","options":{"A":"Deficiência de G6PD.","B":"Deficiência de ferro.","C":"Esferocitose hereditária.","D":"Hiperesplenismo."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":["question_bank/media/hematologia-introducao-ao-estudo-das-anemias/paste-bb5922fa30716ba415304fc5af1e96429712375a.jpg","question_bank/media/hematologia-introducao-ao-estudo-das-anemias/paste-6d689b8695a7b231c30b8b643f6dfb5842e0096b.jpg","question_bank/media/hematologia-introducao-ao-estudo-das-anemias/paste-d92f5b5c2e36a00c72a1c1ba4855b6d8e43364dc.jpg","question_bank/media/hematologia-introducao-ao-estudo-das-anemias/paste-c47d12b88442adb3e5e8808c37144bfd4530252f.jpg","question_bank/media/hematologia-introducao-ao-estudo-das-anemias/paste-52f2a6a099c4117e5b300d2d957023be08706696.jpg"],"comment":"Classificação da Questão 🟡\n\nDificuldade: Média (Amarela).\n\nJustificativa: A questão exige conhecimento sobre causas de anemia com reticulócitos altos (hemólise ou perda sanguínea) e a exclusão de uma causa com reticulócitos baixos (deficiência de ferro). O raciocínio é intermediário, pois envolve diagnóstico diferencial.\n\nResumo Essencial 📝\n\nA causa que não explica a anemia com reticulócitos altos é a deficiência de ferro. Reticulócitos altos indicam anemia hemolítica ou perda sanguínea, enquanto a deficiência de ferro causa anemia hipoproliferativa (reticulócitos baixos).\n\nExplicação do Gabarito ✅❌\n\nEsferocitose hereditária ✅: Causa possível.\n\nEsferocitose hereditária é uma anemia hemolítica (defeito na membrana dos eritrócitos), levando a hemólise extravascular (esplenomegalia).\n\nReticulócitos estão altos devido à compensação medular pela destruição de eritrócitos; compatível com o quadro. 🩺\n\nDeficiência de ferro ❌: Não causa.\n\nDeficiência de ferro causa anemia microcítica hipoproliferativa (produção medular reduzida), com reticulócitos baixos, não altos.\n\nReticulócitos altos indicam hemólise ou perda sanguínea, o que não ocorre na deficiência de ferro (ex.: anemia ferropriva por sangramento já foi corrigida, e o paciente não está sangrando ativamente).\n\nVisualização: Deficiência de ferro “freia” a produção de eritrócitos, então reticulócitos são baixos – incompatível com o quadro. 🩺🚫\n\nHiperesplenismo ✅: Causa possível.\n\nHiperesplenismo (esplenomegalia, ex.: cirrose, talassemia) causa anemia por hemólise extravascular, com destruição de eritrócitos no baço.\n\nA medula compensa aumentando a produção, elevando os reticulócitos; compatível com o quadro. 🩺\n\nDeficiência de G6PD ✅: Causa possível.\n\nDeficiência de G6PD causa anemia hemolítica aguda (hemólise intravascular) após gatilhos (ex.: favas, drogas como primaquina).\n\nDurante a crise hemolítica, os reticulócitos ficam altos devido à resposta medular; compatível com o quadro. 🩺\n\nFoco nos Termos 🔬\n\nReticulócitos altos: Indicam aumento da produção de eritrócitos pela medula, típico de anemias hemolíticas (esferocitose, G6PD, hiperesplenismo) ou perda sanguínea aguda; índice de reticulócitos corrigido >2% confirma. 🩺\n\nDeficiência de ferro: Anemia microcítica (VCM <80 fL), hipoproliferativa; reticulócitos baixos (produção reduzida); ferritina baixa e saturação de transferrina baixa confirmam. 🩺\n\nEsferocitose hereditária: Anemia hemolítica; esferócitos no esfregaço, teste de Coombs negativo, reticulócitos altos, bilirrubina indireta elevada (hemólise). 🩺\n\nHiperesplenismo: Destruição de eritrócitos no baço (hemólise extravascular); anemia, reticulócitos altos, esplenomegalia; pode ser secundário a cirrose ou trombose da veia porta. 🩺\n\nDeficiência de G6PD: Hemólise intravascular após estresse oxidativo; reticulócitos altos na crise, mordedura de eritrócitos no esfregaço, teste de G6PD confirma (após crise). 🩺\n\nConexão clínica: Paciente com anemia e reticulócitos altos precisa de investigação para hemólise: esfregaço periférico (esferócitos, mordedura), bilirrubina, haptoglobina, teste de Coombs; deficiência de ferro é descartada por reticulócitos baixos.\n\nSemiologia 🩺\n\nHemólise: Astenia, icterícia (bilirrubina indireta), palidez, esplenomegalia (esferocitose, hiperesplenismo); urina escura na G6PD (hemoglobinúria). 🩺\n\nDeficiência de ferro: Palidez, glossite, queilose; reticulócitos baixos, incompatível com o quadro. 🩺\n\nFisiopatologia 📊\n\nMecanismo da anemia com reticulócitos altos:\n\nHemólise (esferocitose, G6PD, hiperesplenismo) -> Destruição de eritrócitos -> Medula compensa -> Reticulócitos ↑.\n\nDeficiência de ferro: ↓ Produção -> Reticulócitos ↓.\n\nDiagrama: Hemólise -> Reticulócitos ↑; Deficiência de ferro -> Reticulócitos ↓.\n\nContexto adicional: Reticulócitos altos também podem ocorrer após reposição de ferro em anemia ferropriva (fase de recuperação), mas o quadro atual não sugere isso.\n\nElementos Dinâmicos ✨\n\nConceito adicional: O índice de produção de reticulócitos (IPR) ajusta os reticulócitos para o grau de anemia; IPR >2 indica hemólise ou sangramento, IPR <2 indica hipoproliferação (ex.: deficiência de ferro).\n\nCuriosidade: A esferocitose hereditária é a anemia hemolítica mais comum em populações do norte da Europa (prevalência 1:2.000).\n\nMnemônico: Para reticulócitos altos: “H.E.G.” – Hemólise (esferocitose, G6PD), Esplenomegalia (hiperesplenismo).\n\nFrase ilustrativa: “Reticulócitos altos: hemólise sim, deficiência de ferro não!”\n\nDicas de Estudo 🔍\n\nVídeos: Busque no YouTube vídeos sobre “anemia hemolítica reticulócitos” ou “esferocitose hereditária”.\n\nImagens: Pesquise no Google Imagens por “esfregaço esferocitose” ou “mordedura eritrócitos G6PD”.\n\nGuias: Consulte livros de hematologia (ex.: Hoffman’s Hematology) ou clínica médica (ex.: Harrison’s Principles of Internal Medicine).","tags":["#AnemiaHemolítica","#Esferocitose","#G6PD","#Hematologia","#Reticulócitos","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885705","ankiGuid":"KuCUby**Wc"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-10a2fec4ecddf586","number":"1003a","sourceNumber":"1003a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Homem, 50 anos, refere cansaço progressivo nos últimos 6 meses, contudo sem sintomas respiratórios. Exame físico: hipocorado. Hematócrito (Ht) = 45% há cerca de um ano. Exames laboratoriais recentes: Ht = 25%; reticulócitos = 4%; ferritina = 300µg/L. Exame do sangue periférico: macro ovalocitose; policromatofilia e vários neutrófilos com seis segmentos ou mais. A hipótese diagnóstica mais provável é:","options":{"A":"hemólise intravascular","B":"anemia megaloblástica","C":"hemólise extravascular","D":"sangramento gastrointestinal oculto"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Nível: 🟡 Média\nCobra interpretação de anemia + morfologia no esfregaço + integração com reticulócitos e ferritina.\n\nResumo essencial\n\nAnemia macrocítica + neutrófilos hipersegmentados + macro-ovalócitos = padrão clássico de anemia megaloblástica.\n\nCorreção direta\n\n✅ Anemia megaloblástica\n\nAchados-chave:\n\nMacro-ovalócitos\n\nNeutrófilos hipersegmentados (≥5–6 lóbulos)\n\nReticulócitos discretamente ↑ (ineficácia medular)\n\nEtiologias comuns: deficiência de vitamina B12 ou folato\n\nErros principais das incorretas\n\n❌ Hemólise intravascular: esperaria ↑ reticulócitos mais acentuado + esquizócitos, não hipersegmentação.\n❌ Hemólise extravascular: típico de esferócitos, não macro-ovalócitos.\n❌ Sangramento GI oculto: anemia microcítica/ferropriva (ferritina baixa, não alta).\n\nFisiopatologia-chave\n\nDeficiência de B12/folato → defeito na síntese de DNA\n→ maturação nuclear lenta → células grandes (megaloblastos)\n→ afeta também neutrófilos → hipersegmentação\n\n💡 Macete\n“Neutrófilo hipersegmentado = pense em B12/folato até prova em contrário”\n\nGlossário\n\nMacro-ovalócito: hemácia grande e oval\n\nHipersegmentação: neutrófilo com ≥5 lóbulos\n\nReticulócitos: refletem resposta da medula","tags":["#AnemiaMegaloblástica","#Folato","#MacroOvalócitos","#NeutrófiloHipersegmentado","#VitaminaB12","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885706","ankiGuid":"d`g?]!Fv@A"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-748029ccf368f6b7","number":"1004a","sourceNumber":"1004a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Homem de 45 anos apresenta histórico de cansaço, tonteiras e palidez das mucosas há algumas semanas. O exame físico não apresentou visceromegalias e o de laboratório evidenciou hemoglobina = 6g/dL, hematócrito = 18%, leucócitos = 9.000/mm³ com diferencial normal e plaquetas = 450.000/mm³. A dosagem de reticulócitos é de 2,5%, VCM = 67fL e CHCM = 28g/dL. Para esse paciente, a definição do tipo de anemia e a alteração principal mais prováveis, respectivamente, são:","options":{"A":"hiperproliferativa / destruição por membrana anormal da hemácia","B":"hipoproliferativa / defeito na formação da hemoglobina","C":"hiperproliferativa / destruição imune das hemácias","D":"hipoproliferativa / defeito na maturação nuclear"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Nível: 🟡 Média\nCobra classificação da anemia (reticulócitos) + índices hematimétricos (VCM/CHCM).\n\nResumo essencial\n\nVCM baixo + CHCM baixo + reticulócitos inadequados = anemia microcítica hipoproliferativa, típica de defeito na síntese de hemoglobina (ex.: ferropriva).\n\nCorreção direta\n\n✅ Hipoproliferativa / defeito na formação da hemoglobina\n\nVCM 67 fL → microcítica\n\nCHCM 28 g/dL → hipocrômica\n\nReticulócitos 2,5% com Hb 6 g/dL → resposta medular inadequada (corrigido baixo)\n→ padrão clássico de defeito na produção de Hb (ferro, heme ou globina)\n\nErros principais das incorretas\n\n❌ Defeito na maturação nuclear: gera macrocitose (megaloblástica), não microcitose.\n❌ Destruição imune: seria anemia hemolítica (hiperproliferativa) com reticulócitos altos.\n❌ Membrana anormal: também hemólise (ex.: esferocitose), não microcítica.\n\nFisiopatologia-chave\n\n↓ ferro/heme/globina → ↓ Hb\n→ hemácias menores e mais pálidas\n→ medula não consegue compensar → hipoproliferação\n\n💡 Macete\n“Micro + hipo → problema é na hemoglobina”\n\nGlossário\n\nVCM: volume corpuscular médio (tamanho da hemácia)\n\nCHCM: concentração de Hb na hemácia\n\nReticulócitos corrigidos: avaliam resposta medular real","tags":["#AnemiaFerropriva","#DiagnósticoLaboratorial","#Hemoglobina","#Hipoproliferativa","#Microcítica","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885707","ankiGuid":"kW,u=/6G~A"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-44fa1c1300c42859","number":"1005a","sourceNumber":"1005a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"O diagnóstico das anemias da infância é muito auxiliado pela correta interpretação dos índices hematimétricos, entre eles, o tamanho dos glóbulos vermelhos (VCM = volume corpuscular médio). Qual alternativa abaixo representa uma possível causa de anemia microcítica (VCM diminuído)?","options":{"A":"Anemia por deficiência de tiamina","B":"Anemia por deficiência de ferro","C":"Anemia diseritropoética congênita","D":"Anemia por deficiência de vitamina B12 ou de ácido fálico","E":"Medicamentos que interferem na eritropoese (p.ex., valproato, zidovudina, alguns imunossupressores)"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Nível: 🟢 Fácil\nCobra correlação VCM ↓ (microcitose) com etiologias clássicas.\n\nResumo essencial\n\nAnemia microcítica = defeito na síntese de hemoglobina, sendo a causa mais comum a deficiência de ferro.\n\nCorreção direta\n\n✅ Anemia por deficiência de ferro\n\nCorreta → ↓ ferro → ↓ síntese de hemoglobina\n→ hemácias menores (VCM ↓) e hipocrômicas\n\nErros principais das incorretas\n\n❌ Deficiência de B12/folato: causa macrocitose (VCM ↑)\n❌ Fármacos (valproato, zidovudina): geralmente causam anemia macrocítica\n❌ Deficiência de tiamina: não é causa típica de anemia microcítica\n❌ Anemia diseritropoética congênita: costuma ser normo ou macrocítica\n\nFisiopatologia-chave\n\n↓ ferro → ↓ heme → ↓ hemoglobina\n→ hemácia “divide mais” antes de encher → fica menor (microcítica)\n\n💡 Macete\n“Microcitose = problema no ferro (ou Hb)”\n\nGlossário\n\nVCM: tamanho médio da hemácia\n\nHipocromia: ↓ coloração por menos hemoglobina\n\nHeme: componente da hemoglobina dependente de ferro","tags":["#Anemia","#DeficienciaDeFerro","#Hematologia","#Microcitose","#Pediatria","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885708","ankiGuid":"N]+i4>}>?N"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-63c36a481c9196ff","number":"1006a","sourceNumber":"1006a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Anemias microcíticas/hipocrômicas podem estar associadas a:","options":{"A":"doença renal.","B":"deficiência crônica de ferro.","C":"invasão tumoral da medula óssea.","D":"fase inicial da deficiência de ferro."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Nível: 🟡 Média\nCobra evolução da anemia ferropriva + diferenciação de padrões hematimétricos.\n\nResumo essencial\n\nAnemia microcítica/hipocrômica é típica de defeito na síntese de hemoglobina, principalmente na deficiência crônica de ferro.\n\nCorreção direta\n\n✅ Deficiência crônica de ferro\n\nCorreta → estágio tardio da ferropriva\n→ já há ↓ Hb suficiente para gerar microcitose (VCM ↓) + hipocromia (CHCM ↓)\n\nErros principais das incorretas\n\n❌ Invasão tumoral da medula: causa anemia normocítica ou pancitopenia.\n❌ Fase inicial da deficiência de ferro: ainda é normocítica (não microcítica).\n❌ Doença renal: anemia normocítica normocrômica (↓ eritropoetina).\n\nFisiopatologia-chave\n\nEvolução da anemia ferropriva:\n\nDepleção de estoques (ferritina ↓)\n\n↓ ferro sérico\n\n↓ Hb → microcitose e hipocromia\n\n💡 Macete\n“Ferropriva só fica microcítica quando já está avançada”\n\nGlossário\n\nMicrocitose: hemácia pequena (VCM ↓)\n\nHipocromia: pouca hemoglobina (CHCM ↓)\n\nFerritina: marcador de estoque de ferro","tags":["#AnemiaFerropriva","#AnemiaMicrocítica","#DeficiênciaDeFerro","#Hematologia","#Hemoglobina","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885709","ankiGuid":"n5,oN~5F`4"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-7a8a2bc530e58a25","number":"1007a","sourceNumber":"1007a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Causas de hematimetria que mostra VGM maior que 100, EXCETO","options":{"A":"Álcool.","B":"Deficiência de Vit B12.","C":"Excesso de ácido fólico.","D":"Hipotireoidismo.","E":"doença hepática."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Nível: 🟡 Média\nCobra causas de macrocitose (VCM > 100 fL) e identificação de exceção.\n\nResumo essencial\n\nMacrocitose ocorre por defeito na síntese de DNA (megaloblástica) ou por alterações metabólicas/hepáticas/álcool.\nExcesso de folato NÃO causa macrocitose.\n\nCorreção direta\n\n✅ Excesso de ácido fólico (EXCETO)\n\nNão causa macrocitose → ao contrário, o folato corrige anemia megaloblástica.\n\nPode até mascarar deficiência de B12, sem corrigir déficit neurológico.\n\nErros principais das incorretas\n\n❌ Hipotireoidismo: causa macrocitose leve.\n❌ Doença hepática: altera membrana da hemácia → macrocitose.\n❌ Deficiência de B12: clássico → anemia megaloblástica.\n❌ Álcool: causa macrocitose mesmo sem anemia.\n\nFisiopatologia-chave\n\nB12/folato ↓ → defeito de DNA → célula cresce sem dividir → macrocitose\n\nÁlcool/fígado → alteração de membrana lipídica → hemácias maiores\n\n💡 Macete\n“Macro = B12, folato ↓, fígado e álcool — nunca excesso de folato”\n\nGlossário\n\nVCM (VGM): volume corpuscular médio\n\nMegaloblástica: defeito de maturação nuclear\n\nMacrocitose: hemácia grande (>100 fL)","tags":["#AnemiaMacrocítica","#DeficiênciaB12","#Hematologia","#VGM","#Álcool","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885710","ankiGuid":"u-&*g/B*|1"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-360e970a5f33a7a1","number":"1008a","sourceNumber":"1008a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"A morfologia da hemácia auxilia no diagnóstico diferencial das anemias. Assinale a alternativa em que ambas as anemias são hipocrômica e microcítica:","options":{"A":"Microesferocitose e Alfa Talassemia","B":"Anemia ferropriva e Beta Talassemia","C":"Talassemia Beta e Anemia falciforme","D":"Deficiência de G6PD e Anemia Ferropriva","E":"Microesferocitose e Deficiência de G6PD"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Nível: 🟢 Fácil\nCobra padrões morfológicos clássicos das anemias (microcitose/hipocromia).\n\nResumo essencial\n\nAnemias microcíticas e hipocrômicas = defeito na síntese de hemoglobina\n→ principais: ferropriva e talassemias.\n\nCorreção direta\n\n✅ Anemia ferropriva e beta-talassemia\n\nAmbas apresentam:\n\nVCM ↓ (microcitose)\n\nCHCM ↓ (hipocromia)\n\nMecanismo comum: ↓ produção de hemoglobina\n\nErros principais das incorretas\n\n❌ Microesferocitose: hemácias pequenas, mas hipercromia, não hipocromia.\n❌ Deficiência de G6PD: anemia hemolítica → geralmente normocítica.\n❌ Anemia falciforme: hemolítica → normocítica.\n❌ Combinações mistas incluem doenças não microcíticas/hipocrômicas.\n\nFisiopatologia-chave\n\nFerropriva: ↓ ferro → ↓ heme → ↓ Hb\n\nTalassemia: ↓ síntese de globina → ↓ Hb\n→ resultado comum: hemácias pequenas e pálidas\n\n💡 Macete\n“Micro + hipo = ferro ou talassemia até prova em contrário”\n\nGlossário\n\nMicrocitose: hemácia pequena (VCM ↓)\n\nHipocromia: pouca hemoglobina (CHCM ↓)\n\nTalassemia: defeito genético na produção de globina","tags":["#AnemiaFerropriva","#BetaTalassemia","#DiagnósticoPrecoce","#Hematologia","#Hipocrômica","#MedicinaPreventiva","#Microcítica","#Prevenção","#Rastreamento","#SaúdePública","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885711","ankiGuid":"G^wj|ku@bR"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-9c05ea7fd63b497d","number":"1009a","sourceNumber":"1009a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Mulher, 32 anos, em investigação de trombocitopenia de surgimento recente, associada à elevação de escórias nitrogenadas. Hemograma: leucometria e hemoglobina em níveis normais. A visualização de hemácias fragmentadas (esquizócitos) na lâmina de sangue periférico sugere a hipótese diagnóstica, mais provável, de:","options":{"A":"trombocitopenia pós infecciosa","B":"púrpura trombocitopênica trombótica","C":"leucemia mielocítica aguda","D":"trombocitopenia induzida por drogas"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Nível: 🔴 Difícil\nCobra microangiopatia trombótica + correlação clínica (plaquetas ↓ + esquizócitos + rim).\n\nResumo essencial\n\nEsquizócitos + trombocitopenia + disfunção renal = quadro clássico de microangiopatia trombótica, principalmente PTT.\n\nCorreção direta\n\n✅ Púrpura trombocitopênica trombótica (PTT)\n\nEsquizócitos = fragmentação mecânica das hemácias em microtrombos\n\nTrombocitopenia → consumo plaquetário\n\n↑ escórias nitrogenadas → acometimento renal\n\nErros principais das incorretas\n\n❌ Pós-infecciosa: não cursa com esquizócitos típicos.\n❌ Induzida por drogas: pode dar plaquetopenia isolada, sem microangiopatia.\n❌ Leucemia mieloide aguda: alteração medular, não gera padrão de fragmentação mecânica.\n\nFisiopatologia-chave\n\n↓ atividade da ADAMTS13\n→ acúmulo de multímeros de vWF\n→ formação de microtrombos plaquetários\n→ hemácias passam e se fragmentam → esquizócitos\n\n💡 Macete\n“Esquizócito = pense em microangiopatia (PTT/HUS)”\n\nGlossário\n\nEsquizócito: fragmento de hemácia (marcador de hemólise mecânica)\n\nMicroangiopatia: lesão em pequenos vasos com trombos\n\nADAMTS13: enzima que cliva vWF\n\nElemento clínico\n\nPTT clássica (pêntade):\n\ntrombocitopenia\n\nanemia hemolítica microangiopática\n\ndisfunção renal\n\nalteração neurológica\n\nfebre (nem sempre presente)","tags":["#Esquizócitos","#Hematologia","#MicroangiopatiaTrombótica","#PTT","#Trombocitopenia","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885712","ankiGuid":"b*e<`:uL?s"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-a539354acd97eb5f","number":"1010a","sourceNumber":"1010a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"São causas de anemia macrocítica:","options":{"A":"Cirurgia bariátrica, doença inflamatória intestinal e artrite reumatoide.","B":"Anemia perniciosa, cirurgia bariátrica e síndrome do intestino curto.","C":"Doença inflamatória intestinal, talassemia e anemia perniciosa.","D":"Síndrome do intestino curto, anemia falciforme, hábito vegetariano.","E":"Hábito vegetariano, talassemia, artrite reumatoide."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão\n\nNível: 🟡 Média (Fisiopatologia das anemias macrocíticas e suas etiologias).\n\nResumo Essencial\n\nAnemia macrocítica (VCM >100 fL) resulta principalmente de deficiência de B12/folato, comum em condições que afetam absorção intestinal.\n\nCorreção Direta\n\n✅ Alternativa correta:\n\n\"Anemia perniciosa, cirurgia bariátrica e síndrome do intestino curto\":\n\nJustificativa:\n\nAnemia perniciosa: Deficiência de fator intrínseco → ↓ absorção B12 → megaloblastose.\n\nCirurgia bariátrica: Bypass gástrico → ↓ absorção B12 (íleo terminal) e folato.\n\nSíndrome do intestino curto: Ressecção ileal → ↓ absorção B12 → macrocitose.\n\nErros nas Outras Alternativas ❌\n\nTalassemia: Causa anemia microcítica (VCM <80 fL) por defeito na síntese de globinas.\n\nDII e artrite reumatoide: Causam anemia normocítica (doença crônica/inflamação).\n\nAnemia falciforme: Normocítica com reticulocitose (hemólise compensada).\n\nFisiopatologia da Macrocitose\n\nMegaloblástica (B12/folato):\n\nSíntese de DNA prejudicada → divisão celular lenta\n\nHipersegmentação neutrofílica + megaloblastos\n\nNão-megaloblástica:\n\nAlcoolismo, hipotireoidismo, hepatopatia\n\nLocais de Absorção\n\nB12: Íleo terminal (complexo B12-fator intrínseco)\n\nFolato: Jejuno proximal\n\nFerro: Duodeno (anemia microcítica)\n\nDiagnóstico Diferencial\n\nVCM >100 fL + B12/folato baixos = Megaloblástica\n\nVCM >100 fL + B12/folato normais = Não-megaloblástica\n\nCausas por Mecanismo\n\n↓ Absorção: Perniciosa, bariátrica, intestino curto, metformina\n\n↓ Ingesta: Vegetarianismo estrito (B12), alcoolismo (folato)\n\n↑ Consumo: Gravidez, neoplasias, hemodiálise\n\nMnemônico Útil ✨\n\n\"MAC-ro = Má Absorção Cobalamina\" - B12/folato são as principais causas.\n\nTags Temáticas\n\nDica: Macrocitose = Pense B12/folato! Problemas intestinais são causas frequentes. 🔴📏","tags":["#AnemiaMacrocítica","#AnemiaPerniciosa","#CirurgiaBariátrica","#Folato","#Hematologia","#Megaloblastose","#VitaminaB12","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885713","ankiGuid":"P&h(0O;y)e"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-a7580ee1bc791f2e","number":"1011a","sourceNumber":"1011a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Qual dos seguintes achados são característicos na hematoscopia de sangue periférico de um homem de 28 anos que foi esplenectomizado há 06 meses, após trauma abdominal fechado?","options":{"A":"Acantócitos.","B":"Hemácias em lágrima.","C":"Neutrófilos com hipogranulação.","D":"Hemácias com inclusões basofílicas.","E":"Hemácias em alvo."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Nível: 🟡 Média\nCobra função do baço na “filtragem” de hemácias + achados pós-esplenectomia.\n\nResumo essencial\n\nSem baço → perda da função de remoção de inclusões eritrocitárias\n→ aparecem corpos de Howell-Jolly (inclusões basofílicas) no sangue periférico.\n\nCorreção direta\n\n✅ Hemácias com inclusões basofílicas\n\nCorresponde aos corpos de Howell-Jolly (restos nucleares)\n\nBaço normal removeria essas inclusões → ausência do baço = elas persistem\n\nErros principais das incorretas\n\n❌ Acantócitos: associados a doença hepática ou abetalipoproteinemia.\n❌ Hemácias em lágrima: típico de mielofibrose/infiltração medular.\n❌ Hemácias em alvo: comum em talassemia/hepatopatias.\n❌ Neutrófilos hipogranulados: sugere síndrome mielodisplásica.\n\nFisiopatologia-chave\n\nBaço → “peneira” do sangue\n\nRemove hemácias anormais\n\nRetira inclusões nucleares\n\nPós-esplenectomia →\n→ Howell-Jolly bodies aparecem no sangue periférico\n\n💡 Macete\n“Sem baço = sobra sujeira na hemácia” (Howell-Jolly)\n\nGlossário\n\nCorpos de Howell-Jolly: restos de DNA nas hemácias\n\nEsplenectomia: retirada do baço\n\nInclusões basofílicas: estruturas coradas dentro da hemácia\n\nElemento clínico\n\nPacientes esplenectomizados → maior risco de infecção por:\n\nbactérias encapsuladas (ex.: pneumococo)","tags":["#Esplenectomia","#Hematologia","#Hematoscopia","#Hipoespelnismo","#Hipoesplenismo","#HowellJolly","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885714","ankiGuid":"IHgz>!FG&o"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-a0a69ae5e3a9c812","number":"1012a","sourceNumber":"1012a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Mulher de 48 anos queixa-se de parestesias em mãos e pés há cerca de 4 meses. Tem diabetes mellitus há 5 anos, em uso de metformina e sangramento retal devido a hemorroida há 1 ano. Exames laboratoriais: Hb = 10,0 g/dL; VCM = 115 fL; leucócitos = 3.800/ mm³ ; segmentados = 1.600/ mm³; plaquetas = 120.000/ mm³ . Descrição do esfregaço sanguíneo: ausência de células imaturas e presença de pleocariócitos. A hipótese diagnóstica é","options":{"A":"deficiência de ácido fólico.","B":"anemia hemolítica.","C":"anemia de doença crônica.","D":"deficiência de vitamina B12.","E":"deficiência de ferro."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão 🟡\n\nDificuldade: Média (Amarela).\n\nJustificativa: A questão exige conhecimento sobre anemias macrocíticas (VCM > 100 fL), interpretação de achados laboratoriais (hemograma, esfregaço) e correlação com sintomas clínicos (parestesias) e comorbidades (diabetes, uso de metformina). O raciocínio clínico é direto, mas requer integração de dados para diferenciar causas de anemia, como deficiência de B12, folato ou outras condições.\n\nResumo Essencial 📝\n\nA paciente apresenta anemia macrocítica (VCM = 115 fL), pancitopenia (Hb = 10,0 g/dL, leucócitos = 3.800/mm³, plaquetas = 120.000/mm³), pleocariócitos no esfregaço e parestesias, sugerindo deficiência de vitamina B12 ou folato, que afetam a síntese de DNA e causam megaloblastose. O uso prolongado de metformina e sangramento crônico por hemorroidas aumentam o risco de deficiência de B12. A diferenciação entre B12 e folato é crucial, considerando sintomas neurológicos (parestesias) e contexto clínico.\n\nExplicação do Gabarito ✅❌\n\nDeficiência de ferro ❌: Incorreto. A deficiência de ferro causa anemia microcítica (VCM < 80 fL), não macrocítica (VCM = 115 fL). Embora o sangramento retal por hemorroidas possa contribuir para perda de ferro, os achados laboratoriais (VCM elevado, pleocariócitos) não são compatíveis. 🩺🚫\n\nAnemia de doença crônica ❌: A anemia de doença crônica é tipicamente normocítica ou levemente microcítica, não macrocítica. Não explica o VCM elevado, pleocariócitos ou parestesias. 🩺🚫\n\nAnemia hemolítica ❌: A anemia hemolítica geralmente é normocítica, com aumento de reticulócitos e presença de hemácias anormais (ex.: esferócitos). O esfregaço sem células imaturas e com pleocariócitos não suporta essa hipótese. 🩺🚫\n\nDeficiência de ácido fólico ❌: A deficiência de folato causa anemia macrocítica e megaloblastose, com VCM elevado e pleocariócitos, mas não está associada a parestesias, que são típicas da deficiência de B12. O contexto clínico (metformina, sangramento) favorece B12. 🩺🚫\n\nDeficiência de vitamina B12 ✅: Correta. A deficiência de B12 causa anemia macrocítica (VCM = 115 fL), pancitopenia (devido à megaloblastose medular), pleocariócitos (neutrófilos hipersegmentados) e parestesias (por neuropatia periférica). O uso prolongado de metformina reduz a absorção de B12, e o sangramento crônico pode exacerbar a anemia. Visualização: Imagine hemácias grandes e neutrófilos com núcleos hipersegmentados, como flores malformadas, refletindo a maturação deficiente por falta de B12. 🩺🩸\n\nFoco nos Termos 🔬\n\nAnemia macrocítica: Hemácias grandes (VCM > 100 fL), causada por deficiência de vitamina B12 ou folato, que impair a síntese de DNA, levando a megaloblastose. 🩸\n\nPancitopenia: Redução de todas as linhagens celulares (hemácias, leucócitos, plaquetas), comum em deficiências de B12/folato devido à falha na maturação medular. 📉\n\nPleocariócitos: Neutrófilos hipersegmentados (com >5 lóbulos nucleares), um marcador de anemia megaloblástica (B12 ou folato). 🔍\n\nVitamina B12: Nutriente essencial para síntese de DNA e mielinização nervosa. Sua deficiência causa anemia macrocítica e neuropatia (ex.: parestesias). 🧬\n\nMetformina: Medicamento para diabetes que reduz a absorção de vitamina B12 no íleo, aumentando o risco de deficiência a longo prazo. 💊\n\nConexão clínica: A deficiência de B12, potencializada por metformina e sangramento crônico, explica a anemia macrocítica, pancitopenia, pleocariócitos e parestesias. A ausência de sintomas neurológicos na deficiência de folato diferencia as duas condições.\n\nSemiologia 🩺\n\nParestesias em mãos e pés: Sensação de formigamento ou dormência, indicando neuropatia periférica, um achado clássico da deficiência de vitamina B12 devido à desmielinização nervosa. Visualize os nervos periféricos como cabos elétricos desgastados, causando “curtos” sensitivos.\n\nFisiopatologia 📊\n\nMecanismo da deficiência de vitamina B12:\n\nDeficiência de B12 (ex.: má absorção por metformina) -> Alteração na síntese de DNA -> Maturação deficiente de eritroblastos e leucócitos -> Megaloblastos na medula -> Anemia macrocítica, pancitopenia e pleocariócitos.\n\nNeuropatia: B12 insuficiente -> Desmielinização nervosa -> Parestesias.\n\nDiagrama: Metformina/sangramento -> Baixa B12 -> Megaloblastose -> Anemia macrocítica + Pancitopenia + Pleocariócitos; Desmielinização -> Parestesias.\n\nContexto adicional: O sangramento retal crônico pode causar anemia ferropriva (microcítica), mas o VCM elevado indica que a deficiência de B12 é o fator dominante.\n\nElementos Dinâmicos ✨\n\nConceito adicional: A anemia megaloblástica por B12/folato é caracterizada por hipersegmentação de neutrófilos (pleocariócitos) e hemácias macrocíticas. Testes como níveis séricos de B12, folato e ácido metilmalônico (elevado na deficiência de B12) confirmam o diagnóstico.\n\nCuriosidade: A deficiência de B12 pode levar à “anemia combinada subaguda”, com sintomas neurológicos (parestesias, ataxia) e hematológicos, descrita no século XIX como anemia perniciosa antes da descoberta da B12.\n\nMnemônico: Para lembrar sintomas da deficiência de B12: “P.A.N.E.” – Parestesias, Anemia macrocítica, Neuropatia, Esfregaço com pleocariócitos.\n\nFrase ilustrativa: “Sem B12, as hemácias crescem grandes, os neutrófilos viram flores e os nervos formigam!”\n\nDicas de Estudo 🔍\n\nVídeos: Busque no YouTube vídeos sobre “anemia megaloblástica” ou “deficiência de vitamina B12”, mostrando esfregaços com pleocariócitos e hemácias macrocíticas.\n\nImagens: Pesquise no Google Imagens por “neutrófilos hipersegmentados” (lóbulos nucleares múltiplos) e “hemácias macrocíticas” (grandes, ovaladas).\n\nGuias: Consulte manuais de hematologia (ex.: Williams Hematology) ou diretrizes sobre anemia megaloblástica para revisar diagnóstico e tratamento.","tags":["#AnemiaMacrocítica","#Hematologia","#Pancitopenia","#Pleocariócitos","#VitaminaB12","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885715","ankiGuid":"oY]hT*$wxN"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-b2499441440c6185","number":"1013a","sourceNumber":"1013a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Das alternativas apresentadas abaixo qual apresenta exemplos de anemias hipoproliferativas?","options":{"A":"As desordens de membranas e as anemias microangiopáticas.","B":"As hemoglobinopatias, como a anemia falciforme.","C":"A ocupação medular por células anormais, as leucemias e as metástases.","D":"A hemoglobinúria paroxística noturna."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão 🟡\n\nDificuldade: Média (Amarela).\n\nJustificativa:\n\nPara um aluno de medicina, a questão exige conhecimento intermediário sobre a classificação das anemias, especificamente o conceito de anemias hipoproliferativas, geralmente abordado no 3º ou 4º ano (disciplinas como hematologia ou clínica médica).\n\nO raciocínio é intermediário, pois o aluno precisa distinguir entre anemias hipoproliferativas (baixa produção de eritrócitos na medula óssea) e outras categorias (ex.: hemolíticas, por perda sanguínea), além de identificar exemplos corretos entre distratores.\n\nNão é fácil, pois exige entendimento da fisiopatologia medular e diferenciação de causas, mas também não é difícil, pois não envolve cálculos (ex.: índices hematimétricos) ou manejo clínico detalhado, sendo acessível a estudantes com base sólida em hematologia.\n\nResumo Essencial 📝\n\nA alternativa correta é a ocupação medular por células anormais, as leucemias e as metástases, pois essas condições representam anemias hipoproliferativas, causadas pela substituição ou inibição da hematopoiese normal na medula óssea.\n\nExplicação do Gabarito ✅❌\n\nA ocupação medular por células anormais, as leucemias e as metástases ✅: Correto.\n\nAnemias hipoproliferativas ocorrem devido a uma produção reduzida de eritrócitos na medula óssea.\n\nOcupação medular por células anormais: Infiltração por células neoplásicas (ex.: leucemia, metástases de tumores sólidos como mama ou próstata) substitui o tecido hematopoético, diminuindo a produção de eritrócitos.\n\nLeucemias: Doenças malignas das células hematopoéticas (ex.: LMA, LLC) ocupam a medula, suprimindo a eritropoiese.\n\nMetástases: Tumores secundários na medula (ex.: neuroblastoma) causam hipoplasia medular, levando a anemia.\n\nEsses exemplos são clássicos de anemias hipoproliferativas, confirmados por biópsia de medula óssea mostrando celularidade reduzida ou infiltrada.\n\nVisualização: Medula ocupada por células cancerígenas = menos eritrócitos = anemia hipoproliferativa. 🩺🩺\n\nA hemoglobinúria paroxística noturna ❌: Errado.\n\nA hemoglobinúria paroxística noturna é uma anemia hemolítica (não hipoproliferativa), causada por destruição intravascular de eritrócitos devido a defeitos na proteína CD55/CD59, levando a hemólise e hemoglobinúria. A produção medular não é o problema principal. 🩺🚫\n\nAs hemoglobinopatias, como a anemia falciforme ❌: Errado.\n\nA anemia falciforme (hemoglobinopatia por mutação na hemoglobina S) é uma anemia hemolítica, resultante da hemólise dos eritrócitos falciformes (devido a vaso-oclusão e fragilidade). A medula pode hiperproliferar para compensar, mas a causa é hemólise, não hipoprodução. 🩺🚫\n\nAs desordens de membranas e as anemias microangiopáticas ❌: Errado.\n\nDesordens de membranas (ex.: esferocitose hereditária) e anemias microangiopáticas (ex.: púrpura trombocitopênica trombótica) são anemias hemolíticas, causadas por destruição periférica de eritrócitos (fragmentação ou defeitos membranários), não por falha na produção medular. 🩺🚫\n\nFoco nos Termos 🔬\n\nAnemias hipoproliferativas: Redução da produção de eritrócitos na medula óssea; causas: ocupação medular (leucemias, metástases), deficiência de ferro, vitamina B12/fólico, insuficiência renal. 🩺\n\nOcupação medular: Infiltração por células neoplásicas (ex.: leucemia mieloide aguda, metástases) suprime hematopoiese; anemia normocítica/normocrômica. 🩺\n\nAnemias hemolíticas: Aumento da destruição de eritrócitos (ex.: hemoglobinúria paroxística, falciforme); medula hiperativa (reticulocitose). 🩺\n\nDiagnóstico: Mielograma mostra celularidade reduzida ou infiltrada em hipoproliferativas; hemólise é sugerida por haptoglobina baixa, LDH elevado. 🩺\n\nConexão clínica: Paciente com anemia e histórico de câncer precisa de biópsia medular para diferenciar ocupação (hipoproliferativa) de outras causas; tratamento depende da etiologia (ex.: quimioterapia para leucemia).\n\nSemiologia 🩺\n\nAnemia hipoproliferativa: Palidez, fadiga, taquicardia; reticulócitos baixos (<2%), medula infiltrada em biópsia. 🩺\n\nExame físico: Linfonodos (leucemia), massas (metástases); esplenomegalia sugere hemólise, não hipoprodução. 🩺\n\nFisiopatologia 📊\n\nMecanismo:\n\nOcupação medular -> Substituição de células hematopoéticas -> Hipoprodução de eritrócitos -> Anemia.\n\nDiagrama: Infiltração -> Hipoprodução -> Anemia hipoproliferativa.\n\nContexto adicional: Leucemias representam 30-40% das causas de ocupação medular; metástases são mais comuns em câncer avançado.\n\nElementos Dinâmicos ✨\n\nConceito adicional: Reticulócitos baixos (<2%) confirmam hipoproliferação; elevados (>2%) indicam hemólise.\n\nCuriosidade: A hemoglobinúria paroxística noturna foi descrita por Marchiafava e Micheli em 1931, ligada a mutações somáticas.\n\nMnemônico: Para hipoproliferativas: “L.M.O.” – Leucemias, Metástases, Ocupação.\n\nFrase ilustrativa: “Anemia por ocupação medular: leucemias e metástases são os vilões!”\n\nDicas de Estudo 🔍\n\nVídeos: Busque no YouTube vídeos sobre “anemia hipoproliferativa” ou “mielograma ocupação medular”.\n\nImagens: Pesquise no Google Imagens por “biópsia medular leucemia” ou “anemia hipoproliferativa”.\n\nGuias: Consulte livros de hematologia (ex.: Williams Hematology) ou clínica médica (ex.: Harrison’s Principles of Internal Medicine).","tags":["#AnemiaHipoproliferativa","#Hematologia","#Leucemia","#Medicina","#Metástases","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885716","ankiGuid":"xJO?_2N#!."},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-b4d8d86507af268d","number":"1014a","sourceNumber":"1014a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Paciente de 21 anos de idade, sexo masculino, apresenta quadro de celulite na coxa direita, iniciando o tratamento oral com trimetoprim-sulfametoxazol. Algumas horas depois, evolui com mal-estar, tontura, falta de ar, calafrios e lombalgia. Não há histórico de uso prévio de antibióticos. Exame físico: hipocorado (2+/4+), ictérico (1+/4+), eupneico e afebril. Exames séricos: hemoglobina: 9,1 g/dL, plaquetas: 330000/mm³, reticulócitos corrigidos: 15,8%; esfregaço de sangue periférico: presença de corpúsculos de Heinz. O diagnóstico mais provável é:","options":{"A":"deficiência de glicose-6-fosfato desidrogenase.","B":"desordem da membrana do eritrócito.","C":"hemólise autoimune.","D":"sepse por bactérias anaeróbias."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão: 🟡 Média.\n\nJustificativa da Classificação: A questão apresenta um quadro de hemólise aguda desencadeada pela administração de trimetoprim-sulfametoxazol em um paciente com achados laboratoriais sugestivos. A interpretação correta requer a associação entre o fármaco utilizado, o quadro clínico de anemia hemolítica com icterícia e os achados específicos no esfregaço de sangue periférico (corpúsculos de Heinz), direcionando para a deficiência de glicose-6-fosfato desidrogenase (G6PD).\n\nResumo Essencial: A deficiência de G6PD é uma enzimopatia hereditária que torna os eritrócitos mais suscetíveis ao dano oxidativo. Certos fármacos, como o sulfametoxazol (presente no trimetoprim-sulfametoxazol), podem desencadear hemólise aguda em indivíduos com essa deficiência, levando a anemia, icterícia e outros sintomas.\n\nExplicação do Gabarito Detalhada:\n\n❌ Sepse por bactérias anaeróbias. – A sepse é uma resposta inflamatória sistêmica grave a uma infecção. Embora possa cursar com anemia e mal-estar, a presença de icterícia com reticulocitose elevada e, principalmente, os corpúsculos de Heinz no esfregaço periférico não são achados típicos de sepse por anaeróbios. Além disso, a relação temporal com o início do antibiótico sugere uma causa medicamentosa.\n\n✅ Deficiência de glicose-6-fosfato desidrogenase. – O quadro clínico de anemia (hemoglobina baixa), icterícia, reticulocitose elevada (indicando resposta da medula óssea à hemólise) e a presença de corpúsculos de Heinz no esfregaço de sangue periférico são fortemente sugestivos de hemólise por deficiência de G6PD desencadeada pelo sulfametoxazol. O sulfametoxazol é um conhecido agente oxidante que pode levar à destruição dos eritrócitos deficientes em G6PD. A ausência de histórico prévio de uso de antibióticos explica a primeira manifestação da hemólise nesse momento.\n\n❌ Desordem da membrana do eritrócito. – Desordens da membrana do eritrócito, como esferocitose hereditária ou eliptocitose hereditária, geralmente se manifestam com anemia hemolítica crônica ou recorrente, esplenomegalia e ausência de um fator precipitante agudo como o uso de um medicamento específico. Embora possa haver icterícia, os corpúsculos de Heinz não são característicos dessas condições.\n\n❌ Hemólise autoimune. – A hemólise autoimune ocorre quando o sistema imunológico produz anticorpos que atacam os próprios eritrócitos. O quadro clínico pode ser agudo ou crônico e geralmente se associa a um teste de Coombs positivo, que não foi mencionado nos dados fornecidos. Os corpúsculos de Heinz também não são típicos dessa condição.\n\nFoco nos Termos-Chave 📖:\n\nCelulite: Infecção bacteriana da pele e do tecido subcutâneo. 🦠\n\nTrimetoprim-sulfametoxazol: Antibiótico de amplo espectro. 💊\n\nMal-estar: Sensação geral de desconforto e indisposição.\n\nTontura: Sensação de vertigem ou instabilidade. 😵‍💫\n\nFalta de ar (dispneia): Dificuldade para respirar. 💨\n\nCalafrios: Tremores com sensação de frio. 🥶\n\nLombalgia: Dor na região lombar. 🤕\n\nHipocorado: Palidez da pele e mucosas devido à anemia.\n\nIctérico: Coloração amarelada da pele e mucosas devido ao aumento da bilirrubina. 🟡\n\nEupneico: Respiração normal.\n\nAfebril: Sem febre.\n\nHemoglobina: Proteína nos eritrócitos responsável pelo transporte de oxigênio. 🩸\n\nPlaquetas: Fragmentos celulares envolvidos na coagulação sanguínea.\n\nReticulócitos corrigidos: Medida da produção de novos eritrócitos pela medula óssea, corrigida para o grau de anemia. Um valor elevado indica resposta à perda de eritrócitos.\n\nEsfregaço de sangue periférico: Análise microscópica de uma amostra de sangue. 🔬\n\nCorpúsculos de Heinz: Inclusões intracelulares nos eritrócitos compostas por hemoglobina desnaturada, resultantes de dano oxidativo. São um achado característico da deficiência de G6PD após exposição a agentes oxidantes.\n\nSepse: Resposta inflamatória sistêmica grave a uma infecção. 🔥\n\nBactérias anaeróbias: Bactérias que não necessitam de oxigênio para sobreviver.\n\nDeficiência de glicose-6-fosfato desidrogenase (G6PD): Enzimopatia hereditária que afeta a via das pentoses fosfato nos eritrócitos, tornando-os mais vulneráveis ao estresse oxidativo. 🧬\n\nDesordem da membrana do eritrócito: Anormalidades estruturais na membrana dos glóbulos vermelhos.\n\nHemólise autoimune: Destruição dos eritrócitos pelo próprio sistema imunológico. 🛡️\n\nSemiologia Aplicada 🩺:\n\nA icterícia e a palidez são sinais de anemia hemolítica. A ausência de febre e outros sinais infecciosos fortes torna a sepse menos provável como causa primária da hemólise. A lombalgia pode ocorrer devido à hemólise intravascular.\n\nFisiopatologia Descomplicada 🧬:\n\nA G6PD é uma enzima essencial na via das pentoses fosfato, responsável por produzir NADPH, um importante redutor que protege os eritrócitos contra o dano oxidativo. Em indivíduos com deficiência de G6PD, a exposição a agentes oxidantes (como o sulfametoxazol) leva à incapacidade de neutralizar o estresse oxidativo, resultando na desnaturação da hemoglobina e formação dos corpúsculos de Heinz. Os eritrócitos contendo corpúsculos de Heinz são removidos prematuramente da circulação pelo baço, causando hemólise.\n\nElementos Dinâmicos para Fixação 🧠:\n\n💡 Frase Ilustrativa: \"Em pacientes com deficiência de G6PD, certos 'gatilhos' como antibióticos sulfa podem 'oxidar' os glóbulos vermelhos desprotegidos, levando à sua destruição.\"\n\nDicas de Estudo Adicionais 📚:\n\nRevise a via das pentoses fosfato e a função da G6PD.\n\nEstude as causas de anemia hemolítica, diferenciando as causas intrínsecas (como a deficiência de G6PD e as desordens da membrana) das causas extrínsecas (como a hemólise autoimune e a microangiopática).\n\nAprenda a identificar os corpúsculos de Heinz no esfregaço de sangue periférico.\n\nConsulte a lista de fármacos e agentes que podem desencadear hemólise em pacientes com deficiência de G6PD.","tags":["#AnemiaHemolítica","#Antibióticos","#CorpúsculosDeHeinz","#DeficiênciaDeG6PD","#Farmacologia","#GenéticaMédica","#Hematologia","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885717","ankiGuid":"s4)EnjY(Ib"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-9a8bd5563eeb6bb9","number":"1015a","sourceNumber":"1015a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"A anemia ferropriva, sob o ponto de vista fisiológico, é classificada como uma anemia decorrente da _________________ e, considerando a classificação morfológica, é uma anemia __________________. Assinale a alternativa que preenche, correta e respectivamente, as lacunas do trecho acima.","options":{"A":"eritropoese inefetiva - macrocítica","B":"deficiência de produção - microcítica","C":"eritropoese inefetiva - microcítica","D":"deficiência de produção - macrocítica"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão\n\nNível: 🟢 Fácil (Conceitos fundamentais de classificação das anemias).\n\nResumo Essencial\n\nAnemia ferropriva resulta de eritropoese inefetiva (produção inadequada de hemoglobina) com morfologia microcítica (hemácias pequenas).\n\nCorreção Direta\n\n✅ Alternativa correta:\n\n\"eritropoese inefetiva - microcítica\":\n\nJustificativa:\n\nEritropoese inefetiva: Medula óssea ativa mas produz hemácias deficientes em hemoglobina.\n\nMicrocítica: VCM <80 fL - hemácias pequenas por deficiência de ferro.\n\nFisiopatologia: ↓ Ferro → ↓ síntese de heme → ↓ hemoglobina → hemácias pequenas e hipocrômicas.\n\nErros nas Outras Alternativas ❌\n\nDeficiência de produção: Implicaria medula hipoativa (ex: aplasia medular) - não é o caso na ferropenia.\n\nMacrocítica: Falso - ferro causa microcitose, não macrocitose (B12/folato).\n\nClassificação Fisiológica das Anemias\n\nDeficiência de produção: Aplasia, infiltração medular, IRC\n\nEritropoese inefetiva: Ferropriva, talassemia, sideroblástica\n\nPerda/destruição: Hemólise, hemorragia aguda\n\nClassificação Morfológica\n\nMicrocítica (VCM <80): Ferro, talassemia, doença crônica\n\nNormocítica (80-100): Doença crônica, hemólise, IRC\n\nMacrocítica (>100): B12, folato, álcool, hipotireoidismo\n\nEritropoese Inefetiva na Ferropriva\n\nMedula hipercelular com eritroblastos microcíticos\n\nProdução aumentada mas qualidade deficiente\n\nReticulócitos baixos/normais (hemácias imaturas defeituosas)\n\nLaboratório Típico\n\nVCM baixo + HCM baixo + CHCM baixo\n\nFerritina baixa + TIBC alto + saturação transferrina baixa\n\nMnemônico Útil ✨\n\n\"Ferro Ineficaz = Micro\" - eritropoese inefetiva produz hemácias pequenas.\n\nTags Temáticas\n\nDica: Ferropriva = Eritropoese inefetiva! Medula trabalha, mas produz hemácias defeituosas e pequenas. 🔴⚙️","tags":["#AnemiaFerropriva","#Anemias","#DeficiênciaDeFerro","#EritropoeseInefetiva","#Eritropoiese","#Ferro","#Fisiopatologia","#Hematologia","#Microcítica","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885718","ankiGuid":"B~$2ufn-sB"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-ad036715f9b6bb20","number":"1016a","sourceNumber":"1016a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Você está investigando a causa da anemia de um paciente de 50 anos de idade, cuja avaliação de rotina mostrou hematrócrito de 25%. Há 1 ano, o hematócrito era de 47%. O volume corpuscular médio é de 80 (V.R.: 79 a 98 fL), a concentração de hemoglobina corpuscular média é 25 (V.R.: 32 a 36 g/dL), a hemoglobina corpuscular média é 25 (V.R.: 26,5 a 31 pg) e a contagem de reticulócitos é 5%(V.R.: 0,5 a 2,17%). A avaliação do esfregaço de sangue periférico mostra grande número de macrócitos policromatófilos. A dosagem de ferritina é de 340 ug/ml. Qual é a causa da anemia deste paciente?","options":{"A":"Defeito na proliferação de eritrócitos na medula óssea;","B":"Hemólise extravascular;","C":"Hemólise intravascular;","D":"Anemia por deficiência de ferro;","E":"Sangramento gastrintestinal;"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Resposta Estruturada\n\nClassificação da Questão\n\nNível: 🔴 Difícil (Interpretação laboratorial complexa, índices hematimétricos discordantes e fisiopatologia da eritropoiese).\n\nResumo Essencial\n\nAnemia grave com reticulocitose aparentemente alta mas inadequada para o grau de anemia, sugerindo eritropoiese ineficaz por defeito medular.\n\nCorreção Direta\n\n✅ Alternativa correta:\n\n\"Defeito na proliferação de eritrócitos na medula óssea\":\n\nJustificativa:\n\nÍndice reticulocitário corrigido: (5% × 25) / 45 = 2,8 (inadequado para Ht 25%)\n\nResposta insuficiente: Para Ht 25%, esperado reticulócitos >10-15%\n\nMacrócitos policromatófilos: Reticulócitos grandes → eritropoiese acelerada mas ineficaz\n\nCHCM baixa (25): Sugere defeito na hemoglobinização\n\nFerritina normal (340): Exclui deficiência de ferro\n\nErros nas Outras Alternativas ❌\n\n\"Sangramento gastrointestinal\":\n\nFerritina normal descarta deficiência férrica por sangramento crônico\n\n\"Anemia por deficiência de ferro\":\n\nFerritina 340 está normal/elevada (deficiência <30)\n\n\"Hemólise intravascular\":\n\nAusência de: hemoglobinúria, ↓haptoglobina (não mencionados)\n\n\"Hemólise extravascular\":\n\nReticulocitose inadequada para hemólise significativa\n\nAnálise dos Índices Laboratoriais 📊\n\nHt: 47% → 25% (queda de 47% em 1 ano)\n\nVCM 80: Normocítico (borderline)\n\nCHCM 25: Hipocromia (VR: 32-36)\n\nReticulócitos 5%: Falsamente elevado para o grau de anemia\n\nÍndice reticulocitário: 2,8 (esperado >4-5 para hemólise/sangramento)\n\nFisiopatologia da Eritropoiese Ineficaz 🧬\n\nCausas principais:\n\nAnemia megaloblástica (B12/folato)\n\nMielodisplasia\n\nSíndromes talassêmicas\n\nAnemia sideroblástica\n\nMecanismo: ↑ Proliferação + ↑ Apoptose intramedular\n\nInterpretação do Reticulócitos 🔍\n\nFórmula corrigida: (Reticulócitos % × Ht paciente) / 45\n\nResposta adequada: >3 para anemia\n\nNeste caso: 2,8 = resposta inadequada\n\nMacrócitos policromatófilos: Reticulócitos imaturos e grandes\n\nDiagnóstico Diferencial 🎯\n\nInvestigar:\n\nB12/Folato: Megaloblástica\n\nMielograma: Mielodisplasia\n\nEletroforese Hb: Talassemia\n\nFerro medular: Sideroblástica\n\nMnemônico Útil ✨\n\n\"Reticulócitos Altos, Anemia Pior = Medula Ineficaz!\"\n\nDica: Reticulócitos \"altos\" mas inadequados para anemia grave = Eritropoiese ineficaz! Sempre calcular índice corrigido. 📉🔬\n\nFonte: Mais importante:\n\nFórmula corrigida: (Reticulócitos % × Ht paciente) / 45\nResposta esperada: >3 para anemia","tags":["#AnemiaMegaloblástica","#EritropoieseIneficaz","#Hematologia","#Mielodisplasia","#ÍndiceReticulocitário","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885719","ankiGuid":"P$:K:}LrlV"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-5ddadbe618179c46","number":"1017a","sourceNumber":"1017a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Uma paciente recém-diagnosticada com leucemia de células pilosas e ainda não submetida a qualquer tratamento apresenta corpúsculos de Howell-Jolly, corpúsculos de Heinz, e hemácias nucleadas. Qual a interpretação destes achados?","options":{"A":"Infiltração esplênica difusa pelo tumor.","B":"Coagulação intravascular disseminada.","C":"Anemia hemolítica.","D":"Pancitopenia.","E":"Transformação para leucemia aguda."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão\n\nNível: 🟡 Média (Hematologia - leucemia de células pilosas e função esplênica).\n\nResumo Essencial\n\nCorpúsculos de Howell-Jolly e hemácias nucleadas indicam hipoesplenismo funcional, comum na leucemia de células pilosas devido à infiltração esplênica maciça que compromete a função de filtração.\n\nCorreção Direta\n\n✅ Alternativa correta:\n\n\"Infiltração esplênica difusa pelo tumor\":\n\nJustificativa:\n\nLeucemia de células pilosas: Infiltração preferencial do baço (esplenomegalia em 80-90%).\n\nHipoesplenismo funcional: Infiltração tumoral → ↓função de filtração → corpúsculos não removidos.\n\nAchados típicos: Howell-Jolly (DNA nuclear), hemácias nucleadas, corpúsculos de Heinz → \"aspecto pós-esplenectomia\".\n\nErros nas Outras Alternativas ❌\n\nPancitopenia:\n\nIncompleto: Pancitopenia é consequência, não causa dos achados morfológicos descritos.\n\nCoagulação intravascular disseminada:\n\nFalso: CIVD cursaria com esquizócitos e ↓plaquetas, não com corpúsculos intracelulares.\n\nAnemia hemolítica:\n\nFalso: Hemólise causaria esquizócitos, esferócitos e ↑bilirrubinas, não corpúsculos nucleares.\n\nTransformação para leucemia aguda:\n\nFalso: Leucemia de células pilosas é indolente e raramente transforma. Achados não indicam transformação.\n\nFisiopatologia da Leucemia de Células Pilosas 🔬\n\nInfiltração esplênica:\n\nCélulas pilosas → polpa vermelha → esplenomegalia maciça\n\nFunção comprometida: ↓filtração de hemácias anômalas\n\nConsequências:\n\nSequestro esplênico → pancitopenia\n\nHipoesplenismo funcional → corpúsculos persistentes\n\nMorfologia Hematológica 🔍\n\nCorpúsculos de Howell-Jolly:\n\nRestos de DNA nuclear em hemácias maduras\n\nNormalmente removidos pelo baço\n\nCorpúsculos de Heinz:\n\nHemoglobina precipitada (oxidação)\n\nVisíveis com coloração supravital\n\nHemácias nucleadas:\n\nEritroblastos na circulação periférica\n\nIndica: estresse medular ou hipoesplenismo\n\nDiagnóstico da Leucemia de Células Pilosas 🎯\n\nClínica: Esplenomegalia + pancitopenia + infecções\n\nMorfologia: \"Células pilosas\" com projeções citoplasmáticas\n\nImunofenotipagem: CD11c+, CD25+, CD103+\n\nHistoquímica: TRAP positivo (fosfatase ácida tartrato-resistente)\n\nDiagnóstico Diferencial 🔄\n\nOutras causas de hipoesplenismo:\n\nEsplenectomia cirúrgica\n\nAnemia falciforme (auto-esplenectomia)\n\nDoença celíaca grave\n\nInfiltração tumoral (linfomas, metástases)\n\nMnemônico Útil ✨\n\n\"Células Pilosas = Baço Infiltrado = Corpúsculos Livres\" (hipoesplenismo funcional)\n\nDica: Corpúsculos de Howell-Jolly = hipoesplenismo! Na leucemia de células pilosas = infiltração esplênica 🎯🔬","tags":["#Esplenomegalia","#Hematologia","#Hipoesplenismo","#LeucemiaCélulasPilosas","#Morfologia","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885720","ankiGuid":"G$wY?wDEk~"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-898bf2afd7f543c4","number":"1018a","sourceNumber":"1018a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"A reticulocitose é um bom indicador de eritropoiese. Assim, a anemia que costuma cursar com reticulocitose é","options":{"A":"Anemia carencial ferropriva.","B":"Anemia por deficiência de vitamina B12.","C":"Esferocitose hereditária.","D":"Anemia de Blackfan-Diamond.","E":"Talassemia."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":["question_bank/media/hematologia-introducao-ao-estudo-das-anemias/paste-2793d046c7186cae4dab9b47a01fc3ff4c4d1835.jpg","question_bank/media/hematologia-introducao-ao-estudo-das-anemias/paste-6d689b8695a7b231c30b8b643f6dfb5842e0096b.jpg","question_bank/media/hematologia-introducao-ao-estudo-das-anemias/paste-41dfdff71dc04e32b2cc0918d53fc3ef0fae433c.jpg","question_bank/media/hematologia-introducao-ao-estudo-das-anemias/paste-f75623bc8ee8570cfa3e8289b0093fe54f5aba94.jpg","question_bank/media/hematologia-introducao-ao-estudo-das-anemias/paste-c1356b4bd0510c12aa65322a5d1a27c0e43f882a.jpg","question_bank/media/hematologia-introducao-ao-estudo-das-anemias/paste-e0fa05179b7c339c1cfd63630b5502b14b2dae03.jpg"],"comment":"Classificação da Questão\n\nNível: 🟡 Média (Hematologia básica, classificação de anemias e reticulocitose).\n\nResumo Essencial\n\nReticulocitose indica eritropoiese aumentada em resposta à hemólise ou perda sanguínea aguda, sendo a esferocitose hereditária uma anemia hemolítica crônica compensada.\n\nCorreção Direta\n\n✅ Alternativa correta:\n\n\"Esferocitose hereditária\":\n\nJustificativa:\n\nAnemia hemolítica hereditária por defeito na espectrina/ankirina\n\nHemólise extravascular crônica → medula óssea compensatória\n\nReticulócitos >2-5% (normal <1-2%)\n\nEritropoiese acelerada para repor perda hemolítica\n\nTeste de fragilidade osmótica positivo\n\nErros nas Outras Alternativas ❌\n\n\"Anemia ferropriva\":\n\nReticulocitose baixa - falta ferro para síntese de Hb\n\n\"Deficiência B12\":\n\nReticulocitose baixa - megaloblástica com eritropoiese ineficaz\n\n\"Talassemia\":\n\nReticulocitose baixa/normal - defeito síntese globina\n\n\"Blackfan-Diamond\":\n\nReticulocitose baixa - aplasia pura série vermelha\n\nClassificação das Anemias 🩸\n\nCom reticulocitose (>2%):\n\nHemolíticas: Esferocitose, anemia falciforme, G6PD\n\nHemorragia aguda: Sangramento recente\n\nSem reticulocitose (<2%):\n\nCarenciais: Ferro, B12, folato\n\nCrônicas: Doença crônica, aplásica\n\nCongênitas: Talassemia, Blackfan-Diamond\n\nFisiopatologia da Esferocitose 🔴\n\nDefeito genético: Genes ANK1, SPTB, SPTA1\n\nPerda de membrana: Esferócitos → fragilidade osmótica\n\nHemólise esplênica: Baço reconhece células defeituosas\n\nCompensação medular: ↑ Eritropoiese → ↑ Reticulócitos\n\nÍndice Reticulocitário 📊\n\nFórmula: (Reticulócitos % × Ht paciente) / Ht normal\n\nCorrigido: Índice / fator maturação\n\n>2 = Regenerativa (hemólise/sangramento)\n\n<2 = Hiporregenerativa (produção ↓)\n\nDiagnóstico Diferencial Hemólise 🔬\n\nLaboratoriais: ↑LDH, ↑bilirrubina indireta, ↓haptoglobina\n\nEsferocitose: Esferócitos + fragilidade osmótica\n\nReticulocitose: Confirma resposta medular adequada\n\nMnemônico Útil ✨\n\n\"Hemólise = Hiper-produção!\" (reticulócitos altos compensam destruição)\n\nDica: Reticulocitose alta = Medula trabalhando! Hemólise (esferocitose) ou sangramento agudo fazem medula compensar. 🔴📈","tags":["#Anemia","#AnemiaHemolítica","#Diagnóstico","#Eritropoiese","#EsferocitoseHereditária","#Hematologia","#MedulaÓssea","#Reticulocitose","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885721","ankiGuid":"Iom#Wf!5:R"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-93439965c7c64def","number":"1019a","sourceNumber":"1019a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Paciente do sexo feminino, de 51 anos, queixa-se de cansaço e fraqueza há meses. O hemograma demonstra hemoglobina de 9.5 g/dL, hematócrito de 28.1%, VCM de 134 fL associado a reticulócitos baixos. O hematologista faz um esfregaço de sangue periférico e observa polimorfonucleados hipersegmentados com cerca de cinco a seis segmentações. O exame que mais contribuiria para o diagnóstico correto seria:","options":{"A":"dosagem de B12 e folato.","B":"biópsia da medula óssea.","C":"ferritina sérica.","D":"eletroforese de hemoglobina."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão\n\nNível: 🟢 Fácil (Diagnóstico clássico de anemia megaloblástica).\n\nResumo Essencial\n\nVCM 134 fL + neutrófilos hipersegmentados (>5 lobos) = anemia megaloblástica por deficiência de B12/folato.\n\nCorreção Direta\n\n✅ Alternativa correta:\n\n\"dosagem de B12 e folato\":\n\nJustificativa:\n\nVCM 134 fL: Macrocitose acentuada (>100 fL) sugere megaloblastose.\n\nNeutrófilos hipersegmentados (5-6 lobos): Patognomônico de deficiência B12/folato.\n\nReticulócitos baixos: Confirma eritropoese inefetiva megaloblástica.\n\nDosagem B12/folato: Exame diagnóstico definitivo para megaloblastose.\n\nErros nas Outras Alternativas ❌\n\nEletroforese de hemoglobina: Diagnostica hemoglobinopatias (talassemia, falciforme) - causam microcitose.\n\nFerritina sérica: Avalia deficiência de ferro - causa anemia microcítica (VCM <80).\n\nBiópsia de medula: Desnecessária quando B12/folato explicam o quadro - exame invasivo.\n\nFisiopatologia Megaloblástica\n\nB12/folato: Cofatores na síntese de DNA\n\nDeficiência → ↓ síntese DNA → divisão celular lenta\n\nRNA continua → células grandes (megaloblastos)\n\nNeutrófilos hipersegmentados: Maturação nuclear anormal\n\nAchados Característicos\n\nLaboratório: VCM >100 fL + reticulócitos baixos\n\nEsfregaço: Megaloblastos + neutrófilos hipersegmentados\n\nMedula: Hipercelular com megaloblastos\n\nCritérios Diagnósticos\n\nVCM >100 fL (especialmente >115 fL)\n\nNeutrófilos com >5 lobos em >5% das células\n\nB12 <200 pg/mL ou folato <2 ng/mL\n\nSequência Diagnóstica\n\nHemograma → macrocitose\n\nEsfregaço → hipersegmentação\n\nB12/folato → confirma deficiência específica\n\nMnemônico Útil ✨\n\n\"Macro + Hiper = B12 Folato\" - VCM alto + hipersegmentação = dosagem vitamínica.\n\nTags Temáticas\n\nDica: Hipersegmentação neutrofílica = Patognomônico! VCM >130 + neutrófilos >5 lobos = B12/folato sempre. 🎯🔬","tags":["#AnemiaMacrocítica","#AnemiaMegaloblástica","#B12Folato","#Folato","#Hematologia","#Hipersegmentação","#Megaloblástica","#VitaminaB12","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885722","ankiGuid":"M-t-U8i;>Q"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-bb918d7c4aea39bb","number":"1020a","sourceNumber":"1020a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Considerando os dados a seguir, referentes à anemia em adultos, relacione os tipos de anemia e as causas:\nTipos de anemia:\nI - Microcítica;\nII - Normocítica;\nIII - Macrocítica;\n\nCausas:\n( ) Doenças crônicas;\n( ) Deficiência de ferro;\n( ) Deficiência de vitamina B12;\n( ) Alcoolismo;\n( ) Talassemias.\n\nA sequência correta é:","options":{"A":"II, I, III, III, I","B":"I, I, III, II, III","C":"I, II, II, I, III","D":"II, I, II, I, I"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão 🟡\n\nDificuldade: Média (Amarela).\n\nJustificativa: A questão exige conhecimento sobre os tipos de anemia (microcítica, normocítica, macrocítica) e suas causas, com base no volume corpuscular médio (VCM). O raciocínio é intermediário, pois envolve associar corretamente cada causa ao tipo de anemia.\n\nResumo Essencial 📝\n\nA sequência correta é: II (normocítica), I (microcítica), III (macrocítica), III (macrocítica), I (microcítica).\n\nDoenças crônicas: Anemia normocítica (II).\n\nDeficiência de ferro: Anemia microcítica (I).\n\nDeficiência de vitamina B12: Anemia macrocítica (III).\n\nAlcoolismo: Anemia macrocítica (III).\n\nTalassemias: Anemia microcítica (I).\n\nExplicação do Gabarito ✅❌\n\nVamos correlacionar cada causa com o tipo de anemia, com base no volume corpuscular médio (VCM):\n\nDoenças crônicas → Normocítica (II).\n\nAnemia de doença crônica (ex.: artrite reumatoide, insuficiência renal) é tipicamente normocítica (VCM 80-100 fL), devido à produção inadequada de eritrócitos e inibição da eritropoese por citocinas inflamatórias. 🩺\n\nDeficiência de ferro → Microcítica (I).\n\nA deficiência de ferro causa anemia microcítica (VCM <80 fL), pois o ferro é essencial para a síntese de hemoglobina; eritrócitos tornam-se pequenos e hipocrômicos (ex.: anemia ferropriva). 🩺\n\nDeficiência de vitamina B12 → Macrocítica (III).\n\nA deficiência de vitamina B12 (ou folato) causa anemia macrocítica (VCM >100 fL), pois prejudica a síntese de DNA, levando a eritrócitos grandes e imaturos (ex.: anemia megaloblástica). 🩺\n\nAlcoolismo → Macrocítica (III).\n\nAlcoolismo crônico causa anemia macrocítica (VCM >100 fL), por toxicidade direta na medula óssea e deficiência de folato (frequente em alcoolistas); eritrócitos são grandes e disfuncionais. 🩺\n\nTalassemias → Microcítica (I).\n\nTalassemias (ex.: talassemia beta) causam anemia microcítica (VCM <80 fL), devido à produção deficiente de cadeias de globina, resultando em eritrócitos pequenos e hipocrômicos. 🩺\n\nSequência: (Doenças crônicas) II, (Deficiência de ferro) I, (Deficiência de B12) III, (Alcoolismo) III, (Talassemias) I → II, I, III, III, I.\n\nI, I, III, II, III ❌: Errado. Doenças crônicas não são microcíticas (I), e alcoolismo não é normocítico (II). 🩺🚫\n\nII, I, III, III, I ✅: Correta.\n\nII (normocítica) – Doenças crônicas.\n\nI (microcítica) – Deficiência de ferro.\n\nIII (macrocítica) – Deficiência de B12.\n\nIII (macrocítica) – Alcoolismo.\n\nI (microcítica) – Talassemias. 🩺\n\nII, I, II, I, I ❌: Errado. Deficiência de B12 não é normocítica (II), e alcoolismo não é microcítico (I). 🩺🚫\n\nI, II, II, I, III ❌: Errado. Doenças crônicas não são microcíticas (I), e deficiência de ferro não é normocítica (II). 🩺🚫\n\nVisualização: Microcítica (pequenos: ferro, talassemia), normocítica (normais: doenças crônicas), macrocítica (grandes: B12, alcoolismo) – a sequência II, I, III, III, I encaixa perfeitamente. 🩺🩺\n\nFoco nos Termos 🔬\n\nAnemia microcítica: VCM <80 fL; eritrócitos pequenos; causas incluem deficiência de ferro (ferropriva) e talassemias (defeito na globina). 🩺\n\nAnemia normocítica: VCM 80-100 fL; eritrócitos normais; comum em doenças crônicas (ex.: inflamação inibe eritropoese) ou hemólise. 🩺\n\nAnemia macrocítica: VCM >100 fL; eritrócitos grandes; causas incluem deficiência de B12/folato (megaloblástica) e alcoolismo (toxicidade medular). 🩺ulgação: Volume Corpuscular Médio (VCM): Medida do tamanho médio dos eritrócitos no hemograma; guia a classificação da anemia (microcítica, normocítica, macrocítica). 🩺\n\nDiagnóstico diferencial: Anemia requer investigação de causa subjacente; exames como ferro sérico, ferritina (deficiência de ferro), B12/folato (macrocítica) ou eletroforese de hemoglobina (talassemia) ajudam no diagnóstico. 🩺\n\nConexão clínica: Paciente com anemia deve ter VCM avaliado no hemograma para classificar o tipo (microcítica, normocítica, macrocítica), seguido de investigação da causa (ex.: ferritina para deficiência de ferro, B12/folato para macrocítica).\n\nSemiologia 🩺\n\nAnemia microcítica: Palidez, fadiga, glossite (deficiência de ferro); talassemias podem ser assintomáticas ou graves (ex.: talassemia maior). 🩺\n\nAnemia normocítica: Sintomas de doença de base (ex.: fadiga em insuficiência renal); sem alterações específicas no tamanho dos eritrócitos. 🩺\n\nAnemia macrocítica: Palidez, neuropatia (B12), glossite; alcoolismo pode ter sinais de hepatopatia (ex.: icterícia). 🩺\n\nFisiopatologia 📊\n\nMecanismo das anemias:\n\nMicrocítica: ↓ Ferro ou globina -> ↓ Hemoglobina -> Eritrócitos pequenos.\n\nNormocítica: Inflamação (doença crônica) -> ↓ Eritropoese -> Anemia moderada.\n\nMacrocítica: ↓ B12/folato ou toxicidade (álcool) -> ↓ Síntese de DNA -> Eritrócitos grandes.\n\nDiagrama: Causa -> Alteração no VCM -> Tipo de anemia.\n\nContexto adicional: Anemia de doença crônica é a segunda causa mais comum de anemia em adultos (após deficiência de ferro), prevalência de 10-20% em doenças inflamatórias.\n\nElementos Dinâmicos ✨\n\nConceito adicional: Talassemias são mais comuns em populações mediterrâneas, africanas e asiáticas (prevalência genética); a talassemia minor é leve, enquanto a maior requer transfusões.\n\nCuriosidade: A anemia megaloblástica (B12/folato) pode causar hipersegmentação de neutrófilos (vistos no esfregaço periférico), um achado clássico.\n\nMnemônico: Para tipos de anemia: “M.N.M.” – Microcítica (ferro, talassemia), Normocítica (doença crônica), Macrocítica (B12, álcool).\n\nFrase ilustrativa: “Microcítica: ferro ou talassemia; normocítica: doença crônica; macrocítica: B12 ou álcool!”\n\nDicas de Estudo 🔍\n\nVídeos: Busque no YouTube vídeos sobre “tipos de anemia VCM” ou “anemia microcítica macrocítica”.\n\nImagens: Pesquise no Google Imagens por “anemia VCM hemograma” ou “esfregaço periférico anemia megaloblástica”.\n\nGuias: Consulte livros de hematologia (ex.: Hoffman’s Hematology) ou clínica médica (ex.: Harrison’s Principles of Internal Medicine).","tags":["#AnemiaMacrocítica","#AnemiaMicrocítica","#AnemiaNormocítica","#Hematologia","#VCM","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885723","ankiGuid":"l1QpMf9gWi"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-d74cb8f87ba6197c","number":"1021a","sourceNumber":"1021a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Foram avaliados esfregaços de sangue periférico de cinco pacientes. Em um deles chamou atenção grande quantidade de eritrócitos em alvo (leptócitos). Trata-se provavelmente do individuo com diagnóstico de","options":{"A":"Fibrose medular.","B":"Hemoglobinopatia C.","C":"Talassemia minor.","D":"Cirrose hepática criptogenética.","E":"Doença falciforme."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão: 🟡 Média.\n\nJustificativa da Classificação: A questão requer a identificação da condição clínica mais provável associada à presença significativa de eritrócitos em alvo (leptócitos) no esfregaço de sangue periférico. Para responder corretamente, é necessário conhecer as alterações morfológicas das hemácias em diferentes condições hematológicas e hepáticas. Embora os leptócitos possam ser encontrados em várias situações, sua grande quantidade sugere fortemente uma condição específica.\n\nResumo Essencial: A presença de numerosos eritrócitos em alvo no sangue periférico é um achado morfológico sugestivo de certas hemoglobinopatias e outras condições que alteram a composição da membrana eritrocitária ou a relação superfície-volume da célula.\n\nExplicação do Gabarito Detalhada:\n\n❌ Hemoglobinopatia C. – Na hemoglobinopatia C, o esfregaço de sangue periférico tipicamente revela a presença de hemácias em alvo, mas também de cristais de hemoglobina C (formas hexagonais ou em barra) e um aumento de reticulócitos. Embora as hemácias em alvo estejam presentes, a descrição de \"grande quantidade\" sem menção aos cristais torna esta opção menos provável como a principal característica.\n\n✅ Doença falciforme. – Na doença falciforme, a principal característica morfológica no esfregaço de sangue periférico são as hemácias em foice (drepanócitos). No entanto, também podem ser observadas hemácias em alvo, especialmente em pacientes esplenectomizados ou com função esplênica reduzida. A descrição de \"grande quantidade\" de eritrócitos em alvo, embora não seja o achado primordial, pode ocorrer nesta condição devido a alterações na membrana eritrocitária e desidratação celular. É importante notar que a questão foca na \"grande quantidade\" de leptócitos como o achado que chamou a atenção.\n\n❌ Talassemia minor. – Na talassemia minor (traço talassêmico), o esfregaço de sangue periférico pode mostrar microcitose (hemácias pequenas), hipocromia (hemácias pálidas), anisocitose (variação no tamanho das hemácias) e poiquilocitose (variação na forma das hemácias), incluindo algumas hemácias em alvo. No entanto, a presença de uma \"grande quantidade\" de eritrócitos em alvo não é a característica predominante.\n\n❌ D. Cirrose hepática criptogenética. – Na cirrose hepática, incluindo a criptogenética, é comum observar macrocitose (hemácias grandes e arredondadas) e acantócitos (células espiculadas com projeções irregulares) devido a alterações no metabolismo lipídico e na membrana eritrocitária. Embora algumas hemácias em alvo possam estar presentes, não é o achado mais proeminente e em \"grande quantidade\".\n\n❌ Fibrose medular (Mielofibrose primária). – Na mielofibrose primária, o esfregaço de sangue periférico é caracterizado por leucoeritroblastose (presença de precursores de células vermelhas e brancas), dacriócitos (hemácias em lágrima) e anisopoiquilocitose significativa. Hemácias em alvo podem ser observadas, mas não em grande quantidade como o achado mais chamativo.\n\nFoco nos Termos-Chave 📖:\n\nEritrócitos em Alvo (Leptócitos): Hemácias com uma área central de hemoglobina, circundada por uma área pálida e, perifericamente, por outro anel de hemoglobina, lembrando um alvo. Essa morfologia ocorre quando há um aumento da relação superfície/volume da célula ou diminuição do conteúdo de hemoglobina em relação à membrana.\n\nHemoglobinopatia C: Doença hereditária causada por uma mutação no gene da beta-globina, resultando na produção de hemoglobina C anormal.\n\nDoença Falciforme: Doença hereditária causada por uma mutação no gene da beta-globina, resultando na produção de hemoglobina S anormal, que causa a falcização das hemácias em condições de baixa oxigenação.\n\nTalassemia Minor: Condição hereditária em que há produção reduzida de uma das cadeias da globina (alfa ou beta), levando a anemia leve e alterações morfológicas nas hemácias.\n\nCirrose Hepática Criptogenética: Cicatrização avançada do fígado de causa desconhecida.\n\nFibrose Medular (Mielofibrose Primária): Doença mieloproliferativa crônica caracterizada pela substituição da medula óssea por tecido fibroso, levando a alterações na produção de células sanguíneas e morfologia anormal no sangue periférico.\n\nSemiologia Aplicada 🩺\n\nA avaliação do esfregaço de sangue periférico é uma ferramenta valiosa na hematologia, fornecendo informações sobre a morfologia das células sanguíneas que podem auxiliar no diagnóstico de diversas condições. A descrição detalhada das alterações morfológicas, como a presença e quantidade de eritrócitos em alvo, é crucial para direcionar a investigação diagnóstica.\n\nFisiopatologia Descomplicada 🧬:\n\nFormação de Eritrócitos em Alvo: Pode ocorrer devido a:\n\nDiminuição do conteúdo de hemoglobina: Como na talassemia e algumas anemias ferropênicas.\n\nAumento da superfície da membrana em relação ao volume celular: Como após esplenectomia (o baço normalmente remove hemácias com excesso de membrana) e em algumas hemoglobinopatias (incluindo a doença falciforme e a hemoglobinopatia C).\n\nAlterações lipídicas na membrana: Como na doença hepática obstrutiva.\n\nNa doença falciforme, a desidratação das hemácias contendo hemoglobina S pode levar a um aumento da concentração de hemoglobina e à formação de hemácias em alvo. Além disso, a disfunção esplênica associada à doença falciforme prejudica a remoção de hemácias com alterações de membrana.\n\nElementos Dinâmicos para Fixação 🧠:\n\n💡 Frase Ilustrativa: \"O 'alvo' na hemácia pode 'acertar' várias condições, mas em 'grande quantidade', pense em 'S' de falciforme (e às vezes 'C'), ou na falta do 'filtro' esplênico.\"\n\nDicas de Estudo Adicionais 📚:\n\nAtlas de Hematologia: Consulte imagens de esfregaços de sangue periférico para visualizar as diferentes morfologias celulares em diversas condições.\n\nLivros de Hematologia: Estude as características morfológicas das anemias falciformes, talassemias, hemoglobinopatias e outras doenças hematológicas.\n\nArtigos de Revisão sobre Morfologia Eritrocitária: Aprofunde-se nas causas e significado clínico das alterações na forma das hemácias.","tags":["#CirroseHepática","#DoençaFalciforme","#EritrócitosEmAlvo","#EsfregaçoDeSanguePeriférico","#Hematologia","#Hemoglobinopatias","#Leptócitos","#Mielofibrose","#MorfologiaEritrocitária","#Talassemia","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885724","ankiGuid":"cL1x%P/!i;"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-14f96f123b682ac3","number":"1022a","sourceNumber":"1022a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"É exemplo de anemia microcítica:","options":{"A":"Anemia por doença renal.","B":"Deficiência de folato.","C":"Anemia sideroblástica.","D":"Mielodisplasia."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão: 🟡 Média\n\nJustificativa da Classificação: A questão exige conhecimento sobre a classificação morfológica das anemias (microcítica, normocítica, macrocítica) e a capacidade de associar diferentes etiologias a essa classificação. É necessário entender os mecanismos fisiopatológicos subjacentes a cada condição listada para determinar qual delas tipicamente cursa com diminuição do tamanho dos eritrócitos.\n\nResumo Essencial: As anemias são classificadas de acordo com o tamanho médio dos glóbulos vermelhos (VCM). Anemias microcíticas são caracterizadas por eritrócitos menores que o normal, geralmente devido a problemas na síntese de hemoglobina. É fundamental diferenciar as causas de anemia microcítica para um diagnóstico e tratamento adequados.\n\nExplicação do Gabarito Detalhada:\n\n✅ Anemia sideroblástica – Nesta condição, apesar de haver ferro disponível, ocorre um defeito na incorporação do ferro ao heme (componente da hemoglobina) dentro da medula óssea. Isso leva à produção de glóbulos vermelhos menores (microcíticos) e frequentemente hipocrômicos (com menos cor, devido à menor quantidade de hemoglobina funcional). O ferro não utilizado se acumula nas mitocôndrias dos precursores eritroides, formando os sideroblastos em anel, um achado característico.\n\n❌ Anemia por doença renal – A anemia na doença renal crônica é tipicamente normocítica e normocrômica. A principal causa é a diminuição da produção de eritropoetina (hormônio que estimula a produção de glóbulos vermelhos) pelos rins doentes. Embora em alguns casos possa haver outros fatores contribuintes, como deficiência de ferro devido à perda sanguínea ou inflamação crônica, a característica primária não é a microcitose.\n\n❌ Mielodisplasia – As síndromes mielodisplásicas são um grupo heterogêneo de distúrbios da medula óssea caracterizados por produção ineficaz de células sanguíneas. A anemia associada pode ser macrocítica, normocítica ou, menos frequentemente, microcítica. A morfologia das células sanguíneas é frequentemente anormal, com variações no tamanho e forma (anisopoiquilocitose), mas a microcitose não é a apresentação típica de todas as formas de mielodisplasia.\n\n❌ Deficiência de folato – A deficiência de folato causa uma anemia macrocítica, também conhecida como anemia megaloblástica. O folato é essencial para a síntese de DNA, e sua deficiência leva a uma maturação nuclear mais lenta em comparação com a maturação citoplasmática dos precursores eritroides, resultando em células maiores que o normal (macrócitos).\n\nFoco nos Termos-Chave 📖:\n\nAnemia microcítica: 🩸 Tipo de anemia caracterizada por glóbulos vermelhos com um volume corpuscular médio (VCM) abaixo do normal. Isso indica que os eritrócitos são menores do que o esperado.\n\nHemoglobina: 🧬 Proteína presente nos glóbulos vermelhos responsável pelo transporte de oxigênio. Sua síntese envolve a incorporação de ferro ao heme.\n\nEritropoetina: 🧪 Hormônio produzido principalmente pelos rins que estimula a medula óssea a produzir mais glóbulos vermelhos.\n\nMielodisplasia: 🦴 Grupo de doenças em que a medula óssea não produz células sanguíneas maduras e saudáveis em quantidade suficiente.\n\nFolato: 💊 Vitamina do complexo B essencial para a síntese de DNA e divisão celular. Sua deficiência afeta principalmente células com alta taxa de proliferação, como os precursores eritroides.\n\nSideroblasto em anel: 🔬 Precursor eritroide na medula óssea com um acúmulo anormal de grânulos de ferro ao redor do núcleo, visualizado na coloração de Perls. É um achado característico da anemia sideroblástica.\n\nFisiopatologia Descomplicada 🧬:\nNa anemia sideroblástica:\nFerro Disponível → Defeito na Incorporação ao Heme (enzimas mitocondriais) → Diminuição da Hemoglobina Intracelular → Eritrócitos Menores (Microcíticos) + Acúmulo de Ferro nas Mitocôndrias dos Precursores → Sideroblastos em Anel.\n\nElementos Dinâmicos para Fixação 🧠:\n💡 Frase Ilustrativa: \"Na anemia sideroblástica, o ferro é como um tijolo disponível, mas a 'argamassa' (incorporação ao heme) está com defeito, resultando em 'tijolos' menores e ferro 'sobrando' nas 'paredes' da medula.\"\n\nDicas de Estudo Adicionais 📚:\n\nRevise a classificação morfológica das anemias (VCM e HCM).\n\nEstude as principais causas de anemia microcítica: deficiência de ferro, talassemia, anemia sideroblástica e anemia de doença crônica (em alguns casos).\n\nCompare e contraste as características laboratoriais e clínicas dessas diferentes anemias.","tags":["#Anemia","#Fisiopatologia","#Hematologia","#Microcítica","#Sideroblástica","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885725","ankiGuid":"y16}C3p_+d"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-436df2a227790385","number":"1023a","sourceNumber":"1023a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"A morfologia dos eritrócitos é de grande valor no diagnóstico das anemias. A presença de corpúsculos de Heinz nos eritrócitos indica","options":{"A":"Agente citotóxico.","B":"Acúmulo de glicogênio.","C":"Precipitação de hemoglobina anormal.","D":"Defeito no citoesqueleto celular."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão\n🟢 Nível: Fácil\nJustificativa: A questão aborda a morfologia eritrocitária e sua relevância diagnóstica em anemias, especificamente a causa da presença de corpúsculos de Heinz. O eixo cobrado é hematologia.\nResumo Essencial\nA presença de corpúsculos de Heinz nos eritrócitos é um achado morfológico específico que indica uma determinada condição relacionada à hemoglobina.\nCorreção Direta e Estruturada\n✅ Os corpúsculos de Heinz são inclusões intracitoplasmáticas nos eritrócitos compostas por hemoglobina desnaturada e precipitada. Sua formação ocorre devido ao estresse oxidativo excessivo ou à presença de hemoglobinas instáveis ou anormais, que são mais suscetíveis à desnaturação.\n\n❌ Agentes citotóxicos podem causar anemia por diversos mecanismos (supressão da medula óssea, hemólise), mas não levam diretamente à formação específica de corpúsculos de Heinz.\n\n❌ Defeitos no citoesqueleto celular, como na esferocitose hereditária ou eliptocitose, causam alterações na forma dos eritrócitos (esferócitos, eliptócitos), mas não a formação de corpúsculos de Heinz.\n\n❌ O acúmulo de glicogênio nos eritrócitos é característico de algumas enzimopatias raras, como a doença de Andersen (glicogenose tipo IV), e não se manifesta como corpúsculos de Heinz.\nFoco em Conteúdo Médico Relevante\nOs corpúsculos de Heinz são visualizados na coloração supravital (azul de metileno ou cristal violeta), pois não são corados pelo corante de Wright utilizado na coloração padrão do esfregaço sanguíneo. Sua presença sugere:\n\nDeficiência de enzimas da via das pentoses fosfato: Principalmente a deficiência de glicose-6-fosfato desidrogenase (G6PD), que torna os eritrócitos mais vulneráveis ao dano oxidativo.\n\nHemoglobinas instáveis: Variantes de hemoglobina com estrutura anormal que se desnaturam mais facilmente sob estresse oxidativo.\n\nExposição a agentes oxidantes: Certas drogas (sulfonamidas, dapsona, primaquina), toxinas ou alimentos (fava em indivíduos com deficiência de G6PD) podem induzir estresse oxidativo e formação de corpúsculos de Heinz.\n\nOs eritrócitos contendo corpúsculos de Heinz são frequentemente removidos prematuramente pelo baço, levando à anemia hemolítica.\nVisualização e Didática\nAnalogia: Imagine as moléculas de hemoglobina como novelos de lã bem enrolados dentro do glóbulo vermelho. Em condições normais, eles permanecem assim. No entanto, sob estresse oxidativo ou se a \"lã\" for de má qualidade (hemoglobina anormal), os novelos começam a se desfazer e a se aglomerar em \"nós\" dentro da célula – esses \"nós\" são os corpúsculos de Heinz.\nGlossário Breve de Termos-Chave 📖\n🟢 Eritrócitos: Glóbulos vermelhos, células sanguíneas responsáveis pelo transporte de oxigênio.\n🟢 Corpúsculos de Heinz: Inclusões intracitoplasmáticas nos eritrócitos compostas por hemoglobina desnaturada e precipitada.\n🟢 Anemia: Condição caracterizada pela redução do número de eritrócitos, da concentração de hemoglobina ou do hematócrito, resultando em diminuição da capacidade de transporte de oxigênio pelo sangue.\n🟢 Agente Citotóxico: Substância tóxica para as células, capaz de causar sua morte ou dano.\n🟢 Citoesqueleto Celular: Rede de proteínas que dá forma e suporte estrutural à célula.\n🟢 Hemoglobina: Proteína presente nos eritrócitos que se liga ao oxigênio.\n🟢 Desnaturação: Perda da estrutura tridimensional funcional de uma proteína.\n🟢 Estresse Oxidativo: Desequilíbrio entre a produção de radicais livres e a capacidade do organismo de neutralizá-los.\n🟢 Via das Pentoses Fosfato: Via metabólica importante para a produção de NADPH, essencial para proteger os eritrócitos contra o dano oxidativo.\n🟢 Glicose-6-Fosfato Desidrogenase (G6PD): Enzima chave na via das pentoses fosfato. Sua deficiência é a enzimopatia humana mais comum.\n🟢 Hemoglobinas Instáveis: Variantes de hemoglobina com estrutura alterada que as torna mais propensas à desnaturação.\n🟢 Coloração Supravital: Técnica de coloração utilizada em células vivas ou recém-mortas para visualizar estruturas específicas que não são bem coradas pelas técnicas padrão.\n🟢 Coloração de Wright: Corante utilizado na hematologia para colorir esfregaços sanguíneos.\n🟢 Baço: Órgão do sistema linfático responsável pela filtração do sangue e remoção de células sanguíneas danificadas ou anormais.\n🟢 Anemia Hemolítica: Anemia causada pela destruição prematura dos eritrócitos.\nElementos Clínicos Aplicáveis 🩺\nA identificação de corpúsculos de Heinz no esfregaço sanguíneo, com coloração supravital, é um achado importante para o diagnóstico diferencial de anemias hemolíticas, especialmente em pacientes com história de uso de certas medicações, exposição a agentes oxidantes ou suspeita de deficiência de G6PD ou hemoglobinopatias instáveis. A investigação laboratorial adicional (dosagem de G6PD, eletroforese de hemoglobina) é fundamental para confirmar o diagnóstico etiológico.","tags":["#Anemia","#CorpúsculosDeHeinz","#Diagnóstico","#Eritrócitos","#EstresseOxidativo","#G6PD","#Hematologia","#Hemoglobina","#Hemoglobinopatias","#MorfologiaEritrocitária","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885726","ankiGuid":"r(#^v/W>%3"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-204649930e94f35f","number":"1024a","sourceNumber":"1024a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Criança de 1 ano e 6 meses, é trazida pela mãe com histórico de choro freqüente em crises, sem fator desencadeante óbvio e melhora espontânea. Desde seu nascimento, vários episódios de \"infecções\", tratados sempre sob orientação médica e nos últimos15 dias amarelamento da pele e dos olhos, com duração de 5 dias e melhora espontânea. Foi solicitado um hemograma, e durante a análise foi visualizada a seguinte imagem:\n\nDiante do exposto, o achado na lâmina e a hipótese diagnóstica são:","options":{"A":"Presença de linfoblasto, hipótese diagnóstica de Leucemia Linfóide Aguda.","B":"Pesença de reticulocitose, hipótese diagnóstica de Anemia Hemolítica.","C":"Presença de poiquilocitose, hipótese diagnóstica de Anemia Falciforme.","D":"Presença de microcitose, hipótese diagnóstica de Anemia Ferropriva."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":["question_bank/media/hematologia-introducao-ao-estudo-das-anemias/paste-463145d17c3e01aa72ee673d5ab36381673a6ede.jpg"],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão\n\nNível: 🔴 Difícil\n\nEixos: Hematologia Pediátrica, Diagnóstico Diferencial, Anemia, Interpretação de Hemograma.\n\nJustificativa: Requer integração de achados clínicos (icterícia intermitente, crises de choro) com análise de lâmina hematológica e formulação de hipóteses diagnósticas, considerando causas de anemia em criança.\n\nResumo Essencial\n\nPaciente: Criança de 1 ano e 6 meses com crises de choro (sugestivo de dor), icterícia intermitente (5 dias, melhora espontânea), e história de “infecções” (possíveis crises hemolíticas).\n\nAchado na lâmina: Não descrito visualmente, mas a alternativa correta sugere poiquilocitose (células falciformes), apontando para anemia falciforme.\n\nDiagnóstico: Anemia falciforme, com poiquilocitose (eritrócitos em foice) como achado típico.\n\nCorreção Direta e Estruturada\n\n✅ Resposta correta: Presença de poiquilocitose, hipótese diagnóstica de Anemia Falciforme\n\nExplicação: Poiquilocitose (variação na forma dos eritrócitos, ex.: células falciformes) é característica da anemia falciforme, uma hemoglobinopatia que causa hemólise crônica, icterícia intermitente (↑ bilirrubina indireta por hemólise), crises dolorosas (vaso-oclusivas, explicando choro) e infecções frequentes (devido a asplenia funcional).\n\nJustificativa técnica: A icterícia transitória e crises de choro em criança jovem são compatíveis com crises hemolíticas/vaso-oclusivas da anemia falciforme. Poiquilocitose com células falciformes na lâmina confirma o diagnóstico (UpToDate, 2023).\n\n❌ Presença de reticulocitose, hipótese diagnóstica de Anemia Hemolítica\n\nErro: Embora reticulocitose (↑ reticulócitos) esteja presente em anemias hemolíticas, incluindo falciforme, o achado mais específico na lâmina é poiquilocitose (células falciformes). O diagnóstico “anemia hemolítica” é genérico, não específico para falciforme.\n\n❌ Presença de microcitose, hipótese diagnóstica de Anemia Ferropriva\n\nErro: Microcitose (eritrócitos pequenos, VCM <80 fL) é típica de anemia ferropriva, mas não explica icterícia ou crises dolorosas; lâmina de falciforme mostra células em foice, não microcitose.\n\n❌ Presença de linfoblasto, hipótese diagnóstica de Leucemia Linfóide Aguda\n\nErro: Linfoblastos sugerem leucemia, mas não há sintomas de leucemia (ex.: febre persistente, hematomas, linfadenopatia). Icterícia e crises dolorosas apontam para hemólise, não leucemia.\n\nMecanismos Fisiopatológicos\n\nAnemia falciforme:\n\nMecanismo: Mutação no gene da beta-globina (HbS) → hemoglobina anormal → eritrócitos em foice → hemólise crônica (↑ bilirrubina indireta, icterícia) e crises vaso-oclusivas (dor, choro).\n\nSequência: Hemólise → ↑ bilirrubina indireta → icterícia; obstrução vascular → crises dolorosas; asplenia funcional → infecções.\n\nPoiquilocitose: Presença de células falciformes na lâmina, visíveis em esfregaço periférico, devido à polimerização da HbS em condições de hipóxia.\n\nDiagnósticos Diferenciais\n\nAnemia hemolítica autoimune: Icterícia e hemólise, mas com teste de Coombs positivo, menos comum em crianças tão jovens.\n\nTalassemia: Microcitose e hemólise, mas sem crises vaso-oclusivas ou poiquilocitose falciforme.\n\nLeucemia linfóide aguda: Linfoblastos na lâmina, com sintomas sistêmicos (febre, hematomas), não descritos.\n\nAprofundamento\n\nDiagnóstico confirmatório: Eletroforese de hemoglobina (detecta HbS); esfregaço periférico com células falciformes; ↑ reticulócitos e bilirrubina indireta.\n\nEvidências recentes: Triagem neonatal para HbS (teste do pezinho) reduz mortalidade por infecções em anemia falciforme (Pediatrics, 2024).\n\nComplicações: Crises vaso-oclusivas, infecções (ex.: Streptococcus pneumoniae), síndrome torácica aguda.\n\nPor que os alunos erram?\n\nAssociam icterícia apenas a anemia hemolítica genérica ou leucemia, sem considerar poiquilocitose específica da falciforme.\n\nConfundem microcitose (ferropriva) com achados de hemoglobinopatias.\n\nUma comparação ou ilustração\n\nAnalogia: Anemia falciforme é como “canos entupidos” (crises vaso-oclusivas) e “filtro danificado” (hemólise), com células em foice visíveis na lâmina como “peças tortas”.\n\nRecurso Extra\n\n💡 Frase ilustrativa: “Icterícia, crises de dor, células em foice? Anemia falciforme na lâmina!”\n\nGlossário de Termos-Chave 📖\n\nPoiquilocitose: Variação na forma dos eritrócitos (ex.: células falciformes).\n\nAnemia falciforme: Hemoglobinopatia com HbS, causando hemólise e crises vaso-oclusivas.\n\nIcterícia: Coloração amarelada por ↑ bilirrubina (indireta em hemólise).\n\nElementos Clínicos Aplicáveis 🩺\n\nAchados semiológicos: Icterícia intermitente, crises de choro (dor vaso-oclusiva), história de infecções.\n\nExames: Hemograma (poiquilocitose, anemia), eletroforese de hemoglobina, bilirrubina indireta, reticulócitos.\n\nConduta: Hidratação, analgesia (crises dolorosas), profilaxia antibiótica (ex.: penicilina), vacina pneumocócica, ácido fólico.\n\nSugestão de Estudo 📚\n\nGuideline: “Management of Sickle Cell Disease” (NHLBI, 2023).\n\nLivro: “Nelson Textbook of Pediatrics”, capítulo sobre hemoglobinopatias.","tags":["#AnemiaFalciforme","#AnemiaHemolítica","#CriseVasoOclusiva","#DiagnósticoHematológico","#Drepanócitos","#Hemoglobinopatia","#Icterícia","#Pediatria","#Poiquilocitose","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885727","ankiGuid":"FixQ-#0MmG"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-a62aec136f9a1cdc","number":"1025a","sourceNumber":"1025a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Mulher de 25 anos com história de cansaço aos grandes esforços apresenta os seguintes resultados laboratoriais:\n\nHb = 12 g/dL\nVCM = 58 fL (microcitose)\nHCM = 28 pg (hipocromia)\nRDW = 12% (normal)\nFerro sérico = 150 µg/dL (normal)\nTIBC = 320 µg/dL (normal)\nEsfregaço de sangue periférico: hemácias em alvo, microcitose e hipocromia.\n\nQual exame hematológico deve ser solicitado para confirmar o diagnóstico?","options":{"A":"Eletroforese de hemoglobina","B":"Dosagem de ferritina sérica","C":"Mielograma para pesquisa de sideroblastos em anel","D":"Prova de Coombs direta","E":"Dosagem de vitamina B12 e folato"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão\n\nNível: 🟡 Média (Diagnóstico diferencial de anemia microcítica - talassemia vs anemia ferropriva).\n\nResumo Essencial\n\nMicrocitose + hipocromia com ferro normal e RDW normal em paciente jovem sugere talassemia minor, confirmada por eletroforese de hemoglobina.\n\nCorreção Direta\n\n✅ Alternativa correta:\n\n\"Eletroforese de hemoglobina\":\n\nJustificativa:\n\nPadrão clássico de talassemia minor:\n\nMicrocitose desproporcional (VCM 58 fL vs Hb 12 g/dL)\n\nRDW normal (12%) - diferencial chave\n\nFerro sérico normal (150 µg/dL)\n\nHemácias em alvo no esfregaço\n\nEletroforese confirma:\n\nβ-talassemia minor: ↑ HbA2 (>3,5%) ± ↑ HbF\n\nα-talassemia: HbA2 normal, mas microcitose + hemácias em alvo\n\nDiagnóstico diferencial: Exclui anemia ferropriva (ferro normal)\n\nErros nas Outras Alternativas ❌\n\nDosagem de ferritina:\n\nDesnecessário: Ferro sérico já normal, descarta deficiência de ferro.\n\nProva de Coombs direta:\n\nIrrelevante: Investiga anemia hemolítica autoimune, não microcitose.\n\nMielograma para sideroblastos:\n\nInadequado: Anemia sideroblástica é rara e geralmente adquirida (não em jovem de 25 anos).\n\nB12 e folato:\n\nErro: Causam macrocitose (VCM >100 fL), não microcitose.\n\nTalassemia vs Anemia Ferropriva 🔍\n\nTalassemia minor:\n\nRDW normal (11-15%)\n\nFerro/ferritina normais\n\nHemácias em alvo\n\nMicrocitose desproporcional (VCM muito baixo, Hb pouco reduzida)\n\nAnemia ferropriva:\n\nRDW elevado (>15%) - anisocitose\n\nFerro/ferritina baixos\n\nMicrocitose proporcional à anemia\n\nÍndices Diagnósticos 📊\n\nÍndice de Mentzer: VCM/contagem de hemácias\n\n<13: Sugere talassemia\n\n>13: Sugere anemia ferropriva\n\nÍndice RDW: RDW × VCM/Hb\n\n<220: Talassemia\n\n>220: Anemia ferropriva\n\nEletroforese - Resultados Esperados 🧬\n\nβ-talassemia minor:\n\nHbA2: 3,5-7% (normal: 2-3%)\n\nHbF: 1-5% (pode estar normal)\n\nα-talassemia:\n\nHbA2 normal, diagnóstico por biologia molecular\n\nMnemônico Útil ✨\n\n\"RDW Tell\": RDW normal Tells talassemia (RDW normal = talassemia)\n\nDica: RDW normal + microcitose + ferro normal = talassemia! Eletroforese é padrão-ouro para confirmar. 🧬📊","tags":["#AnemiaMicrocítica","#DiagnósticoDiferencial","#DiagnósticoLaboratorial","#EletroforeseDeHemoglobina","#EletroforeseHemoglobina","#Hematologia","#Talassemia","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885728","ankiGuid":"I`UP@==wAH"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-fea505edca4f9803","number":"1026a","sourceNumber":"1026a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Mulher de 25 anos com história de cansaço aos grandes esforços apresenta os seguintes achados:\n\nHb = 12 g/dL\nVCM = 58 fL (microcitose)\nHCM = 28 pg (hipocromia)\nRDW = 12% (normal)\nFerro sérico = 150 µg/dL (normal)\nTIBC = 320 µg/dL (normal)\nEsfregaço de sangue periférico: hemácias em alvo.\n\nQuais são as quatro causas mais comuns de anemia que cursam com microcitose e hipocromia?","options":{"A":"Deficiência de ferro, talassemia, anemia de doença crônica e anemia sideroblástica","B":"Deficiência de vitamina B12, anemia hemolítica, talassemia e anemia aplástica","C":"Anemia megaloblástica, anemia perniciosa, talassemia e deficiência de folato","D":"Anemia de doença renal, anemia aplástica, deficiência de cobre e talassemia","E":"Deficiência de ferro, anemia hemolítica autoimune, anemia de Fanconi e talassemia"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão\n\nNível: 🟡 Média (Diagnóstico diferencial de anemia microcítica e hipocrômica).\n\nResumo Essencial\n\nAs 4 causas mais comuns de anemia microcítica (VCM <80 fL) e hipocrômica (HCM <27 pg) são:\n\nDeficiência de ferro (mais frequente).\n\nTalassemia minor (hemácias em alvo, RDW normal, ferro sérico normal).\n\nAnemia de doença crônica (ferro sérico normal/baixo, TIBC normal/baixa).\n\nAnemia sideroblástica (ferro sérico elevado, sideroblastos em anel na medula).\n\nCorreção Direta\n\n✅ Alternativa correta:\n\nDeficiência de ferro, talassemia, anemia de doença crônica e anemia sideroblástica.\n\nAnálise do Caso\n\nDados laboratoriais:\n\nHb 12 g/dL (anemia leve).\n\nVCM 58 fL + HCM 28 pg (microcitose e hipocromia acentuadas).\n\nFerro sérico e TIBC normais (exclui deficiência de ferro clássica).\n\nRDW normal (sugere talassemia ou anemia sideroblástica).\n\nHemácias em alvo (típico de talassemia).\n\nDiagnóstico mais provável: Talassemia minor (alfa ou beta).\n\nExclusão das Outras Opções ❌\n\nAnemia hemolítica autoimune/Fanconi: Normocítica ou macrocítica.\n\nDeficiência de B12/anemia megaloblástica: Macrocítica (VCM >100 fL).\n\nAnemia aplástica: Normocítica, sem microcitose.\n\nDeficiência de cobre: Pode causar microcitose, mas é rara.\n\nConfirmação Diagnóstica\n\nTalassemia:\n\nEletroforese de Hb (aumento de HbA2 em beta-talassemia).\n\nPCR para mutações genéticas.\n\nAnemia sideroblástica:\n\nMedula óssea (sideroblastos em anel).\n\nMnemônico Útil ✨\n\n\"Micro-Hipo: Ferro, Talassemia, Doença Crônica, Sideroblástica\".\n\nConduta\n\nTalassemia minor: Geralmente não requer tratamento.\n\nDeficiência de ferro: Suplementação oral.\n\nAnemia de doença crônica: Tratar a causa base.\n\nDica: RDW normal + microcitose extrema + hemácias em alvo = Pense primeiro em talassemia! 🩸🔍","tags":["#AnemiaMicrocítica","#DiagnósticoDiferencial","#Hematologia","#MedicinaInterna","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885729","ankiGuid":"v4MhnEkPrl"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-c65ce9d37c99abe6","number":"1027a","sourceNumber":"1027a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"São causas de anemias macrocíticas:","options":{"A":"Anemias hemolíticas congênitas e anemia megaloblástica.","B":"Anemia sideroblástica e deficiência de ferro.","C":"Envenenamento por chumbo e síndromes talassêmicas.","D":"Anemia por deficiência de tiamina e síndrome mielodisplásica.","E":"Síndromes talassêmicas e anemia hemolítica adquirida."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão\n\nNível: 🟡 Média\n\nEixos: Hematologia, Fisiopatologia, Diagnóstico Diferencial.\n\nResumo Essencial\n\nAnemia macrocítica: Eritrócitos com VCM >100 fL, causada por deficiência de vitamina B12/folato (anemia megaloblástica) ou hemólise congênita (ex.: esferocitose).\n\nCorreção Direta e Estruturada\n\n✅ Resposta correta: Anemias hemolíticas congênitas e anemia megaloblástica.\n\nJustificativa: Anemia megaloblástica (deficiência de B12/folato) causa macrocitose por falha na síntese de DNA. Hemólise congênita (ex.: esferocitose) leva a macrocitose por aumento de reticulócitos (eritrócitos jovens, maiores).\n\n❌ Alternativas incorretas:\n\nTalassêmicas e hemolítica adquirida: Talassêmicas são microcíticas; hemolítica adquirida pode ser normocítica.\n\nSideroblástica e deficiência de ferro: Ambas causam anemia microcítica.\n\nEnvenenamento por chumbo e talassêmicas: Ambas resultam em microcitose.\n\nDeficiência de tiamina e mielodisplásica: Tiamina não causa anemia macrocítica; mielodisplásica pode, mas não é a melhor associação.\n\nMecanismos Fisiopatológicos\n\nAnemia megaloblástica: Deficiência de B12/folato → falha na síntese de DNA → maturação nuclear atrasada → eritrócitos grandes (macrócitos).\n\nHemólise congênita: Destruição de eritrócitos → aumento de reticulócitos (maiores que eritrócitos maduros) → VCM elevado.\n\nProgressão: Estímulo eritropoético → liberação precoce de reticulócitos → macrocitose.\n\nDiagnósticos Diferenciais\n\nSíndrome mielodisplásica: Macrocitose possível, mas com dismorfismo eritroide.\n\nHipotireoidismo: Macrocitose leve, sem megaloblastos.\n\nDoença hepática: Macrocitose por alterações metabólicas, não megaloblástica.\n\nPor que os alunos erram?\n\nConfundem microcitose (talassemia, ferropriva) com macrocitose.\n\nAssociam tiamina a anemias macrocíticas, ignorando sua irrelevância hematológica.\n\nRecurso Extra\n\n💡 Dica clínica: \"Macrocitose com VCM >100? Pense em B12/folato ou hemólise com reticulócitos.\"\n\nElementos Clínicos Aplicáveis 🩺\n\nSemiologia: Palidez, icterícia (hemólise), glossite (B12).\n\nExames: Hemograma (VCM >100 fL), reticulócitos, dosagem de B12/folato, esfregaço (megaloblastos ou esferócitos).\n\nConduta: Repor B12/folato (megaloblástica); tratar causa de hemólise (ex.: ácido fólico, esplenectomia).\n\nGlossário de Termos-Chave 📖\n\nMacrocitose: VCM >100 fL, eritrócitos maiores que o normal.\n\nAnemia megaloblástica: Macrocitose por deficiência de B12/folato, com megaloblastos na medula.\n\nHemólise congênita: Destruição eritrocitária por defeitos genéticos (ex.: esferocitose).\n\nSugestão de Estudo 📚\n\nCapítulo de Anemias do \"Williams Hematology\".\n\nArtigo: \"Megaloblastic Anemia\" (UpToDate).","tags":["#AnemiaMacrocítica","#Hematologia","#Hemólise","#Megaloblástica","#Reticulócitos","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885730","ankiGuid":"QX=&-F,Ql}"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-25ee60d123782aaf","number":"1028a","sourceNumber":"1028a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Em ambulatório de atenção básica você recebe paciente para investigação de anemia com perfil microcítico. Considere a alternativa incorreta:","options":{"A":"A anemia ferropriva é a causa mais comum de anemia na população geral","B":"Talassemia minor é diagnóstico diferencial de anemia microcítica","C":"Anemia por deficiência de Vitamina B12 apresenta-se, em geral com macrocitose","D":"A avaliação de doenças crônicas e de perda sanguínea como hipermenorréia ou sintomas de sangramento digestivo são importantes na investigação etiológica das anemias","E":"Comprovando-se anemia ferropriva, a baixa ingesta de ferro, por exemplo, em dietas vegetarianas, é a principal etiologia"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão\n\nNível: 🟡 Média (Diagnóstico diferencial de anemia microcítica e investigação etiológica).\n\nResumo Essencial\n\nAnemia ferropriva tem como principal causa a perda sanguínea (não deficiência dietética), especialmente sangramento digestivo e hipermenorréia.\n\nCorreção Direta\n\n✅ Alternativa incorreta:\n\n\"Baixa ingesta de ferro é a principal etiologia da anemia ferropriva\":\n\nPor que está incorreta:\n\nPrincipal causa: Perda sanguínea crônica (70-80% dos casos)\n\nMulheres: Hipermenorréia (ciclos >80ml ou >7 dias)\n\nHomens/pós-menopausa: Sangramento digestivo (neoplasias, úlceras, parasitoses)\n\nDeficiência dietética: Representa apenas 10-15% dos casos\n\nAbsorção prejudicada: Doença celíaca, gastrectomia, uso de IBP\n\nAlternativas Corretas ✅\n\nInvestigação de doenças crônicas e perda sanguínea:\n\nCorreto: Sempre investigar sangramento oculto (colonoscopia, EDA) e doenças inflamatórias.\n\nAnemia ferropriva é a mais comum:\n\nCorreto: Representa 50% de todas as anemias mundialmente.\n\nB12 causa macrocitose:\n\nCorreto: VCM >100 fL é típico da anemia megaloblástica.\n\nTalassemia minor é diagnóstico diferencial:\n\nCorreto: Causa microcitose desproporcional à anemia (VCM muito baixo com Hb pouco reduzida).\n\nInvestigação da Anemia Microcítica 🔍\n\n1º passo: Ferritina sérica\n\n<15 ng/mL (mulheres) ou <30 ng/mL (homens) = deficiência de ferro\n\n2º passo: Se ferritina normal → eletroforese de hemoglobina (talassemia)\n\n3º passo: Saturação de transferrina + receptor solúvel de transferrina\n\nCausas de Anemia Microcítica 📊\n\nAnemia ferropriva (80%)\n\nTalassemia (15%)\n\nAnemia de doença crônica (5%)\n\nAnemia sideroblástica (<1%)\n\nInvestigação de Perda Sanguínea 🩸\n\nMulheres pré-menopausa: História menstrual detalhada\n\nHomens/pós-menopausa: Colonoscopia + EDA (obrigatório)\n\nPesquisa de sangue oculto: Pouco sensível, não exclui neoplasia\n\nMnemônico Útil ✨\n\n\"TAILS\": Talassemia, Anemia ferropriva, Inflamação crônica, Lead poisoning, Sideroblástica\n\nDica: Anemia ferropriva = sempre pensar em perda sanguínea primeiro! Deficiência dietética é rara em adultos. 🩸🔍","tags":["#AnemiaFerropriva","#AnemiaMicrocítica","#AtençãoBásica","#DiagnósticoDiferencial","#Ferropriva","#Hematologia","#Talassemia","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885731","ankiGuid":"o?2T60en?9"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-8863d6a3ce49e344","number":"1029a","sourceNumber":"1029a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Correlacione alterações encontradas no hemograma com a patologia:\n\nI. Hemácias em alvo;\nII. Hemácias em rouleaux;\nIII. Esquizócitos;\nIV. Dacriócitos;\n\na. Síndrome hemolítica urêmica;\nb. Hemoglobinopatia C;\nc. Mielofribose;\nd. Mieloma múltiplo;","options":{"A":"Id, IIc, IIIa e IVb","B":"Ib, IIc, IIIa e IVd","C":"Id, IIa, IIIc e IVb","D":"Ic, IId, IIIb e IVa","E":"Ib, IId, IIIa e IVc"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":["question_bank/media/hematologia-introducao-ao-estudo-das-anemias/paste-123f34f304978d7c83d2725a0460cfb4f9818cc2.jpg","question_bank/media/hematologia-introducao-ao-estudo-das-anemias/paste-6a0d37951e2082d41d4f31094c8392a918599e87.jpg","question_bank/media/hematologia-introducao-ao-estudo-das-anemias/paste-d9aa1f13412bf8a114a79777750d874f10df60c9.jpg","question_bank/media/hematologia-introducao-ao-estudo-das-anemias/paste-698da850f99fd3fb74695cf7b5450d8f650ce013.jpg"],"comment":"Classificação da Questão\n\nNível: 🟡 Média (Morfologia eritrocitária e correlação com patologias hematológicas).\n\nResumo Essencial\n\nAlterações morfológicas específicas das hemácias são marcadores diagnósticos de diferentes patologias hematológicas e sistêmicas.\n\nCorreção Direta\n\n✅ Alternativa correta:\n\nCorrelações corretas:\n\nI. Hemácias em alvo → b. Hemoglobinopatia C (talassemia, anemia falciforme)\n\nII. Hemácias em rouleaux → d. Mieloma múltiplo (hipergamaglobulinemia)\n\nIII. Esquizócitos → a. Síndrome hemolítica urêmica (hemólise microangiopática)\n\nIV. Dacriócitos → c. Mielofibrose (fibrose medular)\n\nErros nas Outras Alternativas ❌\n\nHemácias em alvo não são características de mielofibrose:\n\nMielofibrose cursa com dacriócitos (lágrima), não células em alvo.\n\nRouleaux não é típico de mielofibrose:\n\nRouleaux indica aumento de proteínas plasmáticas (gamopatias).\n\nEsquizócitos não são específicos de hemoglobinopatias:\n\nEsquizócitos indicam hemólise microangiopática (SHU, PTT).\n\nElementos Clínicos Aplicáveis 🩺\n\nHemácias em alvo: Hemoglobina C, talassemia, hepatopatia\n\nRouleaux: Mieloma múltiplo, macroglobulinemia, inflamação crônica\n\nEsquizócitos: SHU, PTT, CIVD, válvulas cardíacas\n\nDacriócitos: Mielofibrose, metástases medulares, talassemia grave\n\nFisiopatologia 🔬\n\nCélulas em alvo: Excesso de membrana vs conteúdo celular\n\nRouleaux: Proteínas plasmáticas alteram cargas superficiais\n\nEsquizócitos: Fragmentação mecânica por microtrombos\n\nDacriócitos: Deformação ao passar por medula fibrótica\n\nMnemônico Útil ✨\n\n\"Alvo = Hemoglobinopatia\", \"Rouleaux = gaMatias\", \"Esquizócitos = hEmólise\", \"Dacriócitos = fiDrose\"\n\nTags Temáticas\n\nDica: Morfologia eritrocitária = diagnóstico! Cada alteração tem patologia específica - memorize as correlações clássicas! 🔬🩸","tags":["#Hematologia","#Hemoglobinopatias","#Mielofibrose","#MielomaMultiplo","#MorfologiaEritrocitária","#SHU","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885732","ankiGuid":"ssSg=K+uKP"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-c91a059ba79a6442","number":"1030a","sourceNumber":"1030a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Izabel, 50 anos, com histórico prévio de cirurgia bariátrica (restritiva-disabsortiva) há 10 anos, sem seguimento regular. Encaminhada ao Pronto Socorro do Hospital Cajuru por anemia, com Hb de 6,5 g por dL e volume corpuscular médio de 120fl. Além disso apresentava diminuição da série branca (2500 leucócitos por mm3) e das plaquetas (45.000 por mm3). Sorologias realizadas na admissão, incluindo pesquisa de HIV, negativas. Quadro recente relatado pelos familiares de piora cognitiva progressiva e desequilíbrio. Recebeu diagnóstico de Demência de Alzheimer há cerca de duas semanas, após avaliação em Unidade de Emergência, tendo iniciado Memantina, com pouca resposta.\n\nDe acordo com o caso clínico, a alteração observada no esfregaço do hemograma que poderia colaborar para o diagnóstico é a presença de:","options":{"A":"neutrófilos multisegmentados.","B":"bastonetes de Auer.","C":"corpúsculos de Howell-Jolly.","D":"corpúsculos de Dohle.","E":"granulações tóxicas."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":["question_bank/media/hematologia-introducao-ao-estudo-das-anemias/neutrofilos-segmentados_34873.jpg","question_bank/media/hematologia-introducao-ao-estudo-das-anemias/108-20180827104615-fagot-celljpg.jpg","question_bank/media/hematologia-introducao-ao-estudo-das-anemias/Corp%C3%BAsculos+de+Howell-Jolly.png"],"comment":"Classificação da Questão\n\nNível: 🟡 Média (Hematologia / Clínica Médica – anemia macrocítica e pancitopenia).\n\nResumo Essencial\n\nPaciente com anemia macrocítica (VCM 120), pancitopenia e alterações neurológicas após cirurgia bariátrica → quadro típico de deficiência grave de vitamina B12.\n\nCorreção Direta\n\n✅ Neutrófilos multisegmentados\n\nJustificativa:\n\nA deficiência de B12 causa megaloblastose, visível no esfregaço como neutrófilos hipersegmentados (≥ 5 lobos).\n\nAssocia-se a anemia macrocítica, leucopenia, plaquetopenia e sintomas neurológicos (ataxia, déficit cognitivo).\n\nErros nas Outras Alternativas ❌\n\nBastonetes de Auer: Inclusões citoplasmáticas em blastos, típicas de leucemia mieloide aguda.\n\nCorpúsculos de Döhle: Inclusões citoplasmáticas azuladas em neutrófilos, comuns em infecções.\n\nGranulações tóxicas: Achado em neutrófilos em resposta inflamatória grave.\n\nCorpúsculos de Howell-Jolly: Restos nucleares em hemácias, comuns pós-esplenectomia ou hipofunção esplênica.\n\nFisiopatologia Essencial\n\nCirurgia bariátrica (principalmente disabsortiva) → má absorção de B12 → falha na síntese de DNA → células com núcleo imaturo e citoplasma maduro → megaloblastos na medula e neutrófilos hipersegmentados no sangue periférico.\n\nMnemônico Útil ✨\n\n\"B12 = B’lobos a mais\" → neutrófilos com muitos lobos no núcleo.\n\nTags Temáticas\n\nDica: Anemia macrocítica + pancitopenia + sintomas neurológicos = pense primeiro em deficiência de B12, especialmente após cirurgia bariátrica.","tags":["#AnemiaMegaloblástica","#CirurgiaBariátrica","#DeficiênciaB12","#Hematologia","#NeutrófilosHipersegmentados","#Residência","#VitaminaB12","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885733","ankiGuid":"IP#,UHyJ)q"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-c34658119c6b845d","number":"1031a","sourceNumber":"1031a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Em relação às anemias microcíticas e hipocrômicas é correto afirmar que:","options":{"A":"a causa mais comum é deficiência de vitamina B12.","B":"devem ser tratadas com cianocobalamina.","C":"devem ser investigadas com mielograma.","D":"os principais diagnósticos diferenciais são anemia ferropriva, talassemia e anemia de doença crônica.","E":"os reticulócitos geralmente estão aumentados por ser tratar de anemia hiperproliferativa."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão\n\nNível: 🟢 Fácil (Conceitos básicos de anemias microcíticas - diagnósticos diferenciais clássicos).\n\nResumo Essencial\n\nAnemias microcíticas (VCM <80fL) têm 3 causas principais: anemia ferropriva, talassemia e anemia de doença crônica - diagnósticos diferenciais fundamentais.\n\nCorreção Direta\n\n✅ Alternativa correta:\n\n\"Os principais diagnósticos diferenciais são anemia ferropriva, talassemia e anemia de doença crônica\":\n\nJustificativa:\n\nTriad clássica das anemias microcíticas hipocrômicas\n\nAnemia ferropriva: Deficiência de ferro → ↓ síntese de hemoglobina\n\nTalassemia: Defeito genético na síntese de globinas\n\nAnemia de doença crônica: ↓ disponibilidade de ferro por inflamação\n\nErros nas Outras Alternativas ❌\n\nTratamento com cianocobalamina (B12):\n\nFalso: B12 trata anemia megaloblástica (macrocítica), não microcítica\n\nReticulócitos aumentados:\n\nFalso: Geralmente estão baixos - anemia hipoproliferativa\n\nCausa mais comum é deficiência de B12:\n\nFalso: B12 causa anemia macrocítica, não microcítica\n\nInvestigação com mielograma:\n\nDesnecessário: Diagnóstico feito com hemograma + ferro + ferritina\n\nDiferenciação Laboratorial 📊\n\nAnemia ferropriva: ↓ ferro sérico, ↓ ferritina, ↑ TIBC\n\nTalassemia: Ferro normal, ↑ HbA2 (eletroforese)\n\nDoença crônica: ↓ ferro sérico, ferritina normal/alta, ↓ TIBC\n\nDica: Microcítica = problema na síntese de Hb! Lembre da tríade clássica: ferropriva, talassemia e doença crônica. 🔴","tags":["#AnemiaFerropriva","#AnemiasMicrocíticas","#DoençaCrônica","#Hematologia","#Talassemia","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885734","ankiGuid":"ebs,6abdO["},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-139f5397b808909f","number":"1032a","sourceNumber":"1032a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Paciente de 42 anos, em investigação diagnóstica de anemia grave (hemoglobina = 7g/dL; hematócrito = 20%), recebe contagem de reticulócitos inicial compatível com 4,8% de reticulócitos. Diante desse padrão de comportamento da medula óssea, a condição que pode ser incluída entre as causas possíveis de anemia, nesse caso, é:","options":{"A":"Anemia ferropriva.","B":"Deficiência de G6PD.","C":"Anemia hemolítica autoimune.","D":"Púrpura trombótico-trombocitopênica."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":["question_bank/media/hematologia-introducao-ao-estudo-das-anemias/175090322155216133496488049536852667609563484978368.png"],"comment":"Resposta Estruturada\n\nClassificação da Questão\n\nNível: 🟡 Média (Hematologia - Classificação das anemias por índice de produção reticulocitário).\n\nResumo Essencial\n\nReticulócitos corrigidos = 1% (hipoproliferativa) indica comprometimento da eritropoiese medular, sendo compatível com anemia ferropriva.\n\nCorreção Direta\n\n✅ Alternativa correta:\n\n\"Anemia ferropriva\":\n\nJustificativa:\n\nCálculo essencial: Reticulócitos corrigidos = 4,8% × (20/45) = ≈1%\n\nAnemia hipoproliferativa: Reticulócitos corrigidos <2%\n\nFisiopatologia: Deficiência de ferro → comprometimento da síntese de hemoglobina → eritropoiese ineficaz\n\nMedula óssea: Hipoplasia eritroide por falta de substrato (ferro)\n\nErros nas Outras Alternativas ❌\n\nDeficiência de G6PD: Falso – Anemia hemolítica → reticulocitose aumentada (>5-10%).\n\nAnemia hemolítica autoimune: Falso – Destruição periférica → medula hiperativa → reticulocitose alta.\n\nPúrpura trombótico-trombocitopênica: Falso – Hemólise microangiopática → reticulocitose elevada.\n\nClassificação das Anemias por Reticulócitos\n\nHipoproliferativa (<2% corrigido):\n\nAnemia ferropriva\n\nMegaloblástica\n\nDoença crônica\n\nHiperproliferativa (>2% corrigido):\n\nHemólise\n\nSangramento agudo\n\nFórmula de Correção Reticulocitária\n\nReticulócitos corrigidos = % reticulócitos × (Hct paciente/45)\n\nNosso caso: 4,8% × (20/45) = 1,07%\n\nAnemia Ferropriva – Características\n\nMicrocítica hipocômica (VCM <80, HCM <27)\n\nFerritina baixa (<15 ng/mL)\n\nTransferrina elevada (>300 mg/dL)\n\nSaturação de transferrina baixa (<16%)\n\nMnemônico Útil ✨\n\n\"Reticulócitos <2% = Medula Preguiçosa!\" (hipoproliferativa)\n\nTags Temáticas\n\n#Hematologia #AnemiaFerropriva #ReticulócitosBaixos #AnemiaHipoproliferativa #ÍndiceReticulocitário\n\nDica: Sempre corrigir reticulócitos pelo hematócrito! <2% = hipoproliferativa (ferro, B12, doença crônica). >2% = hiperproliferativa (hemólise, sangramento). 🩸📊","tags":["#Anemia","#Hematologia","#HemóliseAutoimune","#LaboratórioClínico","#Reticulócitos","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885735","ankiGuid":"l0xL_]9sk_"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-cae843302e72c215","number":"1033a","sourceNumber":"1033a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"São causas de microcitose e hipocromia no exame de esfregaço sanguíneo:","options":{"A":"deficiência de ferro, mieloma múltiplo, uso de fenitoína","B":"hemólise intravascular, mielodisplasia, hipertireoidismo","C":"anemia da inflamação, talassemia, anemia sideroblástica","D":"insuficiência renal, leucemia mieloide crônica, hepatite crônica"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão\n\nNível: 🟡 Média (Diagnóstico diferencial de anemias microcíticas e hipocrômicas).\n\nResumo Essencial\n\nMicrocitose + hipocromia resulta de defeitos na síntese de hemoglobina por deficiência de ferro, distúrbios do ferro ou alterações na síntese de globina.\n\nCorreção Direta\n\n✅ Alternativa correta:\n\n\"Anemia da inflamação, talassemia, anemia sideroblástica\":\n\nJustificativa:\n\nAnemia da inflamação: Hepcidina ↑ → ↓ absorção/liberação de ferro → microcitose\n\nTalassemia: Defeito na síntese de globina → hemácias pequenas e hipocrômicas\n\nAnemia sideroblástica: Defeito na síntese do heme → ferro disponível mas não utilizado\n\nErros nas Outras Alternativas ❌\n\nInsuficiência renal, LMC, hepatite crônica:\n\nErro: Causam anemia normocítica, não microcítica\n\nHemólise intravascular, mielodisplasia, hipertireoidismo:\n\nErro: Hemólise causa macrocitose; mielodisplasia é variável; hipertireoidismo normocítica\n\nDeficiência de ferro, mieloma múltiplo, fenitoína:\n\nErro: Mieloma e fenitoína causam anemia normocítica/macrocítica\n\nFisiopatologia das Anemias Microcíticas\n\nMecanismo comum: ↓ síntese de hemoglobina → células pequenas\n\nPrincipais causas (mnemônico TAILS):\n\nTalassemia\n\nAnemia da inflamação\n\nIron deficiency (deficiência de ferro)\n\nLead poisoning (intoxicação por chumbo)\n\nSideroblastic anemia\n\nDiferenciação Laboratorial\n\nDeficiência de ferro: Ferritina ↓, TIBC ↑, saturação ↓\n\nAnemia da inflamação: Ferritina ↑, TIBC ↓, saturação ↓\n\nTalassemia: Eletroforese de Hb alterada, HbA2 ↑\n\nSideroblástica: Sideroblastos em anel na medula óssea\n\nMnemônico Útil ✨\n\n\"TAILS = Microcitose!\" (principais causas de anemia microcítica)\n\nDica: Microcitose = problema na síntese de Hb! Lembre-se do TAILS para as principais causas. 🔬🩸","tags":["#AnemiaInflamação","#AnemiaMicrocítica","#Hematologia","#Sideroblástica","#Talassemia","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885736","ankiGuid":"xT|ivT:iWs"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-76c91de51e75f77f","number":"1034a","sourceNumber":"1034a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Mulher de 28 anos de idade, previamente hígida, está em investigação de fadiga progressiva há 7 meses. O resultado do seu hemograma foi: hemoglobina 8 g/dL; VCM 106 fL; leucócitos 4.200 cels/mm³; plaquetas 240.000 cels/mm³. O esfregaço sanguíneo revelou macrocitose, anisocitose, poiquilocitose e hipersegmentação de neutrófilos. O melhor exame a ser solicitado para elucidar a causa da anemia é o de:","options":{"A":"ferritina","B":"vitamina B12","C":"teste de Coombs","D":"aspirado de medula"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão\n\nNível: 🟡 Média (Diagnóstico de anemia megaloblástica).\n\nResumo Essencial\n\nAnemia macrocítica (VCM 106 fL) com hipersegmentação de neutrófilos em mulher jovem = anemia megaloblástica por deficiência de vitamina B12 ou folato.\n\nCorreção Direta\n\n✅ Alternativa correta:\n\n\"Vitamina B12\":\n\nJustificativa:\n\nAchados clássicos: Macrocitose (VCM >100 fL) + hipersegmentação neutrofílica (>5 lóbulos)\n\nAnemia megaloblástica: Defeito na síntese de DNA → células grandes e imaturas\n\nEpidemiologia: Deficiência B12 mais comum que folato em adultos jovens\n\nErros nas Outras Alternativas ❌\n\nFerritina:\n\nErro: Investiga deficiência de ferro → anemia microcítica, não macrocítica\n\nAspirado de medula:\n\nErro: Exame de segunda linha; dosagem B12/folato é mais específica e menos invasiva\n\nTeste de Coombs:\n\nErro: Investiga anemia hemolítica autoimune → não explica macrocitose + hipersegmentação\n\nFisiopatologia da Anemia Megaloblástica\n\nMecanismo:\n\nB12/Folato → cofatores para síntese de DNA\n\nDeficiência → ↓ síntese DNA vs síntese RNA normal → megaloblastos\n\nAchados morfológicos:\n\nMacrocitose (VCM >100 fL)\n\nHipersegmentação neutrofílica (>5 lóbulos = patognomônico)\n\nPancitopenia (casos avançados)\n\nInvestigação Complementar\n\nPrimeira linha: Vitamina B12 + ácido fólico séricos\n\nSegunda linha: Ácido metilmalônico + homocisteína (se B12 borderline)\n\nTerceira linha: Anticorpos anti-fator intrínseco (anemia perniciosa)\n\nDiferencial por Idade\n\nJovens: Deficiência nutricional (vegetarianismo, má absorção)\n\nIdosos: Anemia perniciosa (gastrite atrófica + anticorpos)\n\nMnemônico Útil ✨\n\n\"Macro + Hipersegmentação = B12 na Investigação!\"\n\nDica: Macrocitose + hipersegmentação neutrofílica = anemia megaloblástica! B12 é o primeiro exame a solicitar. 🔬📊","tags":["#AnemiaMegaloblástica","#Hematologia","#Hipersegmentação","#Macrocitose","#VitaminaB12","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885737","ankiGuid":"r3duG$C=Fs"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-46e76ec6f24c4b93","number":"1035a","sourceNumber":"1035a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"São causas de anemia normocrômica normocítica, hipocrômica microcítica e normocrômica macrocítica, respectivamente:","options":{"A":"Anemia aplástica, anemia sideroblástica, anemia megaloblástica.","B":"Anemia da insuficiência renal crônica, anemia hemolítica, anemia do hipotiroidismo.","C":"Anemia induzida por fármacos, anemia sideroblástica, anemia ferropriva.","D":"Talassemia, anemia de doença crônica, anemia megaloblástica.","E":"Anemia ferropriva, anemia hemolítica, talassemia."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão\n\nNível: 🟡 Média (Classificação morfológica das anemias e suas principais etiologias).\n\nResumo Essencial\n\nAnemia aplástica (normocrômica normocítica), anemia sideroblástica (hipocrômica microcítica) e anemia megaloblástica (normocrômica macrocítica) representam os protótipos de cada categoria morfológica.\n\nCorreção Direta\n\n✅ Alternativa correta:\n\n\"Anemia aplástica, anemia sideroblástica, anemia megaloblástica\":\n\nJustificativa:\n\nAnemia aplástica: Normocrômica normocítica - falha na produção de todas as linhagens celulares.\n\nAnemia sideroblástica: Hipocrômica microcítica - defeito na síntese do heme com acúmulo de ferro.\n\nAnemia megaloblástica: Normocrômica macrocítica - deficiência B12/folato com síntese deficiente de DNA.\n\nErros nas Outras Alternativas ❌\n\nTalassemia: Hipocrômica microcítica (não normocrômica normocítica).\n\nAnemia ferropriva: Hipocrômica microcítica (não normocrômica macrocítica).\n\nAnemia hemolítica: Geralmente normocrômica normocítica (não hipocrômica microcítica).\n\nAnemia de doença crônica: Pode ser normocítica ou microcítica.\n\nClassificação Morfológica Sistemática\n\nNormocrômica Normocítica (VCM 80-100, CHCM normal):\n\nAplástica, IRC, doença crônica, hemólise aguda\n\nHipocrômica Microcítica (VCM <80, CHCM baixo):\n\nFerropriva, sideroblástica, talassemia, doença crônica\n\nNormocrômica Macrocítica (VCM >100, CHCM normal):\n\nMegaloblástica (B12/folato), álcool, hipotireoidismo\n\nFisiopatologia Específica\n\nAplástica: ↓ Produção medular → hemácias normais em pequena quantidade\n\nSideroblástica: ↓ Síntese heme → ferro acumula → hemácias pequenas e pálidas\n\nMegaloblástica: ↓ Síntese DNA → divisão lenta → hemácias grandes\n\nAchados Laboratoriais Distintivos\n\nAplástica: Pancitopenia + reticulócitos baixos\n\nSideroblástica: Ferro alto + sideroblastos em anel\n\nMegaloblástica: VCM >100 + neutrófilos hipersegmentados\n\nMnemônico Útil ✨\n\n\"ASM = Aplástica Sideroblástica Megaloblástica\" - protótipos de cada categoria.\n\nTags Temáticas\n\nDica: ASM = Protótipos morfológicos! Cada anemia representa o padrão clássico de sua categoria. 🎯📊","tags":["#AnemiaAplástica","#AnemiaMegaloblástica","#AnemiaSideroblástica","#ClassificaçãoMorfológica","#Hematologia","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885738","ankiGuid":"sQXml9#cp5"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-38067176e4328fb7","number":"1036a","sourceNumber":"1036a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Das anemias abaixo, aquela que tipicamente apresenta-se com normocitose e elevada contagem de reticulócitos é a","options":{"A":"anemia ferropriva.","B":"anemia de doença crônica.","C":"síndrome hemofagocítica.","D":"anemia por deficiência de folato.","E":"deficiência de G6PD."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão\n\nNível: 🟡 Média (Fisiopatologia das anemias hemolíticas e resposta medular compensatória).\n\nResumo Essencial\n\nDeficiência de G6PD causa hemólise com reticulocitose compensatória e normocitose (hemácias jovens têm tamanho normal).\n\nCorreção Direta\n\n✅ Alternativa correta:\n\n\"deficiência de G6PD\":\n\nJustificativa:\n\nG6PD protege hemácias do estresse oxidativo.\n\nHemólise → destruição rápida de hemácias → ↑ reticulócitos (5-20%).\n\nNormocitose: Reticulócitos são normocíticos → VCM normal/levemente elevado.\n\nCompensação medular: Produção aumentada para repor perdas hemolíticas.\n\nErros nas Outras Alternativas ❌\n\nDeficiência de folato: Macrocítica + reticulócitos baixos (eritropoese inefetiva).\n\nAnemia ferropriva: Microcítica + reticulócitos baixos/normais.\n\nSíndrome hemofagocítica: Normocítica + reticulócitos baixos (destruição + ↓ produção).\n\nAnemia de doença crônica: Normocítica/microcítica + reticulócitos baixos.\n\nFisiopatologia G6PD\n\nVia das pentoses: G6PD → NADPH → glutationa reduzida\n\nProteção antioxidante: Glutationa protege contra radicais livres\n\nDeficiência → hemólise oxidativa → anemia hemolítica\n\nPadrão Hemolítico Clássico\n\nLaboratório: ↑ LDH, ↑ bilirrubina indireta, ↓ haptoglobina\n\nReticulócitos: 5-20% (compensação medular)\n\nVCM: Normal ou levemente elevado (reticulócitos jovens)\n\nDesencadeantes da Hemólise G6PD\n\nFármacos: Primaquina, sulfas, dapsona\n\nAlimentos: Fava (favismo)\n\nInfecções: Estresse oxidativo\n\nDiagnóstico Diferencial Reticulocitose\n\n↑ Reticulócitos: Hemólise, hemorragia aguda, tratamento de deficiências\n\n↓ Reticulócitos: Aplasia, megaloblastose, infiltração medular\n\nMnemônico Útil ✨\n\n\"G6PD = Glóbulos 6 Põem Demais\" - hemólise → reticulocitose compensatória.\n\nTags Temâticas\n\nDica: Hemólise = Reticulocitose! G6PD é anemia hemolítica clássica com resposta medular preservada. 🔴⚡","tags":["#AnemiaHemolítica","#G6PD","#Hematologia","#Hemólise","#Reticulocitose","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885739","ankiGuid":"nMa)(heo:n"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-4ad0a4722faa0d83","number":"1037a","sourceNumber":"1037a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Assinale a alternativa CORRETA.\n\nSegundo a Organização Mundial da Saúde, para as crianças de 5 a 11 anos de idade, define-se anemia valores de hemoglobina menor que:","options":{"A":"11,5 g/dl (gramas por decilitro)","B":"12 g/dl (gramas por decilitro)","C":"12,5 g/dl (gramas por decilitro)","D":"13 g/dl (gramas por decilitro)"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão\n\nNível: 🟢 Fácil (Valores de referência da OMS para diagnóstico de anemia em crianças).\n\nResumo Essencial\n\nOMS define anemia em crianças de 5 a 11 anos como hemoglobina <11,5 g/dL, valor específico para essa faixa etária pediátrica.\n\nCorreção Direta\n\n✅ Alternativa correta:\n\n\"11,5 g/dL\":\n\nJustificativa:\n\nOMS (2011): Hemoglobina <11,5 g/dL define anemia em crianças de 5 a 11 anos.\n\nFaixa etária específica: Cada grupo tem valores diferentes devido às variações fisiológicas.\n\nPadrão internacional: Usado globalmente para diagnóstico e programas de saúde pública.\n\nErros nas Outras Alternativas ❌\n\n12 g/dL:\n\nFalso: Valor usado para mulheres não-gestantes (≥15 anos).\n\n12,5 g/dL:\n\nFalso: Não corresponde a nenhuma faixa etária específica da OMS.\n\n13 g/dL:\n\nFalso: Valor usado para homens ≥15 anos.\n\nValores de Referência OMS para Anemia\n\n0-5 anos: <11,0 g/dL\n\n5-11 anos: <11,5 g/dL\n\n12-14 anos: <12,0 g/dL\n\nMulheres ≥15 anos: <12,0 g/dL\n\nHomens ≥15 anos: <13,0 g/dL\n\nGestantes: <11,0 g/dL\n\nAplicação Clínica 🩺\n\nTriagem populacional: Valores usados em programas de saúde pública.\n\nDiagnóstico individual: Sempre considerar contexto clínico e outros parâmetros.\n\nSeguimento: Monitorar resposta ao tratamento com ferro.\n\nMnemônico Útil ✨\n\n\"Cresce a Idade, Cresce a Hb\": 0-5 anos (11,0) → 5-11 anos (11,5) → 12-14 anos (12,0).\n\nTags Temáticas\n\nDica: 5-11 anos = 11,5 g/dL! Cada faixa etária tem seu valor específico - memorize a progressão crescente com a idade. 📊👶","tags":["#Anemia","#Hemoglobina","#OMS","#Pediatria","#SaúdePública","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885740","ankiGuid":"v(}_g>aAla"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-9af7248d6663bfa1","number":"1038a","sourceNumber":"1038a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Paciente feminina, de 19 anos, apresenta-se com sintomas de cansaço há 01 mês. Ao exame físico, encontra-se pálida. Nos exames solicitados, apresentava: Hb = 7,2 g/dl (valores normais [VN]: 12 - 16g/dl); VCM = 110 (VN: 80 - 100); HCM = 33 (VN: 30 - 34); leucócitos = 6.200 com diferencial normal (VN: 5.000 - 10.000); plaquetas= 165.000 (VN:150.000 - 400.000); DHL elevado com Coombs direto positivo; saturação de transferrina, dosagens de B12 e folato normais.\nCom base na história anterior, responda à questão: Qual o diagnóstico da paciente?","options":{"A":"Anemia microcítica hipocrômica.","B":"Anemia normocítica e normocrômica.","C":"Anemia macrocítica.","D":"Existem duas afirmativas corretas.","E":"Nenhuma das anteriores."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão\n\nNível: 🟢 Fácil (Classificação morfológica de anemia baseada no VCM).\n\nResumo Essencial\n\nVCM = 110 (normal: 80-100) caracteriza anemia macrocítica, independentemente da causa subjacente (neste caso, hemólise autoimune por Coombs direto positivo).\n\nCorreção Direta\n\n✅ Alternativa correta:\n\n\"Anemia macrocítica\":\n\nJustificativa:\n\nVCM = 110 (>100) = macrocitose por definição.\n\nClassificação morfológica: Baseada exclusivamente no tamanho das hemácias (VCM).\n\nMacrocítica: VCM >100 fL.\n\nContexto clínico: Anemia hemolítica autoimune (Coombs+, DHL↑) com reticulocitose causando macrocitose.\n\nErros nas Outras Alternativas ❌\n\nAnemia microcítica hipocrômica:\n\nFalso: VCM = 110 é macrocítico (>100), não microcítico (<80).\n\nAnemia normocítica e normocrômica:\n\nFalso: VCM = 110 está acima do normal (80-100).\n\nExistem duas afirmativas corretas:\n\nFalso: Apenas a macrocítica está correta.\n\nNenhuma das anteriores:\n\nFalso: A alternativa \"anemia macrocítica\" está correta.\n\nClassificação Morfológica das Anemias\n\nMicrocítica: VCM <80 fL (ferropriva, talassemia, anemia de doença crônica).\n\nNormocítica: VCM 80-100 fL (hemólise aguda, hemorragia, doença crônica).\n\nMacrocítica: VCM >100 fL (B12/folato, álcool, hipotireoidismo, reticulocitose).\n\nContexto Clínico da Paciente 🩺\n\nAnemia hemolítica autoimune:\n\nCoombs direto positivo + DHL elevado.\n\nReticulocitose → hemácias jovens maiores → macrocitose.\n\nB12 e folato normais → descarta deficiência nutricional.\n\nMnemônico Útil ✨\n\n\"VCM = Vida, Classifique Morfologicamente\": <80 = micro, 80-100 = normo, >100 = macro.\n\nTags Temáticas\n\nDica: VCM >100 = Macrocítica sempre! Não importa a causa - a classificação morfológica é baseada apenas no tamanho das hemácias. 🔬📏","tags":["#Anemia","#Hematologia","#Hemólise","#Macrocítica","#VCM","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885741","ankiGuid":"AjIYl@?dc*"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-d6e4bdf8a2d2221c","number":"1039a","sourceNumber":"1039a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Lactente, seis meses, masculino, é medicado com sulfametoxazol + trimetoprima por apresentar doença febril. Após 36 horas, apresenta icterícia, queda da hemoglobina e presença de corpúsculos de Heinz no esfregaço periférico. Sua mãe refere que, no teste do pezinho, havia uma alteração, mas não sabe ao certo qual era. Pode-se afirmar que a causa da lesão da membrana celular nesta doença é a:","options":{"A":"Ruptura da molécula da hemoglobina devido à ausência de substâncias reduzidas.","B":"Alteração na síntese da hemoglobina pela presença de compostos oxidantes.","C":"Precipitação da hemoglobina pela perda da proteção contra agentes oxidantes.","D":"Perda de um grupo heme da hemoglobina pela presença de agentes reduzidos."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão\n\nNível: 🟡 Média (Fisiopatologia da deficiência de G6PD e hemólise oxidativa).\n\nResumo Essencial\n\nDeficiência de G6PD causa hemólise por precipitação da hemoglobina devido à perda da proteção antioxidante (redução de glutationa), formando corpúsculos de Heinz.\n\nCorreção Direta\n\n✅ Alternativa correta:\n\n\"Precipitação da hemoglobina pela perda da proteção contra agentes oxidantes\":\n\nJustificativa:\n\nG6PD deficiente → ↓ NADPH → ↓ glutationa reduzida.\n\nPerda da proteção antioxidante → estresse oxidativo.\n\nHemoglobina precipita → corpúsculos de Heinz (hemoglobina desnaturada).\n\nSulfametoxazol = droga oxidante → desencadeia hemólise.\n\nErros nas Outras Alternativas ❌\n\nPerda de um grupo heme da hemoglobina:\n\nFalso: O problema não é perda do heme, mas desnaturação da globina.\n\nRuptura da molécula da hemoglobina por ausência de substâncias reduzidas:\n\nImpreciso: Não é ruptura, mas precipitação por oxidação.\n\nAlteração na síntese da hemoglobina:\n\nFalso: A síntese é normal - problema é na proteção antioxidante.\n\nFisiopatologia da Deficiência de G6PD\n\nVia das pentoses:\n\nG6PD → glucose-6-fosfato → NADPH.\n\nNADPH → glutationa reduzida (GSH).\n\nGSH → proteção contra radicais livres.\n\nEstresse oxidativo:\n\nDrogas oxidantes → ↑ radicais livres.\n\nGSH insuficiente → hemoglobina oxida → corpúsculos de Heinz.\n\nDesencadeantes da Hemólise 🩺\n\nMedicamentos:\n\nSulfas (sulfametoxazol), quinolonas, dapsona.\n\nInfecções: Febris agudas.\n\nAlimentos: Fava (favismo).\n\nQuadro Clínico\n\nHemólise aguda: Icterícia, anemia, hemoglobinúria.\n\nLaboratório: ↓ Hb, ↑ bilirrubina, corpúsculos de Heinz.\n\nTeste do pezinho: Triagem para G6PD.\n\nMnemônico Útil ✨\n\n\"G6PD = Glutationa Perdida, Desnaturação\": Perda da proteção antioxidante → precipitação da Hb.\n\nTags Temáticas\n\nDica: G6PD deficiente = Glutationa baixa = Hemoglobina precipita! Corpúsculos de Heinz são hemoglobina desnaturada por oxidação. 🔴⚡","tags":["#CorpúsculosHeinz","#EstresseOxidativo","#G6PD","#Hemólise","#Pediatria","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885742","ankiGuid":"degv-Ski,["},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-b571c5aa58af882b","number":"1040a","sourceNumber":"1040a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"A morfologia dos eritrócitos é de grande valor no diagnóstico das anemias. A presença de corpúsculos de Heinz nos eritrócitos indica:","options":{"A":"Agente citotóxico.","B":"Acúmulo de glicogênio.","C":"Precipitação de hemoglobina anormal.","D":"Defeito no citoesqueleto celular.","E":"Defeito mitocondrial."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão\n\nNível: 🟢 Fácil (Morfologia eritrocitária - significado dos corpúsculos de Heinz).\n\nResumo Essencial\n\nCorpúsculos de Heinz são hemoglobina precipitada (desnaturada) visível como inclusões nos eritrócitos, indicando hemoglobina anormal ou estresse oxidativo.\n\nCorreção Direta\n\n✅ Alternativa correta:\n\n\"Precipitação de hemoglobina anormal\":\n\nJustificativa:\n\nCorpúsculos de Heinz = hemoglobina desnaturada e precipitada.\n\nFormação: Hemoglobina instável → agregação → inclusões citoplasmáticas.\n\nColoração: Visível com azul de metileno ou cristal violeta.\n\nCausas: Deficiência G6PD, hemoglobinopatias instáveis, drogas oxidantes.\n\nErros nas Outras Alternativas ❌\n\nDefeito no citoesqueleto celular:\n\nFalso: Defeitos do citoesqueleto causam esferócitos e eliptócitos.\n\nAcúmulo de glicogênio:\n\nFalso: Glicogênio não forma corpúsculos de Heinz.\n\nAgente citotóxico:\n\nImpreciso: Embora agentes oxidantes causem, o corpúsculo é hemoglobina precipitada.\n\nDefeito mitocondrial:\n\nFalso: Eritrócitos maduros não têm mitocôndrias.\n\nCausas dos Corpúsculos de Heinz\n\nDeficiência de G6PD:\n\nEstresse oxidativo → hemoglobina instável.\n\nHemoglobinopatias:\n\nHb instáveis (Hb Köln, Hb Zurich).\n\nDrogas oxidantes:\n\nSulfas, quinolonas, dapsona.\n\nDetecção Laboratorial 🩺\n\nColoração supravital:\n\nAzul de metileno ou cristal violeta.\n\nEsfregaço comum: Geralmente não visível.\n\nLocalização: Próximo à membrana celular.\n\nDiferencial Morfológico\n\nCorpúsculos de Heinz: Hemoglobina precipitada.\n\nCorpúsculos de Howell-Jolly: Restos nucleares (DNA).\n\nCorpúsculos de Pappenheimer: Grânulos de ferro.\n\nMnemônico Útil ✨\n\n\"Heinz = Hemoglobina\": Corpúsculos de Heinz = Hemoglobina precipitada.\n\nTags Temáticas\n\nDica: Corpúsculos de Heinz = Hemoglobina precipitada! Sempre lembrar: Heinz = Hemoglobina desnaturada por oxidação. 🔴⚡","tags":["#CorpúsculosHeinz","#G6PD","#Hematologia","#Hemoglobina","#MorfologiaEritrocitária","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885743","ankiGuid":"qP=a,&<Ht;"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-aa6a9aa70dbd83a4","number":"1041a","sourceNumber":"1041a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Paciente F.R.L., feminina, 75 anos de idade, realizou alguns exames que revelaram hematócrito de 21%, VCM de 115 fl, macrovalócitos e plurissegmentação de neutrófilos à hematoscopia. A EDA mostrou acentuada atrofia de mucosa em corpo e fundo gástricos. Outras anormalidades podem ser esperadas nesta paciente, com a EXCEÇÃO de:","options":{"A":"LDH alta.","B":"Leucopenia.","C":"Gastrina baixa.","D":"Plaquetopenia.","E":"Homocisteína elevada."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão\n\nNível: 🟡 Média (Hematologia - anemia megaloblástica por deficiência de B12/folato).\n\nResumo Essencial\n\nAnemia megaloblástica (Ht 21%, VCM 115 fl) + atrofia gástrica + plurissegmentação neutrofílica indica deficiência de B12 por gastrite atrófica/anemia perniciosa.\n\nCorreção Direta\n\n✅ Alternativa correta:\n\n\"Gastrina baixa\":\n\nJustificativa:\n\nGastrite atrófica → destruição das células parietais → ↓ ácido gástrico\n\nHipocloridria/acloridria → feedback negativo perdido → ↑ gastrina\n\nGastrina elevada é esperada na anemia perniciosa (não baixa)\n\nMecanismo: Células G antrais secretam gastrina para estimular ácido inexistente\n\nErros nas Outras Alternativas ❌\n\nPlaquetopenia: Esperada - hematopoese ineficaz por deficiência de B12\n\nLeucopenia: Esperada - pancitopenia por megaloblastose medular\n\nLDH alta: Esperada - hemólise intramedular por eritropoese ineficaz\n\nHomocisteína elevada: Esperada - B12 é cofator da metionina sintase\n\nFisiopatologia da Anemia Perniciosa 🩺\n\nGastrite atrófica → ↓ fator intrínseco → ↓ absorção de B12\n\nHipergastrinemia → risco de tumores carcinoides gástricos\n\nAnticorpos: Anti-fator intrínseco (específico) + anti-células parietais\n\nMnemônico Útil ✨\n\n\"Gastrite Atrófica = Gastrina Alta!\" (sem ácido, gastrina sobe)\n\nAchados Laboratoriais Típicos\n\nHemograma: Pancitopenia + macrovalócitos + plurissegmentação\n\nBioquímica: ↑ LDH, ↑ bilirrubina indireta, ↑ homocisteína\n\nEspecíficos: ↓ B12, ↑ gastrina, ↑ ácido metilmalônico\n\nTags Temáticas\n\nDica: Gastrite atrófica = Gastrina ALTA! Sem ácido gástrico, a gastrina dispara para tentar estimular. 🚨🔬","tags":["#AnemiaMegaloblástica","#AnemiaPerniciosa","#DeficiênciaB12","#GastriteAtrófica","#Hematologia","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885744","ankiGuid":"heDE3)|!V&"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-e1eebdc10968b180","number":"1042a","sourceNumber":"1042a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Sobre as alterações descritas em um hemograma, assinale a alternativa INCORRETA:","options":{"A":"Na presença de blastos, deve-se suspeitar de leucemia aguda.","B":"Na presença de linfócitos atípicos, deve-se suspeitar de leucemia aguda.","C":"Neutrófilos hipersegmentados estão presentes nas anemias megaloblásticas","D":"Hemácias em rouleaux podem ser encontradas em pacientes com mieloma múltiplo","E":"O corpúsculo de Howell- Jolly está presente nas hemácias de pacientes pós esplenectomia"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão\n\nNível: 🟡 Média (Hematologia - interpretação morfológica do hemograma).\n\nResumo Essencial\n\nLinfócitos atípicos são células reativas (não neoplásicas) encontradas em infecções virais como mononucleose, não em leucemias agudas.\n\nCorreção Direta\n\n✅ Alternativa incorreta:\n\n\"Na presença de linfócitos atípicos, deve-se suspeitar de leucemia aguda\":\n\nJustificativa:\n\nLinfócitos atípicos = linfócitos reativos (células de Downey)\n\nCausas: EBV, CMV, hepatites virais, toxoplasmose\n\nLeucemia aguda: apresenta blastos (não linfócitos atípicos)\n\nDiferenciação: atípicos são maduros reativos, blastos são imaturos neoplásicos\n\nErros nas Outras Alternativas ❌\n\nBlastos sugerem leucemia aguda: Correto - >20% blastos = critério diagnóstico\n\nCorpúsculo de Howell-Jolly pós-esplenectomia: Correto - baço remove inclusões nucleares\n\nNeutrófilos hipersegmentados na megaloblástica: Correto - >5 lóbulos por deficiência B12/folato\n\nHemácias em rouleaux no mieloma: Correto - paraproteínas alteram viscosidade\n\nDiferenciação Morfológica 🩺\n\nLinfócitos atípicos: Citoplasma abundante, basófilo, núcleo excêntrico\n\nBlastos: Núcleo grande, cromatina frouxa, citoplasma escasso\n\nDiagnóstico diferencial: Imunofenotipagem resolve dúvidas\n\nMnemônico Útil ✨\n\n\"Atípicos = Ataque viral!\" (reação, não neoplasia)\n\nPrincipais Associações\n\nEBV: 10-20% linfócitos atípicos\n\nLeucemia aguda: >20% blastos na medula\n\nTags Temáticas\n\nDica: Linfócitos atípicos = vírus! Blastos = leucemia. Não confundir reação com neoplasia. 🚨🔬","tags":["#Hematologia","#Hemograma","#LeucemiaAguda","#LinfócitosAtípicos","#MorfologiaCelular","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885745","ankiGuid":"BE[qmel7_p"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-da1d4d34b1761c99","number":"1043a","sourceNumber":"1043a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Paciente apresenta ao exame do esfregaço periférico do sangue presença de hemácias em forma de foice. Qual é a hipótese diagnóstica nesse caso?","options":{"A":"Talassemia.","B":"Eliptocitose.","C":"Deficiência de G6PD.","D":"Esferocitose.","E":"Drepanocitose."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão\n\nNível: 🟢 Fácil (Correlação direta entre morfologia eritrocitária e diagnóstico hematológico).\n\nResumo Essential\n\nHemácias em forma de foice no esfregaço sanguíneo são patognomônicas da drepanocitose (anemia falciforme), causada por hemoglobina S.\n\nCorreção Direta\n\n✅ Alternativa correta:\n\n\"Drepanocitose\":\n\nJustificativa:\n\nMorfologia característica: Drepanócitos (hemácias em foice) são patognomônicos.\n\nFisiopatologia: Hemoglobina S → polimerização em baixa tensão de O₂ → deformação celular.\n\nMutação genética: Substituição ácido glutâmico → valina na posição 6 da cadeia β-globina.\n\nConfirmação diagnóstica: Eletroforese de hemoglobina mostra HbS.\n\nErros nas Outras Alternativas ❌\n\nTalassemia:\n\nMorfologia: Microcitose, hipocromia, células em alvo - não foice.\n\nEliptocitose:\n\nMorfologia: Hemácias elípticas/ovais - não foice.\n\nDeficiência de G6PD:\n\nMorfologia: Hemácias mordidas, corpos de Heinz - não foice.\n\nEsferocitose:\n\nMorfologia: Esferócitos (hemácias esféricas) - não foice.\n\nFisiopatologia 🔬\n\nProcesso de falcização:\n\nHipóxia/acidose → HbS polimeriza → rigidez celular.\n\nVaso-oclusão → crises álgicas → infartos tissulares.\n\nConsequências clínicas:\n\nAnemia hemolítica crônica.\n\nCrises vaso-oclusivas.\n\nDactilite, síndrome torácica aguda.\n\nDiagnóstico Complementar 🩺\n\nEletroforese de Hb:\n\nHbSS (homozigoto): HbS >90%.\n\nHbSC (heterozigoto composto): HbS + HbC.\n\nTeste de falcização: Metabissulfito de sódio induz falcização in vitro.\n\nVariantes Genéticas\n\nSS: Forma mais grave (anemia falciforme).\n\nSC: Forma moderada.\n\nS-β talassemia: Gravidade variável.\n\nMnemônico Útil ✨\n\n\"Foice = Drepanocitose!\" (correlação morfológica direta).\n\nTags Temáticas\n\nDica: Hemácias em foice = drepanocitose! É uma correlação direta e patognomônica. Sempre confirme com eletroforese de hemoglobina. 🩸⚡","tags":["#AnemiaFalciforme","#Drepanocitose","#Hematologia","#Hemoglobinopatias","#MorfologiaEritrocitária","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885746","ankiGuid":"t,2iks|8KG"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-1ca0a6f5b160992b","number":"1044a","sourceNumber":"1044a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Considere as seguintes alterações eritrocitárias:\n\nI. Hemácias em gota ou dacriócitos;\n\nII. Hemácias em alvo ou leptócitos;\n\nIII. Acantócitos;\n\nIV. Corpúsculos de Howell-Jolly.\n\nAsplenia\n\nFibrose Medular\n\nHepatopatia\n\nHemoglobinopatia C\n\nA CORRETA relação entre as alterações eritrocitárias e distúrbios clínicos é:","options":{"A":"II, III, I, IV","B":"I, II, III, IV","C":"IV, III, II, I","D":"II, I, IV, III","E":"IV, I, III, II"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":["question_bank/media/hematologia-introducao-ao-estudo-das-anemias/paste-529a42189c7b1d6ffc95cce615068511e0462344.png","question_bank/media/hematologia-introducao-ao-estudo-das-anemias/paste-57f73c03231e899881c78ed647e13ed1e889ccd6.png","question_bank/media/hematologia-introducao-ao-estudo-das-anemias/paste-9d4202479a438c79a59320e768dd72a94d2df8ce.png","question_bank/media/hematologia-introducao-ao-estudo-das-anemias/paste-3309ad7f99f7c8d4c0a804b3526839e125117a2d.png","question_bank/media/hematologia-introducao-ao-estudo-das-anemias/paste-a70b4c4cefbf64aef56dc15856d82bf27813dfdc.png","question_bank/media/hematologia-introducao-ao-estudo-das-anemias/paste-a70b4c4cefbf64aef56dc15856d82bf27813dfdc.png"],"comment":"Classificação da Questão\n\nNível: 🟡 Média (Hematoscopia e correlação clínica de alterações eritrocitárias).\n\nResumo Essencial\n\nAvaliação do esfregaço de sangue periférico é ferramenta diagnóstica fundamental para correlacionar alterações morfológicas eritrocitárias com distúrbios clínicos específicos.\n\nCorreção Direta\n\n✅ Alternativa correta:\n\nCorrelação adequada entre alterações eritrocitárias e distúrbios clínicos:\n\nJustificativa técnica:\n\nI. Dacriócitos (hemácias em gota):\n\nMielofibrose e talassemias → hematopoiese extramedular aumentada\n\nFormato de lágrima/pera por distorção da membrana\n\nII. Leptócitos (hemácias em alvo):\n\nHemoglobinopatia SC (mais característico) e talassemias\n\nFaixa de hemoglobina periférica = aspecto de \"alvo\"\n\nIII. Acantócitos:\n\nHepatopatias (cirrose) → membrana irregular com espículas\n\nAlteração lipídica da membrana eritrocitária\n\nIV. Corpúsculos de Howell-Jolly:\n\nAsplenismo (pós-esplenectomia ou funcional) → restos de DNA nuclear\n\nBaço remove esses corpúsculos em condições normais\n\nErros nas Outras Alternativas ❌\n\nCorrelações incorretas entre morfologia e patologia:\n\nFalso: Cada alteração tem correlação clínica específica bem estabelecida\n\nAtribuições inadequadas de causas:\n\nFalso: Mecanismos fisiopatológicos são distintos para cada poiquilócito\n\nGeneralizações imprecisas:\n\nFalso: Especificidade diagnóstica varia entre as alterações\n\nFisiopatologia das Alterações 🔬\n\nDacriócitos:\n\nFibrose medular → distorção física durante passagem esplênica\n\nLeptócitos:\n\nAlteração da hemoglobina → redistribuição intracitoplásmica\n\nAcantócitos:\n\nDisfunção hepática → alteração do colesterol/fosfolípidos de membrana\n\nHowell-Jolly:\n\nAusência de função esplênica → falha na remoção de restos nucleares\n\nCorrelações Clínicas Importantes 🩺\n\nDacriócitos: Suspeitar de mielofibrose primária ou talassemia major\n\nLeptócitos: Investigar hemoglobinopatias (eletroforese de Hb)\n\nAcantócitos: Avaliar função hepática (bilirrubinas, enzimas)\n\nHowell-Jolly: Confirmar asplenismo (cintilografia esplênica se necessário)\n\nOutras Alterações Relevantes 📊\n\nEsferócitos: Esferocitose hereditária, AHAI\n\nEliptócitos: Eliptocitose hereditária\n\nEsquizócitos: Microangiopatias (PTT, SHU)\n\nRouleaux: Mieloma múltiplo, inflamação\n\nMnemônico Útil ✨\n\n\"DLAH\": Dacriócitos (mielofibrose), Leptócitos (hemoglobinopatias), Acantócitos (hepatopatias), Howell-Jolly (asplenismo)\n\nTags Temáticas\n\nDica: Hematoscopia = mapa diagnóstico! Cada alteração morfológica tem correlação clínica específica - memorize as principais! 🔬🎯","tags":["#DiagnósticoMorfológico","#EsfregaçoSanguíneo","#Hematologia","#Hematoscopia","#PoiquilócitoS","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885747","ankiGuid":"ih8w29BRg>"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-4af2eebe86ce2ebd","number":"1045a","sourceNumber":"1045a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Qual das situações abaixo comumente NÃO é causa de anemia com VCM > 100 fl?","options":{"A":"Abuso de álcool.","B":"Mielodisplasia.","C":"Hipotireoidismo.","D":"Anemia sideroblástica."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão\n\nNível: 🟡 Média (Classificação morfológica das anemias e causas de macrocitose).\n\nResumo Essencial\n\nMacrocitose (VCM >100 fl) pode ser megaloblástica (B12/folato) ou não-megaloblástica (álcool, hipotireoidismo, mielodisplasia). Hipotireoidismo geralmente causa anemia normocítica.\n\nCorreção Direta\n\n✅ Alternativa CORRETA:\n\n\"Hipotireoidismo\":\n\nJustificativa:\n\nHipotireoidismo tipicamente causa anemia normocítica (VCM 80-100 fl).\n\nMecanismo: ↓metabolismo → ↓demanda O₂ → ↓produção eritropoietina.\n\nQuando há macrocitose, geralmente é leve (VCM 100-110 fl), não >100 fl consistentemente.\n\nErros nas Outras Alternativas ❌\n\nAbuso de álcool não causa macrocitose:\n\nIncorreto: Álcool causa macrocitose direta por toxicidade medular (VCM >110 fl).\n\nAnemia sideroblástica não é macrocítica:\n\nIncorreto: Sideroblástica pode ser dimórfica ou macrocítica (defeito síntese heme).\n\nMielodisplasia não causa macrocitose:\n\nIncorreto: Displasia medular → eritroblastos megaloblastóides → VCM >100 fl.\n\nCausas Clássicas de Macrocitose\n\nMegaloblásticas:\n\nB12/Folato → VCM >115 fl + hipersegmentação\n\nNão-megaloblásticas:\n\nÁlcool → VCM 100-110 fl (mais comum)\n\nMielodisplasia → VCM variável + displasia\n\nSideroblástica → VCM >100 fl + sideroblastos em anel\n\nHipotireoidismo vs Macrocitose\n\nMecanismo: ↓T3/T4 → ↓taxa metabólica → ↓necessidade O₂ → ↓EPO\n\nVCM típico: 80-95 fl (normocítica)\n\nSe macrocítica: Geralmente deficiência B12 associada (gastrite atrófica)\n\nMnemônico Útil ✨\n\n\"AMAS\": Alcool, Mielodisplasia, Anemia sideroblástica, Sem hipotireoidismo!\n\nTags Temáticas\n\nDica: Hipotireoidismo = anemia normocítica! Macrocitose vem de álcool, B12/folato, mielodisplasia! 🩸","tags":["#Anemia","#Hematologia","#Hipotireoidismo","#Macrocitose","#VCM","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885748","ankiGuid":"jM]L2![uv,"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-4adb6c97aace1891","number":"1046a","sourceNumber":"1046a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Mulher, 65 anos, portadora de hipotireoidismo por tireoidite de Hashimoto, em uso regular de levotiroxina 150 mcg/dia, com quadro de adinamia progressiva com palidez cutâneo-mucosa ao exame. Ausência de hepatoesplenomegalia ou linfadenopatia. Negava sangramentos. Hemograma evidenciou hemácias de 2.200.000/mm³; hemoglobina de 7,2 g/dl; hematócrito de 36%; leucócitos de 2.200/mm³ e plaquetas de 98.000/mm³. Contagem de reticulócitos de 20.000/mm³. TSH e T4 livre normais. DHL = 1.220 UI/L e bilirrubina indireta de 1,9 mg/dl. Considerando os aspectos descritos, o achado mais provável na hematoscopia desta paciente será:","options":{"A":"Células em lágrima.","B":"Esquizócitos.","C":"Neutrófilos hiperlobulados.","D":"Blastos com bastonetes de Auer.","E":"Corpos de Howell-Jolly."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão\n\nNível: 🔴 Difícil (Diagnóstico diferencial de anemia megaloblástica e morfologia hematológica em contexto clínico complexo).\n\nResumo Essencial\n\nPancitopenia + hemólise (↑DHL, ↑BI) + hipotireoidismo (Hashimoto) + reticulocitose baixa sugerem anemia megaloblástica por deficiência B12 com neutrófilos hipersegmentados.\n\nCorreção Direta\n\n✅ Alternativa CORRETA:\n\n\"Neutrófilos hiperlobulados\":\n\nJustificativa:\n\nTireoidite de Hashimoto → gastrite atrófica → ↓fator intrínseco → deficiência B12.\n\nPancitopenia + hemólise intramedular + reticulocitose inadequada = anemia megaloblástica.\n\nHipersegmentação neutrofílica (>5 lóbulos) é patognomônica da deficiência B12/folato.\n\nErros nas Outras Alternativas ❌\n\nCélulas em lágrima:\n\nContexto: Mielofibrose/infiltração medular - não há hepatoesplenomegalia.\n\nCorpos de Howell-Jolly:\n\nContexto: Hipoesplenismo/asplenia - não há evidência de disfunção esplênica.\n\nEsquizócitos:\n\nContexto: Anemia hemolítica microangiopática - hemólise é intramedular.\n\nBlastos com Auer:\n\nContexto: Leucemia aguda - leucopenia com pancitopenia não sugere.\n\nFisiopatologia da Deficiência B12\n\nHashimoto → gastrite atrófica autoimune → ↓células parietais → ↓fator intrínseco\n\n↓B12 → ↓síntese DNA → eritropoiese ineficaz → hemólise intramedular\n\nMegaloblastos → neutrófilos gigantes hipersegmentados\n\nLaboratório Característico\n\nPancitopenia: Anemia + leucopenia + plaquetopenia\n\nHemólise intramedular: ↑DHL + ↑BI + reticulócitos baixos\n\nVCM elevado (não informado, mas implícito)\n\nHipersegmentação: >5% neutrófilos com >5 lóbulos\n\nAssociação Hashimoto-B12\n\n30-40% dos pacientes com Hashimoto desenvolvem gastrite atrófica\n\nAnticorpos anti-células parietais e anti-fator intrínseco\n\nInvestigar sempre B12 em Hashimoto com anemia\n\nMnemônico Útil ✨\n\n\"HASH-B12\": Hashimoto → Atrófica → Sem fator → Hipersegmentados → B12 baixa!\n\nTags Temáticas\n\nDica: Hashimoto + pancitopenia + hemólise = B12 baixa! Neutrófilos hipersegmentados são patognomônicos! 🔬","tags":["#B12","#Hashimoto","#Hematologia","#Hipersegmentação","#Megaloblástica","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885749","ankiGuid":"camoiSpT$J"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-08940cf2df3aae8f","number":"1047a","sourceNumber":"1047a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Um paciente com palidez e icterícia, que tem ao exame laboratorial: Hb = 9%, reticulócitos > 2, aumento sérico de bilirrubina indireta e bilirrubina direta normal e DHL aumentada, deve ser classificado com anemia:","options":{"A":"Falciforme.","B":"Hemolítica.","C":"Sideroblástica.","D":"Mielodisplásica.","E":"Megaloblástica."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão\n\nNível: 🟢 Fácil (Hematologia – classificação das anemias).\n\nResumo Essencial\n\nAnemia hemolítica cursa com Hb baixa, reticulocitose, aumento de bilirrubina indireta e DHL elevada, com bilirrubina direta normal.\n\nCorreção Direta\n\n✅ Hemolítica\n\nJustificativa:\n\nHemólise → destruição precoce das hemácias → ↑ produção medular (reticulocitose).\n\nCatabolismo da hemoglobina → ↑ bilirrubina indireta e DHL.\n\nBilirrubina direta normal, pois não há obstrução biliar.\n\nErros nas Outras Alternativas ❌\n\nMegaloblástica: Anemia macrocítica com neutrófilos hipersegmentados, não reticulocitose.\n\nMielodisplásica: Produção ineficaz na medula, reticulócitos baixos.\n\nFalciforme: É um tipo de anemia hemolítica específica, mas questão pede classificação geral.\n\nSideroblástica: Distúrbio na síntese do heme, reticulócitos baixos.\n\nFisiopatologia Essencial\n\nHemólise → liberação de Hb → metabolização em biliverdina → bilirrubina indireta → fígado conjuga → direta (normal aqui).\n\nMnemônico Útil ✨\n\n\"Hemólise = Hb baixa + indireta alta + DHL alta + reticulócito alto\".\n\nTags Temáticas\n\nDica: Reticulócitos altos + indireta alta = sempre pense em hemólise ou perda aguda de sangue.","tags":["#AnemiaHemolítica","#Bilirrubina","#Hematologia","#Residência","#Reticulócitos","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885750","ankiGuid":"qU20&v9*K!"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-3710ebc870e85ec0","number":"1048a","sourceNumber":"1048a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"As causas de anemias podem ser diferenciadas em dois grandes grupos de acordo com os mecanismos que dão origem a elas, podendo ser divididas em hipoproliferativas ou hiperproliferativas. Assinale abaixo a assertiva que contém uma causa de anemia hipoproliferativa.","options":{"A":"Esferocitose hereditária.","B":"Anemia carencial.","C":"Hiperesplenismo.","D":"Sangramento agudo evidente."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão\n\nNível: 🟢 Fácil (Hematologia – mecanismos das anemias).\n\nResumo Essencial\n\nAnemias hipoproliferativas ocorrem por baixa produção de hemácias na medula óssea, como nas carenciais (ferro, B12, folato).\n\nCorreção Direta\n\n✅ Anemia carencial\n\nJustificativa:\n\nFalta de substratos essenciais (ex.: ferro) → produção reduzida de hemácias → baixa contagem de reticulócitos.\n\nErros nas Outras Alternativas ❌\n\nHiperesplenismo: Destruição/perda acelerada de hemácias → anemia hiperproliferativa (medula tenta compensar).\n\nEsferocitose hereditária: Hemólise crônica → hiperproliferativa.\n\nSangramento agudo evidente: Perda de sangue → resposta medular aumentada (hiperproliferativa).\n\nFisiopatologia Essencial\n\nHipoproliferativa: problema de produção (ferro, B12, insuficiência renal, aplasia).\n\nHiperproliferativa: perda (sangramento) ou destruição (hemólise).\n\nMnemônico Útil ✨\n\n\"Hipo = Hemácia pouca\" (produção baixa), \"Hiper = Hemácia perdida\" (produção aumentada para compensar).\n\nTags Temáticas\n\nDica: Reticulócitos baixos → hipoproliferativa; reticulócitos altos → hiperproliferativa.","tags":["#Anemias","#Carencial","#Hematologia","#Hipoproliferativa","#Residência","Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885751","ankiGuid":"O)2uFc&@I$"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-8e15215d6a12ffdb","number":"1049a","sourceNumber":"1049a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Paulo, 35 anos, apresenta quadro clínico de anemia. O esfregaço sanguíneo revelou hemácias microcíticas e hipocrômicas. Qual das alternativas abaixo demonstra o mecanismo da anemia?","options":{"A":"Índices hematimétricos, VCM, HCM, CHCM.","B":"Contagem de reticulócitos.","C":"Dosagem da ferritina.","D":"Dosagem da vitamina B12.","E":"Pesquisa do Coombs direto."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885752","ankiGuid":"eDZQ0-y8y0"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-8c412760abc3022a","number":"1050a","sourceNumber":"1050a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Sobre anemias, marque a alternativa INCORRETA.","options":{"A":"AHAI é considerada hipoproliferativa.","B":"Anemia ferropriva é um exemplo de anemia hipoproliferativa.","C":"Anemia megaloblástica é um exemplo de anemia hipoproliferativa.","D":"Na aplasia medular, a medula óssea é substituída por gordura.","E":"As anemias microangiopáticas se caracterizam normalmente por esquizócitos no sangue periférico."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885753","ankiGuid":"Q00;+=2me_"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-c1d905a26a55296d","number":"1051a","sourceNumber":"1051a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Esfregaço periférico de uma mulher de 40 anos revelou a presença de corpos de Howell − Jolly nos eritrócitos. Dos abaixo, o mais provável é haver:","options":{"A":"Presença de hemoglobina C à eletroforese de hemoglobina.","B":"Presença concomitante de esquizócitos.","C":"Antecedente de esplenectomia.","D":"Deficiência de G6PD.","E":"Teste de Coombs positivo."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885754","ankiGuid":"Pv]as)P9}%"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-d47777337abe299a","number":"1052a","sourceNumber":"1052a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Mulher com 76 anos foi admitida na enfermaria com história de um ano de parestesias em membros inferiores. A um mês da internação parou de deambular. No laboratório, apresentava Hb: 8,4 g/dL, VCM: 110 fl, hipersegmentação de neutrófilos e presença de anticorpos anticélulas parietais, o diagnóstico aponta para:","options":{"A":"Anemia perniciosa.","B":"Anemia por deficiência de ácido fólico.","C":"Síndrome mielodisplásica.","D":"Anemia hemolítica autoimune.","E":"Hemoglobinúria paroxística noturna."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885755","ankiGuid":"nYUIZNSmM&"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-de8974a27e560d9f","number":"1053a","sourceNumber":"1053a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"A morfologia da hemácia auxilia no diagnóstico diferencial das anemias. Assinale a alternativa em que ambas as anemias são hipocrômicas e microcíticas:","options":{"A":"Microesferocitose e alfatalassemia.","B":"Anemia ferropriva e betatalassemia.","C":"Talassemia beta e anemia falciforme.","D":"Deficiência de G6PD e anemia ferropriva.","E":"Microesferocitose e deficiência de G6PD."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885756","ankiGuid":"v49H)MJ7?A"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-60dd2f036f86ada5","number":"1054a","sourceNumber":"1054a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Diante de um paciente com anemia normocítica e normocrômica, a primeira consideração é tratar-se de:","options":{"A":"Anemia associada a medicamentos.","B":"Deficiência combinada de ferro e folato.","C":"Talassemia.","D":"Anemia de doença crônica.","E":"Deficiência de cobalamina."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885757","ankiGuid":"Qa!.u&fLz$"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-311b32e1cb603eef","number":"1055a","sourceNumber":"1055a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Mulher, 35 anos, G3P2(C2)A0, idade gestacional = 29 semanas. Refere antecedente de cirurgia bariátrica há 14 meses. Faz pré-natal regularmente, com tratamento para anemia com sulfato ferroso (800 mg/dia) desde a 16ª semana. Exames laboratoriais na 28ª semana de gestação: Hb = 10,5 g/dl; VCM = 110 fl; leucócitos = 3.200/mm³, com presença de neutrófilos hipersegmentados; plaquetas = 150.000/mm³. A causa da anemia é:","options":{"A":"Deficiência de cobalamina.","B":"Deficiência de tiamina.","C":"Deficiência de niacina.","D":"Deficiência de piridoxina."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885758","ankiGuid":"y7Rf[tU_o%"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-9b24ac68993263d9","number":"1056a","sourceNumber":"1056a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Menina de 12 meses, alimentada exclusivamente com leite artificial, tem um exame clínico com palidez acentuada. A avaliação laboratorial mostra uma hemoglobina de 7,0 g/dL, um hematócrito de 25%, aumento significativo de reticulócitos e desidrogenase lática.\n\nQual das propostas abaixo é o diagnóstico mais provável?","options":{"A":"Anemia devido à deficiência de proteína","B":"Anemia por deficiência de ferro.","C":"Anemia devido à deficiência de Vit B12.","D":"Anemia causada por deficiência de ácido fólico.","E":"Anemia hemolítica."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885759","ankiGuid":"y<C!dYnr]d"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-9003d68b7b59ed4c","number":"1057a","sourceNumber":"1057a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Mulher de 30 anos comparece ao seu consultório para um check-up, sem queixas espontâneas significativas. O seu hemograma tem o seguinte resultado: Hemácias 6,5 milhões/mm³; Hemoglobina 9,2g/dl; Hematócrito 42,3%; RDW 14,1%. Qual das seguintes alternativas é mais consentânea com estes achados?","options":{"A":"Este quadro é impossível.","B":"Trata-se de anemia macrocítica.","C":"Os dados são todos perfeitos para o diagnóstico de anemia ferropriva.","D":"Há indicação para hemotransfusão.","E":"É provavelmente o defeito genético mais comum do mundo."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885760","ankiGuid":"E<l3jBYsY&"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-bc16dd02fd3ac4a1","number":"1058a","sourceNumber":"1058a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"O residente avalia o hemograma de paciente de 72 anos no ambulatório, cujos dados mais importantes são: hemoglobina = 8,2 g/dl; reticulócitos = 0,6%; leucócitos = 8.500/dl; plaquetas = 180.000/dl. As doenças que melhor se enquadrariam, nesses dados, são:","options":{"A":"Deficiência de ferro e anemia hemolítica por anticorpos a frio.","B":"Aplasia de medula óssea e anemia microangiopática.","C":"Deficiência de vitamina B12 e mielofibrose.","D":"Esferocitose e insuficiência renal crônica."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885761","ankiGuid":"v$Lbhc{`Gk"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-1da966605423dabf","number":"1059a","sourceNumber":"1059a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Os principias exames laboratoriais indicados para a investigação inicial das anemias são:","options":{"A":"Hemograma e VHS.","B":"Hemograma e reticulócitos.","C":"Reticulócitos e curva de fragilidade osmótica.","D":"Hemograma e eletroforese de hemoglobina."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885762","ankiGuid":"mGh~mQg<%/"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-eb91fba5c4a674a9","number":"1060a","sourceNumber":"1060a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Microcitose caracteriza-se pelo achado de valores abaixo do normal de:","options":{"A":"Hematócrito.","B":"Volume corpuscular médio.","C":"Concentração de hemoglobina.","D":"Hemoglobina corpuscular média."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885763","ankiGuid":"fV)sr6^5zw"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-dfe4b3ffcbf64e5e","number":"1061a","sourceNumber":"1061a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"São causas de anemia com reticulocitopenia, exceto:","options":{"A":"Mielodisplasia.","B":"Deficiência de vitamina B12.","C":"Anemia ferropriva.","D":"Anemia sideroblastica.","E":"Esferocitose hereditária."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885764","ankiGuid":"GggQH#z$W$"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-f517d495bb55abb7","number":"1062a","sourceNumber":"1062a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"A anemia é uma afecção que acomete boa parte da população, em diversas etapas da vida e por diferentes motivos. Sobre esse assunto é correto afirmar que:","options":{"A":"O diagnóstico de anemia é feito quando os valores de hemoglobina estão abaixo de12 g/dl em todos os grupos etários, independente de sexo e de gravidez.","B":"Pode-se afirmar que as principais causas de anemia macrocítica são hemorragias e deficiência de folato.","C":"Anemia microcítica tem como principais causas a deficiência de ferro e hemoglobinopatias.","D":"Oxigenioterapia hiperbárica é opção de tratamento de anemia apenas em crianças.","E":"Quando diagnosticado anemia, não há necessidade de investigação das outras series hematológicas, visto que isso não interferirá no tratamento."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885765","ankiGuid":"D}Htgyk41V"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-00e30b05ffaf3806","number":"1063a","sourceNumber":"1063a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Paciente do sexo feminino, de 40 anos, sem nenhuma patologia de base, realiza um hemograma para uma consulta de rotina e o resultado é o seguinte: Hb 11, Ht 30, Leucócitos 2.500 ( não foi liberado o diferencial) e plaquetas 128.000. Os termos adequados para as alterações laboratoriais apresentadas por essa paciente são:","options":{"A":"Anemia, leucopenia e plaquetose.","B":"Poliglobulia, leucopenia e plaquetose.","C":"Poliglobulia, leucopenia e plaquetopenia.","D":"Anemia, leucopenia e plaquetopenia."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885766","ankiGuid":"oX+Rua<a;H"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-63ed8716749c1454","number":"1064a","sourceNumber":"1064a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Vítima de trauma abdominal, com rotura esplênica há 45 dias, comparece a ambulatório de clínica médica para seguimento de quadro de síndrome metabólica. A presença de corpúsculos de Howell-Jolly, no hemograma trazido pela paciente, permite afirmar que:","options":{"A":"O paciente tem baço acessório ou não foi esplenectomizado.","B":"Trata-se de deficiência de G6PD em paciente esplenectomizado.","C":"O paciente tem deficiência de G6PD.","D":"Houve esplenectomia, e não há baço acessório.","E":"Certamente não houve esplenectomia."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885767","ankiGuid":"bHQfQXPIIk"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-3ca5db46520464ae","number":"1065a","sourceNumber":"1065a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Paciente do sexo masculino, 35 anos, com antecedente de Anemia Falciforme, apresenta no esfregaço de sangue periférico corpúsculos de Howell-Jolly. Assinale abaixo o significado desse achado.","options":{"A":"Crise de falcização.","B":"Processo infeccioso viral.","C":"Hipoesplenismo.","D":"Deficiência de folato."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885768","ankiGuid":"Ci94Ks@nzZ"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-14af2f600fcde0fe","number":"1066a","sourceNumber":"1066a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Jovem de 19 anos é admitido com quadro febril e dores articulares. Realiza hemograma que revela Hb: 9,2 g/dl; Htc: 27%; leucócitos 12.500/mm³ e plaquetas 210.000/mm³, com a lâmina do esfregaço do sangue periférico apresentada abaixo.\n\nO diagnóstico mais provável do caso é:","options":{"A":"malária.","B":"leucemia aguda.","C":"anemia falciforme.","D":"dengue."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":["question_bank/media/hematologia-introducao-ao-estudo-das-anemias/paste-2c704498da015d904212135410e22b414d2c7e1e.jpg"],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885769","ankiGuid":"NJ+jFAbN`B"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-0c8cebd24c1662ee","number":"1067a","sourceNumber":"1067a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Qual das opções abaixo aponta uma forma de anemia a ser considerada no diagnóstico diferencial das anemias microcíticas?","options":{"A":"Anemia aplásica.","B":"Anemia megaloblástica.","C":"Anemia hemolítica autoimune.","D":"Anemia sideroblástica."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885770","ankiGuid":"y=-D=un]05"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-c28c32c8efa7e651","number":"1068a","sourceNumber":"1068a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Analise a foto a seguir, que apresenta um esfregaço de sangue periférico.\n\nQual a alteração encontrada e seu provável significado clínico?","options":{"A":"Hipocromia - Ferropenia.","B":"Rouleaux - Hipergamaglobulinemia.","C":"Esferocitose - Esferocitose hereditária.","D":"Aglutinação - Infecção por Mycoplasma.","E":"Macrocitose - Deficiência de B12."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":["question_bank/media/hematologia-introducao-ao-estudo-das-anemias/paste-5b588bfd9b4c2d1f9d9614be998fd5c333b1a87a.jpg"],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885771","ankiGuid":"lH}WE`FC#L"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-2a09e3d2a7d3b070","number":"1069a","sourceNumber":"1069a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Paciente do sexo masculino apresenta episódio de hemólise. Obseva-se a presença de corpos de Heinz no sangue periférico. O paciente está em uso de dapsona. Assinale a alternativa diagnóstica mais provável:","options":{"A":"Anemia falciforme.","B":"Deficiência de glicose-6-fosfato desidrogenase.","C":"Esferocitose hereditária.","D":"Lupus eritematoso sistêmico.","E":"Deficiência de ácido fólico."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885772","ankiGuid":"<c9!+wX/b"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-8e6b2e18f0466905","number":"1070a","sourceNumber":"1070a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Dois internos analisam o hemograma de uma paciente de 32 anos, antes de avaliar a sua história e exame físico. Hemácias 4,2 M/µl, hematócrito 28%, hemoglobina 9,2 g/dl, concentração de hemoglobina corpuscular média 20,9/dl, volume globular médio 72 fl, hemoglobina corpuscular média 26 pg. A anemia apresentada tende a diminuir, mais provavelmente, a partir da administração de:","options":{"A":"ferro.","B":"ácido fólico.","C":"vitamina B6.","D":"vitamina B12."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885773","ankiGuid":"jeAEobFt.d"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-eb74092fdff86dbe","number":"1071a","sourceNumber":"1071a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Em relação às síndromes anêmicas, ao observarmos volume corpuscular médio alto, devemos considerar como causa possível?","options":{"A":"Doença crônica.","B":"Deficiência de ferro.","C":"Talassemia.","D":"Deficiência de folato.","E":"Intoxicação por chumbo."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885774","ankiGuid":"IsFxGF>%TL"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-22bf0922492adf25","number":"1072a","sourceNumber":"1072a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Considere três pacientes com anemia, além das características abaixo. Paciente\n\nI - TSH superior a 30 mcU/ml. Paciente\n\nII - poliartrite crônica em mãos e rigidez matinal. Paciente\n\nIII - eletroforese de hemoglobina com HbA2 superior a 4%.\n\nAnemias microcítica, normocítica e macrocítica serão encontradas com maior probabilidade, respectivamente, nos pacientes:","options":{"A":"I, III e II.","B":"III, I e II.","C":"I, II e III.","D":"III, II e I.","E":"II, III e I."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885775","ankiGuid":"q`w48YnZ(y"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-af528ee344518a5f","number":"1073a","sourceNumber":"1073a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Paciente do sexo feminino, 35 anos, portadora de Lúpus Eritematoso Sistêmico, apresenta anemia ao hemograma, descartada a possibilidade de hemólise. O Médico atribuiu a alteração como resultado da inflamação crônica. Assinale abaixo o volume corpuscular médio mais provável neste caso.","options":{"A":"60 a 80 fl.","B":"70 a 90 fl.","C":"80 a 100 fl.","D":"90 a 110 fl."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885776","ankiGuid":"N(_mKq|uE;"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-770b959f835ab146","number":"1074a","sourceNumber":"1074a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Na classificação de anemias, podemos definir como diminuição na produção de hemácias, as seguintes situações, com EXCEÇÃO de:","options":{"A":"Anemia aplásica.","B":"Deficiência de vitamina B12.","C":"Deficiência de ferro.","D":"Anemia hemolítica autoimune.","E":"Síndrome mielodisplásica."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885777","ankiGuid":"JR~0e=Wt25"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-3c635433f3d221f2","number":"1075a","sourceNumber":"1075a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Quais das alternativas abaixo reúnem o conjunto de doenças que se manifestam, respectivamente, por anemia hipocrômica e microcítica; anemia normocrômica e normocítica e anemia normocrônica macrocítica?","options":{"A":"talassemia, hipotiroidismo, anemia sideroblástica.","B":"doença celíaca, anemia aplástica, deficiência de ácido fólico.","C":"anemia ferropriva, deficiência de vitamina B12, insuficiência renal crônica.","D":"doença hepática crônica, anemia ferropriva, gastrectomia."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885778","ankiGuid":"Nr*@N;=<st"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-7994d7c6a0f8e1cc","number":"1076a","sourceNumber":"1076a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Microcitose caracteriza-se pelo achado de valores abaixo do normal de:","options":{"A":"hematócrito;","B":"volume corpuscular médio;","C":"concentração de hemoglobina;","D":"ferritina;","E":"hemoglobina corpuscular média."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885779","ankiGuid":"N*Su*r+>o&"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-45c45d66849d96f0","number":"1077a","sourceNumber":"1077a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"A hematoscopia é parte da avaliação do hemograma. Permite observar tamanho e características morfológicas das hemácias, plaquetas e leucócitos, bem como presença e características de células anormais. Algumas alterações são frequentemente encontradas em determinadas doenças ou processos patológicos. Abaixo estão relacionadas algumas dessas associações. Qual delas está ERRADA?","options":{"A":"Corpos de Howell-Jolly e hipofunção ou ausência do baço.","B":"Eritrócitos grandes e ovalados e anemia megaloblástica.","C":"Esferócitos e anemia hemolítica autoimune.","D":"Neutrófilos hipersegmentados e infecção."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885780","ankiGuid":"C],U#)KfsS"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-91e57376498e0d16","number":"1078a","sourceNumber":"1078a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Homem, 48 anos de idade, solteiro, advogado, procura atendimento médico com queixa de fraqueza e falta de ar progressivas há 3 meses. Nas últimas quatro semanas, também notou edema de membros inferiores e palpitações. O exame físico mostrou que o paciente estava bastante descorado e levemente ictérico com parestesia em mãos e pés. A pressão arterial era de 115 x 70 mmHg e o pulso de 94 bpm. O hemograma revelou hemoglobina de 4,4 g/dl, volume corpuscular médio de 117 fl, glóbulos brancos de 2.900/ml com 500 neutrófilos/ml e 2.400 linfócitos/ml, com linfócitos atípicos, 52.000 plaquetas/ml e reticulócitos de 0,3%. No esfregaço do sangue periférico, foram vistas células como abaixo:\n\nO diagnóstico mais provável é:","options":{"A":"leucemia linfoide aguda.","B":"anemia ferropriva.","C":"leucemia mieloide aguda.","D":"anemia perniciosa."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":["question_bank/media/hematologia-introducao-ao-estudo-das-anemias/paste-fa05495ea008a5d7d7de6cda194a78a04e79e209.jpg"],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885781","ankiGuid":"EpTRX)tE,C"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-d946d53f1275c724","number":"1079a","sourceNumber":"1079a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"São causas de anemia microcítica:","options":{"A":"deficiência de ferro, carência de ácido fólico e mielodisplasia.","B":"talassemia, deficiência de ferro e mielodisplasia.","C":"talassemia, anemia da doença crônica e deficiência de vitamina B12.","D":"deficiência de ferro, mielodisplasia e deficiência de cobalamina.","E":"carência de ácido fólico, talassemia e hiperesplenismo."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885782","ankiGuid":"v8sgi6fr7p"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-4bbd8eebe2a9b374","number":"1080a","sourceNumber":"1080a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Um jovem com o diagnóstico de anemia supostamente ferropriva não obteve resposta após o uso, por tempo prolongado, de sulfato ferroso. Com base nessa informação e na morfologia das hemácias:\n\nDentre as opções abaixo, o diagnóstico provável é:","options":{"A":"Anemia hemolítica microangiopática.","B":"Deficiência de ácido fólico.","C":"Drepanocitose.","D":"Talassemia (\"anemia do Mediterrâneo\")."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":["question_bank/media/hematologia-introducao-ao-estudo-das-anemias/paste-8ac45296bc3d6f4addbe7313bbcbbb4a273f1be6.jpg"],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885783","ankiGuid":"iO?Dw%S<&8"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-5bc9efecd86b3ff9","number":"1081a","sourceNumber":"1081a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Gestante de 30 anos, diagnóstico prévio de doença de Crohn, gravidez de 20 semanas, com queixa de perda de apetite, náuseas e vômitos frequentes. Resultado do hemograma: Hb 9,9 g/dL; VCM 100 fL (Fentolitro); leucócitos globais 3.500/mm³, neutrófilos com núcleos hiper segmentados. O diagnóstico mais provável é:","options":{"A":"Anemia aplástica.","B":"Anemia ferropriva.","C":"Anemia hemolítica.","D":"Anemia perniciosa."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885784","ankiGuid":"bj?Toz=4p3"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-7a9e17de0af80496","number":"1082a","sourceNumber":"1082a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"O achado de reticulocitose é frequentemente associado a, exceto:","options":{"A":"Anemias hemolíticas crônicas.","B":"Após hemorragias agudas.","C":"No início da reposição de ferro em pacientes com anemia ferropriva.","D":"Na anemia aplásica.","E":"Durante o tratamento das anemias megaloblásticas."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885785","ankiGuid":"LC<q9y**Td"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-5bd6192fa98e8aaa","number":"1083a","sourceNumber":"1083a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Conceito de anemia na gestação, segundo a OMS (Organização Mundial da Saúde):","options":{"A":"Hemoglobina igual ou abaixo de 11 g/dL.","B":"Hemoglobina igual ou abaixo de 12 g/dL.","C":"Hemoglobina igual ou abaixo de 10 g/dL.","D":"Hemoglobina igual ou abaixo de 9,5 g/dL.","E":"Hemoglobina igual ou abaixo de 10,5 g/dL."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885786","ankiGuid":"b-4YoK<v_L"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-ac94d441251b57c3","number":"1084a","sourceNumber":"1084a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Assinale a alternativa correta entre a associação de achado hematoscópico com o respectivo significado clínico:","options":{"A":"Formação de Rouleaux; infecção crônica.","B":"Esquizócitos; anemia hemolítica microangiopática.","C":"Hipossegmentação nuclear leucocitária; anemia megaloblástica.","D":"Granulações tóxicas neutrofílicas; saturnismo.","E":"Mieloblastos; leucemia linfoblástica aguda."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885787","ankiGuid":"s}RT|Uj$9_"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-7f4d07598b8626a9","number":"1085a","sourceNumber":"1085a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Na avaliação inicial diagnóstica de paciente com Anemia e contagem de reticulócitos não elevada, devemos considerar no diagnóstico diferencial o valor do Volume Corpuscular Médio (VCM) ou volume celular. Assinale a alternativa CORRETA:","options":{"A":"Se o VCM é normal, o paciente pode ter aplasia da medula óssea.","B":"Se o VCM é baixo, o paciente pode ter deficiência de vitamina B12.","C":"Se o VCM é baixo, o paciente pode ter deficiência de folato.","D":"Se o VCM é alto, o paciente pode ter deficiência de ferro.","E":"Se o VCM é alto, o paciente pode ter traço talassêmico."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885788","ankiGuid":"tR:>Ey*Y5d"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-81015dd0dc76f0e9","number":"1086a","sourceNumber":"1086a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Em um paciente portador de anemia com VCM = 114 fL a presença de neutrófilos hipersegmentados aponta para o diagnóstico de anemia","options":{"A":"da doença crônica.","B":"por deficiência de vitamina B12 e/ou de folato.","C":"por deficiência de vitamina B12 apenas.","D":"por deficiência de folato apenas.","E":"por mielodisplasia."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885789","ankiGuid":"POWbmZnhs0"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-a42331949ba6d1a6","number":"1087a","sourceNumber":"1087a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Associe as alterações laboratoriais (coluna 1) às situações clínicas em que ocorrem (coluna 2).\n\nCOLUNA 1\n\n1 - VCM baixo, RDW elevado, reticulócitos corrigidos < 2%.\n\n2 - VCM baixo, RDW normal, reticulócitos corrigidos ≥ 2%.\n\n3 - VCM normal ou baixo, RDW normal, reticulócitos corrigidos < 2%.\n\n4 - VCM elevado, RDW elevado, reticulócitos corrigidos < 2%. 5- VCM elevado, RDW elevado, reticulócitos corrigidos ≥ 2%.\n\nCOLUNA 2\n\n( ) paciente com anemia e Coombs direto positivo, icterícia e esplenomegalia.\n\n( ) paciente com pancitopenia e gastrite atrófica.\n\n( ) paciente com anemia hereditária e hemoglobina A2 aumentada.\n\nA sequência numérica correta, de cima para baixo, da coluna 2, é:","options":{"A":"2 - 4 - 5","B":"4 - 1 - 3","C":"4 - 5 - 2","D":"5 - 1 - 3","E":"5 - 4 - 2"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885790","ankiGuid":"AqJjo5nNLH"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-a836917a0567c222","number":"1088a","sourceNumber":"1088a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"A anemia por deficiência de ferro caracteriza-se por ser:","options":{"A":"Hipocrômica e macrocítica.","B":"Normocrômica e macrocítica.","C":"Hipocrômica e microcítica.","D":"Normocrômica e normocítica.","E":"Normocrômica e microcítica."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885791","ankiGuid":"nmZE@_!8S*"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-ab14c30fbfc9ff1a","number":"1089a","sourceNumber":"1089a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Qual o provável diagnóstico para homem, 47 anos, em investigação de anemia que apresente reticulócitos diminuídos e volume corpuscular médio elevado?","options":{"A":"Talassemia.","B":"Esferocitose.","C":"Anemia perniciosa.","D":"Anemia hemolítica autoimune.","E":"Deficiência de G6PD."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885792","ankiGuid":"oKTqK4VP%|"},{"id":"anki-hematologia-introducao-ao-estudo-das-anemias-26764f8e5a121121","number":"1090a","sourceNumber":"1090a","collectionBlock":"anki:hematologia-introducao-ao-estudo-das-anemias","collectionLabel":"Anki · Introdução ao Estudo das Anemias","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Introdução ao Estudo das Anemias","subtopic":"","stem":"Para um paciente cujo esfregaço de sangue periférico apresente macrocitose e hipersegmentação de neutrófilos, qual das condições abaixo não deve ser considerada?","options":{"A":"Uso crônico de bloqueador de bomba protônica.","B":"História prévia de cirurgia bariátrica.","C":"Doença de Crohn.","D":"Intoxicação por chumbo."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Introdução ao Estudo das Anemias","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Introdução ao Estudo das Anemias","Anki"],"ankiNoteId":"1742992885793","ankiGuid":"Ky&hPo0h:<"}]};
